```java
import org.apache.commons.lang3.StringUtils;
import com.example.pokemon.*;

public class PokemonReportGenerator {
    private TypeLibrary typeLib;
    private DataAccessLayer dataAccessLayer;

    public PokemonReportGenerator(TypeLibrary typeLib, DataAccessLayer dataAccessLayer) {
        this.typeLib = typeLib;
        this.dataAccessLayer = dataAccessLayer;
    }

    public String generatePokemonReport(String pokemonName) throws Exception {
        if (StringUtils.isBlank(pokemonName)) {
            throw new IllegalArgumentException("Pokemon name cannot be blank");
        }

        PokemonData pokemon = dataAccessLayer.getPokemonData(pokemonName);

        if (pokemon == null) {
            throw new Exception("Could not find the requested Pokemon in our database!");
        }

        StringBuilder report = new StringBuilder();

        report.append("Report for ").append(pokemon.getName()).append("\n");

        // Check each type and append weaknesses/resistances
        for (TypeData type : pokemon.getTypes()) {
            TypeInfo typeInfo = typeLib.getTypeInfo(type);

            report.append("Type: ").append(type.getName()).append("\n");
            report.append("Weaknesses: ").append(StringUtils.join(typeInfo.getWeaknesses(), ", ")).append("\n");
            report.append("Resistances: ").append(StringUtils.join(typeInfo.getResistances(), ", ")).append("\n");
        }

        return report.toString();
    }
}
```
