["Below is a basic example of how you could implement a function in C that retrieves cryptographic hash functions and block ciphers from an existing cryptography library:

```c
#include <openssl/evp.h>
#include <assert.h>

typedef struct {
    const EVP_MD *(*getDigestByIndex)(int);
    const char* (*nameOfDigest)(const EVP_MD *);
} DigestFunctions;

static const EVP_MD *opensslGetDigestByIndex(int nid) {
    return EVP_get_digestbynid(nid);
}

static const char* opensslNameOfDigest(const EVP_MD *md) {
    assert(md != NULL); // verify that the digest is correctly initialized
    return OBJ_nid2ln(EVP_MD_type(md));
}

DigestFunctions getOpenSSLDigestFunctions() {
    DigestFunctions functions;
    functions.getDigestByIndex = opensslGetDigestByIndex;
    functions.nameOfDigest = opensslNameOfDigest;
    return functions;
}
```
This code retrieves the list of available cryptographic hash functions and block ciphers from the OpenSSL library, by using its API conventions to get the digest by its index number, and then it verifies that each entry is correctly initialized. 

