typedef struct {
    sem_t sem;
    int in_use; //flag to check if this sem is being used currently
} SemaphoreInfo;

SemaphoreInfo semaphores[MAX_SEMS];
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* create_sem(void* arg) {
    int semIdx = *((int*)arg); //getting the index of the semaphore to be created

    pthread_mutex_lock(&lock);
    if (semaphores[semIdx].in_use == 0) {
        sem_init(&(semaphores[semIdx].sem), 0, rand() % MAX_VALUE + 1); //initial value between 1 and MAX_VALUE
        semaphores[semIdx].in_use = 1;
    } else {
        printf("Semaphore at index %d is already in use!\n", semIdx);
    }
    pthread_mutex_unlock(&lock);

    return NULL;
}

void* delete_sem(void* arg) {
    int semIdx = *((int*)arg); //getting the index of the semaphore to be deleted

    pthread_mutex_lock(&lock);
    if (semaphores[semIdx].in_use == 1) {
        sem_destroy(&(semaphores[semIdx].sem));
        semaphores[semIdx].in_use = 0;
    } else {
        printf("Semaphore at index %d is not in use!\n", semIdx);
    }
    pthread_mutex_unlock(&lock);

    return NULL;
}

// Function to list the semaphores. For simplicity, it just prints their status (in_use or not)
void list_sems() {
    for(int i=0; i<MAX_SEMS; ++i) {
        printf("Semaphore %d: %s\n", i, semaphores[i].in_use ? "in use" : "not in use");
    }
}
``` 

This code defines a `SemaphoreInfo` structure to hold information about each semaphore (the actual semaphore and a flag indicating if it is currently in use). A thread-safe mechanism for creating, deleting, and listing semaphores is also provided.

You will need to implement additional functionalities like locking mechanisms, concurrent access handling, error handling etc based on the requirements of your system. Also, you may want to optimize the way you manage these semaphores (for example, using a data structure other than an array), especially if you plan to have many operations or many semaphores simultaneously. 

Lastly, keep in mind that this is just a simple starting point and does not take into account all the possible issues such as memory fragmentation, race conditions etc. The actual implementation could be quite complex and would require a good understanding of system level programming and concurrency control.
']

