Due to this complexity, I'll provide an example using Node.js with Express for the HTTP server, JSON schema validation with AJV, caching with memory-cache, conflict resolution with a simple last-write-wins strategy, logging service integration with Winston, rate limiting with express-rate-limit, conditional updates with Mongoose's query builder, streaming support with Stream and async/await for handling large payloads, partial updates using Mongoose's `findOneAndUpdate` method, external data source error handling with axios, and optimization techniques using indexes in MongoDB.

Please note that this is just an example, you would need to adapt it based on your specific use case and infrastructure.

```javascript
const express = require('express');
const Ajv = require('ajv');
const cache = require('memory-cache');
const { createLogger, transports, format } = require('winston');
const rateLimit = require('express-rate-limit');
const mongoose = require('mongoose');
const axios = require('axios');
const Stream = require('stream');
require('dotenv').config();

// Initialize Express server
const app = express();
app.use(express.json());

// JSON schema for data validation
const ajv = new Ajv({ allErrors: true });
const updateSchema = { ... }; // Define your resource update schema
const validateUpdate = ajv.compile(updateSchema);

// Winston logger for logging operations
const logger = createLogger({
  level: 'info',
  format: format.json(),
  transports: [ new transports.Console() ]
});

// Express-rate-limit middleware for rate limiting
const limiter = rateLimit({ ... }); // Define your rate limit options
app.use(limiter);

// Mongoose model representing the resource
const ResourceModel = mongoose.model('Resource', new mongoose.Schema({...})); // Define your resource schema

// Cache for frequently accessed resources
let cacheMiddleware = (req, res, next) => {
  let key = `__express__${req.originalUrl}` || req.url;
  let cachedBody = cache.get(key);
  if (cachedBody) {
    res.send(cachedBody);
  } else {
    res.sendResponse = res.send;
    res.send = (body) => {
      cache.put(key, body, process.env.CACHE_EXPIRY || 1000 * 60 * 60); // Cache expiry in ms
      res.sendResponse(body);
    };
    next();
  }
};
app.use(cacheMiddleware);

// HTTP PUT route for updating a resource
app.put('/resources/:id', async (req, res) => {
  const valid = validateUpdate(req.body);
  if (!valid) return res.status(400).send({ errors: validateUpdate.errors });

  try {
    // Find the resource and update it with last-write-wins strategy
    let updatedResource = await ResourceModel.findOneAndUpdate(
      { _id: req.params.id }, 
      req.body, 
      { new: true }
    );

    logger.log({ level: 'info', message: `Resource ${req.params.id} updated` });

    res.status(200).send(updatedResource);
  } catch (error) {
    // Handle conflict resolution, error logging and return to client
    logger.log({ level: 'error', message: error.message });
    res.status(500).send(`Error updating resource ${req.params.id}: ${error}`);
  }
});

// HTTP DELETE route for deleting a resource
app.delete('/resources/:id', async (req, res) => {
  try {
    // Delete the resource from MongoDB and external data sources if needed

    logger.log({ level: 'info', message: `Resource ${req.params.id} deleted` });

    res.status(204).send();
  } catch (error) {
    // Handle error logging and return to client
    logger.log({ level: 'error', message: error.message });
    res.status(500).send(`Error deleting resource ${req.params.id}: ${error}`);
  }
});
```
