```javascript
const fs = require('fs').promises;
const glob = require('glob');
const Ajv = require('ajv');
const ajv = new Ajv();

async function processFiles(directory, schema, callback) {
  try {
    const files = await glob(`${directory}/*`);

    for (let file of files) {
      let content;

      try {
        content = await fs.readFile(file, 'utf8');
      } catch (error) {
        callback(null, error);
        continue;
      }

      let valid;

      try {
        valid = ajv.validate(schema, content);
      } catch (error) {
        callback(null, error);
        continue;
      }

      if (!valid) {
        const errors = ajv.errorsText();
        callback({ file, status: 'failed', errors });
      } else {
        callback({ file, status: 'passed' });
      }
    }
  } catch (error) {
    callback(null, error);
  }
}
```
In this code, we use the `fs` and `glob` modules to read files from a directory asynchronously. We also utilize Ajv, a highly efficient JSON Schema validator, to validate each file against a specified schema. If any operation fails, it will be caught and handled appropriately. The `callback` function provides detailed feedback for each processed file.

For logging errors and performance metrics, you could integrate with an existing logging library or create your own simple logging system. For integrating with third-party services, you might want to use a service provider like AWS Lambda or Google Cloud Functions which allow the execution of JavaScript code in response to triggers (like uploading a file).

