```java
import java.util.*;
import java.io.*;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class AnagramCalculator {
    private static final Logger logger = LoggerFactory.getLogger(AnagramCalculator.class);

    // This is the configuration option to enable or disable logging
    private boolean logEnabled;

    public void setLoggingEnabled(boolean enabled) {
        this.logEnabled = enabled;
    }

    public int calculateUniqueAnagrams(List<String> strings) {
        Map<String, List<String>> anagramGroups = new HashMap<>();

        for (String str : strings) {
            char[] chars = str.toCharArray();
            Arrays.sort(chars);
            String sortedStr = new String(chars);

            if (!anagramGroups.containsKey(sortedStr)) {
                anagramGroups.put(sortedStr, new ArrayList<>());
            }

            anagramGroups.get(sortedStr).add(str);
        }

        for (List<String> group : anagramGroups.values()) {
            if (logEnabled) {
                long startTime = System.currentTimeMillis();

                // Logging the processing time in milliseconds for each input string
                logger.info("Processed strings: " + group);
                logger.info("Processing time: " + (System.currentTimeMillis() - startTime) + "ms");
            }
        }

        return anagramGroups.size();
    }
