```python
import os
import time
import threading
from queue import Queue
from PIL import Image

class ThemeCacheManager:
    def __init__(self, max_cache=50, timeout=10*60):
        self.theme_cache = {}
        self.max_cache = max_cache
        self.timeout = timeout
        self.logger = open('logfile.txt', 'a')  # Log file to record changes
        self.data_source = None  # External data source, should provide a get_theme(id) method

    def set_default_dir(self, dir):
        if os.path.isdir(dir):
            self.default_dir = dir
        else:
            raise ValueError("Invalid directory")

    def fetch_theme_from_source(self, id):
        return self.data_source.get_theme(id) if self.data_source is not None else None

    def load_theme(self, theme_id):
        # Check in cache first
        if theme_id in self.theme_cache:
            cached_theme = self.theme_cache[theme_id]
            if time.time() - cached_theme['last_access'] < self.timeout:
                return cached_theme['image']
            else:
                del self.theme_cache[theme_id]  # Remove from cache and load again
        # Load from source or fallback directory
        theme = self.fetch_theme_from_source(theme_id)
        if theme is None:
            try:
                theme = Image.open(os.path.join(self.default_dir, f"{theme_id}.png"))
            except Exception as e:
                raise ValueError("Failed to load theme") from e

        self.theme_cache[theme_id] = {'image': theme, 'last_access': time.time()}
        if len(self.theme_cache) > self.max_cache:  # Remove oldest entry when cache is full
            oldest_entry = min(self.theme_cache, key=lambda k: self.theme_cache[k]['last_access'])
            del self.theme_cache[oldest_entry]
        return theme

    def log_change(self, user_id, theme_id):
        self.logger.write(f"User {user_id} changed to theme {theme_id} at {time.ctime()}\n")
```

