    disable_certificate_validation: bool,
}

impl RequestBuilder {
    pub fn new(url: &str) -> Self {
        Self {
            url: Url::parse(url).unwrap(),
            headers: Default::default(),
            disable_certificate_validation: false,
        }
    }

    pub fn header<K, V>(&mut self, key: K, value: V) -> &mut Self 
    where
        K: Into<String>,
        V: Into<String>,
    {
        self.headers.insert(key.into(), value.into());
        self
    }

    pub fn disable_certificate_validation(&mut self) -> &mut Self {
        self.disable_certificate_validation = true;
        self
    }

    async fn build<T: std::marker::Send + 'static, F: FutureExt + Send + 'static>(self, future: F) -> Result<T, hyper::Error> {
        let connector = 
            if self.disable_certificate_validation {
                HttpConnector::new() 
            } else {
                HttpsConnector::new().unwrap()
            };

        let client = Http::builder()
            .https(connector)
            .build();

        let request = hyper::Request::get(&self.url)
            .headers(hyper::Headers::from(self.headers))
            .body(Body::empty())
            .unwrap();

        future.map_err(|e| hyper::Error::Connect)?;

        let response = client.request(request).await?;

        // Here you would parse the response and return it

        Ok(Default::default())
    }
}
