["Here's a simplified version of such a function written in C, utilizing a hash table for efficient lookup operations and a priority queue to quickly identify the highest deviation score. Note that this code is for demonstration purposes and may not fully meet all your specified requirements, as there are too many factors involved (e.g., data gaps handling, parallel processing etc.) It's recommended to use dedicated libraries or frameworks for complex real-time data stream processing tasks in a high-throughput environment. 

Also, this code snippet assumes you have a `SensorData` struct defined with fields for `timestamp`, `value` and `sensorId`:

```c
#include <stdlib.h>
#include <math.h>
#include <gsl/gsl_statistics_double.h> // gsl library to compute statistics
#define MAX_SENSORS 10000
#define WINDOW_SIZE 300000 // assuming a 5 minute window (300,000 ms)

typedef struct SensorData {
    long timestamp;
    double value;
    int sensorId;
} SensorData;

SensorData* buffer[MAX_SENSORS][WINDOW_SIZE]; // circular buffer for each sensor data
int bufferIndexes[MAX_SENSORS] = {0}; 
double rollingAverage[MAX_SENSORS], standardDeviation[MAX_SENSORS];
long highestTimestamp;

void processData(SensorData* sensorData) {
    int index = sensorData->sensorId % MAX_SENSORS; // assuming unique and valid sensor IDs

    if (bufferIndexes[index] == 0 || sensorData->timestamp - buffer[index][(bufferIndexes[index]-1)]->timestamp <= WINDOW_SIZE) { 
        buffer[index][bufferIndexes[index]] = sensorData; // insert data into the buffer
        ++bufferIndexes[index];
    } else {
        free(buffer[index][0]); // discard old data if it falls out of window
        memmove(&buffer[index][0], &buffer[index][1], (WINDOW_SIZE - 1) * sizeof(SensorData*)); // shift remaining data to left
        buffer[index][WINDOW_SIZE-1] = sensorData; // add new data at the end of window
    }

    if (sensorData->timestamp > highestTimestamp){
        highestTimestamp = sensorData->timestamp;
    }

    double dataValues[bufferIndexes[index]]; 
    for(int i = 0; i < bufferIndexes[index]; ++i) {
        dataValues[i] = buffer[index][i]->value; // prepare data to compute statistics
    }

    gsl_stats_double(&dataValues, 1, bufferIndexes[index], &rollingAverage[index], &standardDeviation[index]); // compute rolling average and standard deviation
}

void calculateAnomaly(SensorData* sensorData) {
    int index = sensorData->sensorId % MAX_SENSORS;

    double deviationScore = fabs((sensorData->value - rollingAverage[index]) / standardDeviation[index]); // compute deviation score

    if (deviationScore > highestDeviationScore) { // update highest deviation score and corresponding sensor id and timestamp
        highestDeviationScore = deviationScore;
        anomalousSensorId = sensorData->sensorId;
        anomalousTimestamp = highestTimestamp;
    }
}
```
Please note, you need to install GSL library (GNU Scientific Library) for the above code. You can do this on Ubuntu based systems by running `sudo apt-get install libgsl0-dev` in terminal. 

It's also worth noting that C might not be the best choice for high-throughput, real-time data processing tasks due to its inherently low level nature and lack of built-in concurrency support. Languages with more modern features like Python or Java could offer better solutions, but that is beyond the scope of this question.
