['```csharp
using System;
using System.Collections.Generic;

public class DynamicValueGenerator {
    private float min = 0f;
    private float max = 1f;
    private int intMin = 0;
    private int intMax = 1;
    private Dictionary<float, int> floatGenerationCount = new Dictionary<float, int>();
    private Dictionary<int, int> intGenerationCount = new Dictionary<int, int>();

    public float GenerateFloat(float inclusiveMin, float inclusiveMax, bool exclusiveMax) {
        if (exclusiveMax && inclusiveMax == max) inclusiveMax -= float.Epsilon;

        var range = inclusiveMax - min;
        var randomValue = min + ((float)new Random().NextDouble() * range);
        TrackGenerationCount(randomValue);

        return randomValue;
    }

    public int GenerateInt(int inclusiveMin, int inclusiveMax, bool exclusiveMax) {
        if (exclusiveMax && inclusiveMax == max) inclusiveMax -= 1;

        var range = inclusiveMax - min;
        var randomValue = min + new Random().Next() % range;
        TrackGenerationCount(randomValue);

        return randomValue;
    }

    public void SetRange(float min, float max) {
        if (min >= max) throw new ArgumentException("Min cannot be equal or greater than Max");
        this.min = min;
        this.max = max;
    }

    public void SetRange(int min, int inclusiveMax) {
        if (min >= inclusiveMax) throw new ArgumentException("Min cannot be equal or greater than Max");
        this.intMin = min;
        this.intMax = inclusiveMax;
    }

    public void ResetRange() {
        SetRange(0f, 1f);
        SetRange(0, 1);
    }

    private void TrackGenerationCount<T>(T value) {
        if (typeof(T) == typeof(float)) {
            floatGenerationCount.TryGetValue((float)(object)value, out int count);
            floatGenerationCount[(float)(object)value] = count + 1;
        } else if (typeof(T) == typeof(int)) {
            intGenerationCount.TryGetValue((int)(object)value, out int count);
            intGenerationCount[(int)(object)value] = count + 1;
        }
    }

    public override string ToString() {
        return $"Float range: [{min}, {max})  Int range: [{intMin}, {intMax}]";
    }
}
```
