```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define structure to hold bitmap data and theme directory
typedef struct {
    char *bitmaps;  // Bitmap data, could be replaced with appropriate type
    char *directory; // Directory for the theme
} ThemeCache;

ThemeCache cache[1024];  // Maximum number of theme caches you want to support
