// Function for parsing each line
void processLine(char *line) {
    char *token;
    double sum = 0.0, avg = 0.0;
    int count = 0;

    token = strtok(line, ","); // Split string by comma
    while (token != NULL) {
        if (isdigit(*token)) {  // Check if the token is a number
            double num = atof(token);
            sum += num;
            count++;
            if (count > 2) { // Keep only last two numbers in sum
                sum -= avg;
            } else {
                avg = sum / count;
            }
        }
        token = strtok(NULL, ",");  // Get next token
    }

    if (count > 1) {
        asprintf(&line, "%s,%f", line, avg); // Append average to the end of the line
    } else {
        asprintf(&line, "%s,N/A", line);  // If less than two numbers, append N/A
    }
}

// Function for processing large text file
void processFile(FILE *file) {
    char *line = NULL;
    size_t len = 0;

    while (getline(&line, &len, file) != -1) { // Read each line from the file
        processLine(line);  // Process each line
    }
}
```

