    TIFFClose(tif);
}

unsigned char* computeMD5Hash(const unsigned char *data, size_t length) {
    unsigned char *md5Result = (unsigned char*)malloc(16); // MD5 is 128 bit or 16 byte

    if (!md5Result) {
        printf("Failed to allocate memory for MD5 hash.\n");
        return NULL;
    }

    memset(md5Result, 0, 16); // Initialize the memory with zeroes
    MD5(data, length, md5Result);

    return md5Result;
}
