#include <ctype.h>

void modify_filename(char *directory, char *filename) {
    const char extension[] = ".dat";

    int length = strlen(filename);
    if (length > 255 - strlen(extension)) {  // check filename length with max allowed
        printf("Filename exceeds maximum length limit\n");
        return;
    }

    char new_filename[256] = "";
    strcat(new_filename, directory);

    int vowel_count = 0;
    for (int i = 0; filename[i]; ++i) {  // count vowels in filename
        if (strchr("AEIOUaeiou", filename[i])) {
            vowel_count++;
        }
    }

    char *dot = strrchr(filename, '.');  // check if file has an extension
    size_t fnlen = (dot ? dot - filename : length) + 1;
    strncat(new_filename, filename, fnlen);  // append filename without extension or entire filename

    if (dot && !strcmp(dot, extension)) {  // if file has .dat extension
        new_filename[fnlen - strlen(extension)] = '\0';  // remove old extension
    }
    sprintf(&new_filename[strlen(new_filename)], "%d.new", vowel_count);  // append new extension and vowel count

    printf("New filename: %s\n", new_filename);
}
