    if (conversionResult != SUCCESS) {
        printf("Error: Failed to convert JPEG to PDF.\n");
        return ERROR_CONVERSION_FAILED;
    }

    // Read binary data from metadataJsonFilePath
    FILE *file = fopen(metadataJsonFilePath, "rb"); 
    if (file == NULL) {
      printf("Error: Failed to open file.\n");
      return ERROR_DESERIALIZATION_FAILED;
    }

    // Get the size of the binary data
    fseek(file, 0L, SEEK_END);
    long numbytes = ftell(file);

    // Allocate memory for the binary data
    unsigned char *buffer = (unsigned char*)calloc(numbytes + 1, sizeof(char));  

    // Read binary data 
    fseek(file, 0L, SEEK_SET);	
    fread(buffer, sizeof(char), numbytes, file);
    fclose(file);

    // Use a third-party library to deserialize the byte array
    void *deserializedObject = NULL;
    int deserializeResult = deserialize(buffer, &deserializedObject);

    if (deserializeResult != SUCCESS) {
        printf("Error: Failed to deserialize object.\n");
        return ERROR_DESERIALIZATION_FAILED;
    }

    // Free memory 
    free(buffer);

    return SUCCESS;
}
