```java
import java.io.*;
import org.apache.commons.exec.*;
import java.nio.file.*;
import java.time.LocalDateTime;
import java.util.concurrent.TimeUnit;

public class DynamicCommandExecutor {
    private static final int MAX_RETRY = 5;
    private static final long INITIAL_DELAY = 1000L; // in milliseconds

    public void executeWithRetry(String command, String workingDir) throws IOException {
        File dir = new File(workingDir);
        CommandLine cmdLine = CommandLine.parse(command);

        for (int i = 1; i <= MAX_RETRY; ++i) {
            int exitCode = executeCommand(cmdLine, dir);

            if (exitCode == 0) { // success
                backupConfig(); 
                return;
            } else {
                try {
                    TimeUnit.MILLISECONDS.sleep(INITIAL_DELAY * i);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    throw new RuntimeException("Retry interrupted", e);
                }
            }
        }

        rollbackConfig(); // if all retries fail, roll back changes
    }

    private int executeCommand(CommandLine cmdLine, File workingDir) {
        DefaultExecutor executor = new DefaultExecutor();
        executor.setWorkingDirectory(workingDir);
        ByteArrayOutputStream stdout = new ByteArrayOutputStream();
        ByteArrayOutputStream stderr = new ByteArrayOutputStream();

        PumpStreamHandler psh = new PumpStreamHandler(stdout, stderr);
        executor.setStreamHandler(psh);

        try {
            int exitCode = executor.execute(cmdLine);
            System.out.println("Exit code: " + exitCode);

            String outputStr = stdout.toString();
            if (!outputStr.isEmpty()) {
                System.out.println("Output: " + outputStr);
            }

            String errorStr = stderr.toString();
            if (!errorStr.isEmpty()) {
                System.err.println("Error: " + errorStr);
            }

            return exitCode;
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }

    private void backupConfig() throws IOException {
        Path source = Paths.get("config.properties");

        String timestampStr = LocalDateTime.now().toString();
        Path target = Paths.get(source.getParent().toString(), "backup_" + timestampStr + ".properties");
        Files.copy(source, target);
    }

    private void rollbackConfig() {
        // This is a placeholder function. Actual implementation may depend on how your configuration files are managed and backed up
    }
}
```
Note: This code assumes that the command being executed doesn't require input or environment variables, and it just prints its output to standard out/error. In real-world scenarios, you might need to deal with other potential issues such as handling inputs, setting environments etc. 

Also, remember to include Apache Commons Exec library in your build configuration or add it to the classpath when running this code. This is a simple demonstration of how you can handle command execution and retry logic. You'll likely need to adjust this code to fit your specific use case and requirements.
