```csharp
using System;
using System.Text;
using System.Threading.Tasks;
using System.Security.Cryptography;

public class SecureMessageHandler
{
    private byte[] key = null;
    private byte[] iv = null;

    public async Task<string> EncryptMessageAsync(string plainText)
    {
        using (TripleDES des3 = TripleDES.Create())
        {
            des3.Key = this.key;
            des3.IV = this.iv;
            ICryptoTransform encryptor = des3.CreateEncryptor();

            byte[] plainTextBytes = Encoding.UTF8.GetBytes(plainText);
            byte[] cipherTextBytes = await Task.Run(() => TransformMessage(encryptor, plainTextBytes));

            return Convert.ToBase64String(cipherTextBytes);
        }
    }

    public async Task<string> DecryptMessageAsync(string base64CipherText)
    {
        using (TripleDES des3 = TripleDES.Create())
        {
            des3.Key = this.key;
            des3.IV = this.iv;
            ICryptoTransform decryptor = des3.CreateDecryptor();

            byte[] cipherTextBytes = Convert.FromBase64String(base64CipherText);
            byte[] plainTextBytes = await Task.Run(() => TransformMessage(decryptor, cipherTextBytes));

            return Encoding.UTF8.GetString(plainTextBytes);
        }
    }

    private byte[] TransformMessage(ICryptoTransform transform, byte[] input)
    {
        using (MemoryStream memoryStream = new MemoryStream())
        {
            using (CryptoStream cryptoStream = new CryptoStream(memoryStream, transform, CryptoStreamMode.Write))
            {
                cryptoStream.Write(input, 0, input.Length);
                cryptoStream.FlushFinalBlock();

                return memoryStream.ToArray();
            }
        }
    }

    public void LoadEncryptionParameters()
    {
        // Retrieve key and IV from a secure store or environment variables
        // This is simplified for this example, real implementation would need to handle errors, encryption versioning etc
        string keyFromSecureStore = Environment.GetEnvironmentVariable("KEY");
        string ivFromSecureStore = Environment.GetEnvironmentVariable("IV");

        ValidateKeyAndIvLengths(keyFromSecureStore, ivFromSecureStore);

        this.key = Encoding.ASCII.GetBytes(keyFromSecureStore);
        this.iv = Encoding.ASCII.GetBytes(ivFromSecureStore);
    }

    private void ValidateKeyAndIvLengths(string key, string iv)
    {
        if (key.Length != 24 || iv.Length != 8)
        {
            throw new ArgumentException("Invalid Key/IV length");
        }
    }
}
