    private static readonly ThirdPartyChecksumLibrary _checksumCalculator = new ThirdPartyChecksumLibrary();

    public static CustomDataStructure LoadAndDeserialize(string filePath, int expectedVersion)
    {
        try
        {
            using (var fileStream = File.OpenRead(filePath))
            {
                var customObject = (CustomDataStructure)_binaryFormatter.Deserialize(fileStream);

                if (customObject.Version != expectedVersion)
                {
                    throw new InvalidOperationException("Unsupported version of the binary file.");
                }

                // Checksum verification
                var actualChecksum = _checksumCalculator.ComputeChecksum(fileStream);
                var expectedChecksum = LoadExpectedChecksumFromStorage();

                if (actualChecksum != expectedChecksum)
                {
                    throw new InvalidOperationException("Data integrity validation failed.");
                }

                return customObject;
            }
        }
        catch (IOException ex)
        {
            Logger.LogError($"An IO error occurred while loading the file: {ex}");
        }
        catch (SerializationException ex)
        {
            Logger.LogError($"A serialization exception occurred: {ex}");
        }
        catch (Exception ex)
        {
            Logger.LogError($"An unexpected error occurred: {ex}");
        }

        return null;
    }

    private static string LoadExpectedChecksumFromStorage()
    {
        // This would be a database call or file read operation to fetch the expected checksum from storage. 
        // Implementation is omitted here for simplicity
        throw new NotImplementedException();
    }
}
