            String cacheSizeStr = System.getProperty(CACHE_SIZE);
            cacheSize = Integer.parseInt(cacheSizeStr);
        } catch (Exception e) {
            cacheSize = DEFAULT_CACHE_SIZE;
        }

        // Define allowed classes here 
        allowedClasses.add(Class1.class);
        allowedClasses.add(Class2.class);
    }

    public Object deserialize(byte[] data) {
        ByteArrayInputStream bis = new ByteArrayInputStream(data);
        try (ObjectInputStream in = new ObjectInputStream(bis)) {
            Object obj = in.readObject();

            if (!allowedClasses.contains(obj.getClass())) {
                throw new IllegalArgumentException("Unauthorized deserialization of class " + obj.getClass());
            }

            String cacheKey = SerializationUtils.serialize(obj).toString();
            Object cachedObj = cache.computeIfAbsent(cacheKey, k -> {
                try (ByteArrayInputStream bis2 = new ByteArrayInputStream(data);
                     ObjectInputStream in2 = new ObjectInputStream(bis2)) {
                    return in2.readObject();
                } catch (Exception e) {
                    throw new RuntimeException("Error during deserialization", e);
                }
            });

            // Ensure cache size limits are maintained 
            if (cache.size() > DEFAULT_CACHE_SIZE) {
                clearCache();
            }

            return cachedObj;
        } catch (Exception e) {
            throw new RuntimeException("Error during deserialization", e);
        }
    }

    public void clearCache() {
        cache.clear();
    }
}
```
This code uses a `ConcurrentHashMap` as a simple cache, ensuring thread-safety and efficient resource management. It also uses an allowed classes set to check the class of each deserialized object against predefined acceptable classes. This mechanism can be adapted for dynamic configuration by replacing the hardcoded `allowedClasses.add(Class1.class);` lines with a method that reads from an external source like a configuration file or environment variables. 

Note: Remember to add Apache Commons Lang library in your project for using SerializationUtils.serialize() method. You can include it by adding following line in the pom.xml of Maven-based projects:
```xml
<dependency>
    <groupId>org.apache.commons</groupId>
    <artifactId>commons-lang3</artifactId>
    <version>3.12.0</version>
</dependency>
```
