import json, gc, os, time
from collections import defaultdict
import requests  # or any other library for handling HTTP requests

class JSONProcessor:
    def __init__(self):
        self.factories = dict()
        self.tracked_objects = []

    def register(self, module_id, factory_func):
        if module_id in self.factories:
            raise Exception("Module already registered.")
        else:
            self.factories[module_id] = factory_func

    def unregister(self, module_id):
        del self.factories[module_id]

    def add_tracked_object(self, obj):
        self.tracked_objects.append(obj)

    def remove_tracked_object(self, obj):
        self.tracked_objects.remove(obj)

    def report_memory_usage(self):
        for i in range(0, len(self.tracked_objects)):
            print(f"Object {i} uses {sys.getsizeof(self.tracked_objects[i])} bytes")

    def track_gc(self, generation):
        print("Garbage collector is running for the {}th time".format(generation))

    gc.callbacks.append(track_gc)

class DataModel:
    def __init__(self, data):
        self.data = data

class ExternalDataSource:
    def __init__(self, url):
        self.url = url
        self.last_updated = 0
        self.ttl = 60  # Time To Live in seconds

    def fetch(self):
        if time.time() - self.last_updated > self.ttl:
            response = requests.get(self.url)
            if response.status_code == 200:
                self.data = response.json()
                self.last_updated = time.time()
            else:
                raise Exception("Failed to fetch data from the external source")
        return self.data
