['Below is a basic code implementation of your requirements using Java NIO Channels and an ExecutorService to manage connections. It doesn't cover all possible edge cases but provides a good start point. Remember this is just a simple example and may require further adjustments for production use.

```java
import java.nio.ByteBuffer;
import java.security.MessageDigest;
import java.util.concurrent.*;
import javax.xml.bind.DatatypeConverter;
import java.nio.channels.*;
import java.net.InetSocketAddress;
import java.nio.charset.StandardCharsets;
import java.io.IOException;

public class ConnectionManager {
    private ExecutorService executor = Executors.newFixedThreadPool(10); // adjust according to your need
    private SocketChannel channel;
    private AsynchronousSocketChannel asyncChannel;

    public void establishConnection(String endpoint, int port) throws ExecutionException, InterruptedException {
        InetSocketAddress serverAddr = new InetSocketAddress(endpoint, port);

        try {
            this.asyncChannel = AsynchronousSocketChannel.open();
            Future<Void> result = asyncChannel.connect(serverAddr);
            // Wait for the operation to complete with timeout
            result.get(5000, TimeUnit.MILLISECONDS);

            if (result.isCancelled()) {
                System.out.println("Connection timed out");
            } else if (result.isDone()) {
                this.channel = asyncChannel.get();
                scheduleHealthCheck(30, TimeUnit.SECONDS); // health check every 30 seconds
            }
        } catch (IOException | TimeoutException e) {
            System.err.println("Error establishing connection: " + e.getMessage());
            retryConnection(endpoint, port);
        }
    }

    private void scheduleHealthCheck(long delay, TimeUnit timeUnit) {
        executor.schedule(() -> 
            checkConnectionState(), 
            delay, timeUnit
        );
    }

    private void retryConnection(String endpoint, int port) throws ExecutionException, InterruptedException {
        System.out.println("Retrying connection");
        establishConnection(endpoint, port);
    }

    private void checkConnectionState() {
        // Implement your logic here to check the state of the connection
        // This can be a simple read/write operation or more complex health checks (heartbeats etc.)
    }

    public String getMD5Hash(String input) throws Exception{
        if(channel == null || !channel.isConnected()){
            throw new IOException("Connection is not established");
        }

        byte[] data = input.getBytes(StandardCharsets.UTF_8); 
        ByteBuffer buffer = ByteBuffer.wrap(data);
        channel.write(buffer);

        MessageDigest md = MessageDigest.getInstance("MD5");
        md.update(buffer.array());
        byte[] digest = md.digest();

        return DatatypeConverter.printHexBinary(digest).toLowerCase();
    }
}
```
This code creates a connection to an endpoint using the NIO library, schedules periodic health checks and allows retrieval of MD5 hashes for a given string. The implementation does not include sophisticated error handling or advanced connection management features such as load balancing, health checks, retry mechanisms etc., which you'd typically find in production code.
']

