['Here is a sample solution written in C that follows the instructions given. This code does not include any error handling for files with extensions other than text, image, and binary, as these are not specified in the problem statement. The code also assumes that the unique file identifier is the filename itself (this may or may not be accurate).

```c
#include <dirent.h>
#include <stdio.h>
#include <sys/stat.h>
#include <time.h>
#include <string.h>
#include <errno.h>

void process_directory(const char *dirname) {
    DIR *d;
    struct dirent *ent;
    int count[256] = {0};

    d = opendir(dirname);
    if (!d) {
        fprintf(stderr, "Could not open directory '%s': %s\n", dirname, strerror(errno));
        return;
    }

    while ((ent = readdir(d)) != NULL) {
        char path[PATH_MAX], newpath[PATH_MAX];
        struct stat st;
        int n;

        if (strcmp(ent->d_name, ".") == 0 || strcmp(ent->d_name, "..") == 0) {
            continue; // Skip . and .. entries
        }

        snprintf(path, sizeof path, "%s/%s", dirname, ent->d_name);

        if (stat(path, &st) < 0 || !S_ISREG(st.st_mode)) {
            continue; // Skip non-regular files and stat failures
        }

        n = strrchr(ent->d_name, '.') - ent->d_name; // Find the base name length
        count[n]++; // Increment file counter for this base name

        struct tm *tm = localtime(&st.st_mtim); // Get modification time

        snprintf(newpath, sizeof newpath, "%s/%.*s-%.4d%.2d%.2d%.2d%.2d%.2d-v%03d", 
                 dirname, n, ent->d_name, tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday, 
                 tm->tm_hour, tm->tm_min, tm->tm_sec, count[n]); // Generate new path

        if (rename(path, newpath) < 0) {
            fprintf(stderr, "Could not rename file '%s': %s\n", ent->d_name, strerror(errno));
        } else {
            printf("Renamed '%s' to '%s'\n", path, newpath);
        }
    }

    closedir(d);
}
```
This code assumes that the modification time of a file is the last time it was modified. It also uses `rename` instead of file I/O functions for simplicity. 

Note: This code does not handle cases where multiple threads access the directory simultaneously. To handle this, you would need to add locks around any shared resources (in this case, the count array and files). For example, you could use pthread mutexes or a lock-free data structure like tbb::concurrent_hash_map.
']

