        printf("Memory allocation failed!\n");
        return;
    }

    int capacity = 1024 * 1024 / sizeof(int); // capacity in terms of number of integers
    int size = 0; // current size used

    while (size < 5) { // read until 5MB is reached
        if(scanf("%d", &arr[size]) != 1) { // try reading an integer
            printf("Invalid input!\n");
            return;
        }
        ++size;
        if(size == capacity && size < 5 * 1024 * 1024 / sizeof(int)) { // double the memory if not enough space for more
            int* temp = realloc(arr, (capacity *= 2) * sizeof(int));
            if(temp == NULL) { // allocation failed
                printf("Memory allocation failed!\n");
                return;
            } else {
                arr = temp; // assign new memory to the array pointer
            }
        }
    }

    int largest = 0;
    for(int i=0; i<size; ++i) { // find the largest number
        if (arr[i] > largest) {
            largest = arr[i];
        }
    }

    printf("Largest number: %d\n", largest);
    free(arr);
}
