```rust
use std::collections::HashMap;
use hyper::{Body, Client};
use tokio::sync::Semaphore;

pub struct HttpClient {
    client: Client,
    semaphore: Semaphore,
}

impl HttpClient {
    pub fn new() -> Self {
        let client = Client::new();
        let semaphore = Semaphore::new(10); // limit to 10 concurrent requests
        HttpClient { client, semaphore }
    }

    pub async fn get(&self, url: &str, headers: Option<HashMap<&str, &str>>, params: Option<HashMap<&str, &str>>) -> Result<String, Box<dyn std::error::Error>> {
        let permit = self.semaphore.acquire().await; // acquire a semaphore permit

        let client = &self.client;
        let url = format_url(url, params); // function to add parameters to URL if needed

        let resp = match headers {
            Some(headers) => client.get(&url).headers(headers).await?, // send GET request with optional headers
            None => client.get(&url).await?,
        };

        let bytes = hyper::body::to_bytes(resp.into_body()).await?; // read the response body to a byte vector

        let result = String::from_utf8(bytes)?; // convert bytes to string (UTF-8)

        drop(permit); // release the permit when done

        Ok(result)
    }
}
``` 

