['Here is a simple code snippet that satisfies most of your requirements. This uses Java's CompletableFuture for parallel execution to calculate hashes, Guava's RateLimiter for controlling network traffic, and Apache Commons IO's Digester to compute SHA-256 hashes in a streaming way. 

```java
import com.google.common.util.concurrent.RateLimiter;
import org.apache.commons.codec.digest.DigestUtils;
import java.io.*;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.security.NoSuchAlgorithmException;
import java.util.Map;
import java.util.concurrent.CompletableFuture;
import java.util.stream.Collectors;
import java.util.Arrays;
import java.util.List;

public class FileHashService {
    private final MetadataService metadataService = new MockMetadataService(); // Replace with actual service
    private final RateLimiter rateLimiter = RateLimiter.create(10.0); // Adjust this for your need

    public Map<String, String> calculateHashes(List<File> files) {
        return files.stream()
            .collect(Collectors.toMap(
                File::getName, 
                file -> CompletableFuture.supplyAsync(() -> calculateHashWithRetry(file))
                    .thenApply(hash -> validateAndGetMetadata(file, hash))
            )).entrySet().stream()
            .collect(Collectors.toMap(Map.Entry::getKey, Map.Entry::getValue));
    }

    private String calculateHashWithRetry(File file) {
        int retries = 0;
        while (true) {
            try {
                return calculateSha256(file);
            } catch (IOException e) {
                if (++retries >= 3) throw new RuntimeException("Failed to calculate hash for " + file.getName(), e);
            }
        }
    }

    private String validateAndGetMetadata(File file, String hash) {
        rateLimiter.acquire(); // Ensures we don't hit the metadata service too hard

        Map<String, Object> metadata = metadataService.getMetadata(hash);
        if (metadata != null && metadata.containsKey("valid") && Boolean.TRUE.equals(metadata.get("valid"))) {
            return hash; // Valid file
        } else {
            throw new IllegalArgumentException("Invalid or corrupted file " + file.getName());
        }
    }

    private String calculateSha256(File file) throws IOException {
        try (InputStream is = Files.newInputStream(Paths.get(file.toURI()));
             InputStream bufferedIs = new BufferedInputStream(is)) {
            return DigestUtils.sha256Hex(bufferedIs);
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("Failed to find SHA-256 algorithm", e);
        }
    }
}

interface MetadataService { Map<String, Object> getMetadata(String hash); }
class MockMetadataService implements MetadataService { ... } // Implement with actual service details
