// Implement lock and list to ensure data consistency in multi-threaded environment
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
DCI* dciList[1024];
int listSize = 0;

void init() {
    pthread_mutex_init(&lock, NULL);
}

// Add DCI to the list
void add(DCI* dci) {
    pthread_mutex_lock(&lock);
    if (listSize >= 1024) {
        printf("List is full.\n");
    } else {
        dciList[listSize] = dci;
        listSize++;
    }
    pthread_mutex_unlock(&lock);
}

// Delete DCI from the list by index
void delete(int index) {
    pthread_mutex_lock(&lock);
    if (index >= listSize || index < 0) {
        printf("Index out of bounds.\n");
    } else {
        for (int i = index; i < listSize - 1; i++) {
            dciList[i] = dciList[i + 1];
        }
        listSize--;
    }
    pthread_mutex_unlock(&lock);
}

// Lookup DCI by index
DCI* lookup(int index) {
    pthread_mutex_lock(&lock);
    if (index >= listSize || index < 0) {
        printf("Index out of bounds.\n");
        return NULL;
    } else {
        pthread_mutex_unlock(&lock);
        return dciList[index];
    }
}

// Iterate over DCI list
void iterate() {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < listSize; i++) {
        printf("DCI #%d: DLLayerIndication=%d, DMRSConfigurationInfo=%d\n", 
               i, dciList[i]->DLLayerIndication, dciList[i]->DMRSConfigurationInfo);
    }
    pthread_mutex_unlock(&lock);
}
```
