    LogLevel level;
    char *message;
} LogData;

pthread_mutex_t lock;

void log_message(LogLevel level, const char *format, ...) {
    // Locking mechanism for thread safety
    pthread_mutex_lock(&lock);

    va_list args;
    va_start(args, format);

    int size = vsnprintf(NULL, 0, format, args) + 1; // Extra space for '\0'
    if (size < 0) {
        pthread_mutex_unlock(&lock);
        return;
    }

    char *buffer = malloc(size);
    vsnprintf(buffer, size, format, args);

    va_end(args);

    // Construct log data struct
    LogData *log_data = malloc(sizeof(LogData));
    log_data->level = level;
    log_data->message = buffer;

    // TODO: Send the data to external service, add fallback mechanism and cleanup.

    pthread_mutex_unlock(&lock);
}
