#include <semaphore.h>
#include <pthread.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    sem_t sem;
    pthread_mutex_t lock;
} MySemaphore;

void* acquire(MySemaphore *sem) {
    int ret = sem_wait(&sem->sem);
    if (ret != 0) {
        printf("Error: Failed to acquire semaphore");
        exit(-1);
    }
}

void* release(MySemaphore *sem) {
    int ret = sem_post(&sem->sem);
    if (ret != 0) {
        printf("Error: Failed to release semaphore");
        exit(-1);
    }
}

int initSemaphore(MySemaphore *sem, int value) {
    pthread_mutex_init(&sem->lock, NULL);
    if (sem_init(&sem->sem, 0, value) != 0) {
        printf("Error: Failed to initialize semaphore");
        exit(-1);
    }
}

void deleteSemaphore(MySemaphore *sem) {
    pthread_mutex_destroy(&sem->lock);
    if (sem_destroy(&sem->sem) != 0) {
        printf("Error: Failed to delete semaphore");
        exit(-1);
    }
}
```

