// Maximum DNS queries per second
#define MAX_DNS_QUERIES_PER_SECOND 10

static int queryCount = 0;
clock_t startTime = clock();

u_char* resolve(const char *hostname) {
    if (((double)(clock() - startTime)) / CLOCKS_PER_SEC > 1.0) {
        // If a second has passed, reset the query count
        queryCount = 0;
        startTime = clock();
    } else if (queryCount >= MAX_DNS_QUERIES_PER_SECOND) {
        fprintf(stderr, "Maximum DNS queries per second reached.\n");
        return NULL;
    }

    struct hostent *hostInfo = gethostbyname(hostname);
    if (hostInfo == NULL) {
        herror("gethostbyname failed.");
        return NULL;
    }

    queryCount++;
    return (u_char *) hostInfo->h_addr;
}
