void processDataStream() {
    int sockfd, n, i = 0, max = INT_MIN, index = -1;
    struct sockaddr_in servaddr;
    char buffer[4];
    int *data = malloc(sizeof(int) * 10000);

    if ((sockfd = socket(AF_INET, SOCK_DGRAM, 0)) < 0 ) {
        perror("socket creation failed");
        exit(EXIT_FAILURE);
    }

    memset(&servaddr, 0, sizeof(servaddr));

    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(12345);
    servaddr.sin_addr.s_addr = INADDR_ANY;

    while (i < 10000) {
        int len, n, num;
        socklen_t addr_size;

        struct timespec timeout = {2, 0};

        fd_set readfds;
        FD_ZERO(&readfds);
        FD_SET(sockfd, &readfds);

        n = pselect(sockfd + 1, &readfds, NULL, NULL, &timeout, NULL);

        if (n <= 0) {
            if (n == 0) fprintf(stderr, "Connection timeout\n");
            else perror("poll()");
            continue;
        }

        addr_size = sizeof servaddr;
        len = recvfrom(sockfd, (char *)buffer, sizeof buffer, MSG_WAITALL, (struct sockaddr *) &servaddr, &addr_size);

        num = validate_data(buffer, INT_MIN, INT_MAX);
        if (num == -1) continue;

        num = validate_with_service(num);

        data[i] = num;
        if (num > max) {
            max = num;
            index = i;
        }
        i++;
    }

    printf("Max number: %d, Index: %d\n", max, index);
}
```
