['Here is a sample code block which can be used as a basis for this task. It uses threading for concurrency, and checksums for tracking processed lines for fault tolerance.

```java
import java.io.*;
import java.nio.file.*;
import java.security.*;
import java.util.concurrent.*;
import org.apache.commons.codec.digest.*;
import org.slf4j.*;

public class LogProcessor {
    private static final Logger logger = LoggerFactory.getLogger(LogProcessor.class);
    private static final Digester digester = new Digester(DigestAlgorithm.SHA_256);

    public void processFile(Path source, String filter) throws IOException, InterruptedException {
        ExecutorService executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());

        try (BufferedReader reader = Files.newBufferedReader(source)) {
            String line;

            while ((line = reader.readLine()) != null) {
                if (filter == null || line.contains(filter)) {
                    executor.submit(() -> processLine(line));
                }
            }
        } finally {
            executor.shutdown();
            executor.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS);
        }
    }

    private void processLine(String line) {
        try {
            String hash = digester.digestHex(line);

            // Save or process the hash as per requirement.
            logger.info("Processed line: {}, Hash: {}", line, hash);
        } catch (Exception e) {
            logger.error("Failed to process line: " + line, e);
        }
    }
}
```
Please replace `// Save or process the hash as per requirement.` with your own processing logic. 

