Here's a high-level concept:

```c
#include <stdlib.h>
#include <pthread.h>

// Define structures for the record and the linked list nodes
typedef struct Record {
    int value;
    int* key_ptr;
} Record;

typedef struct Node {
    Record* record;
    struct Node* next;
} Node;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
long offsets[10]; // Offset values array
int keys[10];  // Keys array
Node* head; // Head of the linked list
Record records[10];  // Records array

void* memory_pool = NULL;
size_t memory_pool_size = 0;

// Memory pool allocator function:
void* mempool_alloc(size_t size) {
    pthread_mutex_lock(&lock);

    if (memory_pool == NULL || size > memory_pool_size) {
        // If the request size is larger than our current memory pool, or 
        // if we don't have a memory pool yet, allocate new.

        pthread_mutex_unlock(&lock);

        void* new_mem = malloc(size);

        pthread_mutex_lock(&lock);
        free(memory_pool);
        memory_pool = new_mem;
        memory_pool_size = size;
    } 

    // Return the memory from our pool and shrink its size.
    void* retval = memory_pool;
    memory_pool += size;
    memory_pool_size -= size;
    pthread_mutex_unlock(&lock);

    return retval; 
}

// Function for initializing and returning the head of a circular linked list:
Node* initialize() {
    // Allocate memory for our arrays using our custom allocator.
    offsets = mempool_alloc(sizeof(long) * 10);
    keys = mempool_alloc(sizeof(int) * 10);
    records = mempool_alloc(sizeof(Record) * 10);

