['Below is a C code block that meets the requirements mentioned in your problem description. Note that this code does not handle high concurrency conditions as it's beyond the scope of handling system level operations here. 

```c
#include <stdio.h>
#include <string.h>
#include <stdlib.h>

typedef struct Node {
    struct Node* next;
    int key;
    char value[50];
} Node;

Node** hashTable;
int TABLE_SIZE = 13;  // Initial table size
float LOAD_FACTOR_THRESHOLD = 0.7;
int numElements = 0;

unsigned long hash(char* str) {
    unsigned long hash = 5381;
    int c;

    while ((c = *str++))
        hash = ((hash << 5) + hash) + c; 

    return hash % TABLE_SIZE;
}

void insert(int key, char* value) {
    Node* newNode = (Node*) malloc(sizeof(Node));
    if(!newNode){
        printf("Memory allocation failed\n");
        exit(1);
    }
    newNode->key = key;
    strcpy(newNode->value, value);

    int index = hash(value);
    Node* nodePtr = hashTable[index];

    while (nodePtr && nodePtr->next) {  // Handle duplicates by ignoring them
        if (nodePtr->key == key) return;
        nodePtr = nodePtr->next;
    }

    newNode->next = hashTable[index];
    hashTable[index] = newNode;
    ++numElements;

    float loadFactor = (float) numElements / TABLE_SIZE;
    if(loadFactor > LOAD_FACTOR_THRESHOLD){
        resize();
    }
}

void removeNode(int key, char* value) {
    int index = hash(value);
    Node* prevPtr = NULL;
    Node* nodePtr = hashTable[index];

    while (nodePtr && nodePtr->key != key){  // If the key is not found then do nothing
        prevPtr = nodePtr;
        nodePtr = nodePtr->next;
    }

    if (!nodePtr) return;

    if(prevPtr) {
        prevPtr->next = nodePtr->next;  // Remove from middle of list
    } else {
        hashTable[index] = nodePtr->next;  // Remove first element in list
    }

    --numElements;
    free(nodePtr);
}

void resize() {
    int oldSize = TABLE_SIZE;
    numElements = 0;
    TABLE_SIZE *= 2;

    Node** newHashTable = (Node**) calloc(TABLE_SIZE, sizeof(Node*));
    if(!newHashTable){
        printf("Memory allocation failed\n");
        exit(1);
    }

    for(int i = 0; i < oldSize; ++i) {  // Rehash the nodes into the new table
        Node* node = hashTable[i];
        while (node){
            Node* tempPtr = node;
            node = node->next;

            int index = hash(tempPtr->value);
            tempPtr->next = newHashTable[index];
            newHashTable[index] = tempPtr;
            ++numElements;
        } 
    }

    free(hashTable);
    hashTable = newHashTable;
}

void printAllNodes() {
    for (int i = 0; i < TABLE_SIZE; ++i) {
        Node* nodePtr = hashTable[i];

        while (nodePtr){
            printf("Key: %d, Value: %s\n", nodePtr->key, nodePtr->value);
            nodePtr = nodePtr->next;
        }
    } 
}
```
This code initializes a dynamic array of Node pointers as the hash table. The `hash` function generates an index based on string value which is to be used for hashing. When inserting new nodes into the hash table, duplicates are handled by ignoring them when found. The load factor is checked after each addition and if it exceeds a specified threshold, the hash table is doubled in size and all elements are rehashed into the new table using `resize` function. Memory deallocation occurs during node removal or resizing to avoid memory leaks. 
The code can be optimized by adjusting initial allocation size, dynamic resizing and performance implications of frequent rehashing based on specific usage scenarios. However, these trade-offs need careful consideration as they may introduce new complexities into the system design such as potential for system crashes due to insufficient memory during high load conditions or excessive time spent in resizing operations.
']

