void executeCommand(char* filename, char* command[]) {
    pid_t pid = fork();

    if (pid == 0) { // Child process.
        struct stat buffer;   
        if (stat (filename, &buffer) == 0)  // If the file exists.
            remove(filename);   // Delete it before execution.

        execvp(command[0], command); // Execute the command.
        exit(0);
    } else { // Parent process.
        int status;
        wait(&status); // Wait for child to complete and handle any errors gracefully.

        if (WIFEXITED(status)) {
            printf("Child exited with code: %d\n", WEXITSTATUS(status));
        } else if (WIFSIGNALED(status)) {
            printf("Child terminated by signal: %d\n", WTERMSIG(status));
        }
    }
}
