    Measurement **measurements = malloc(MAX_LINES * sizeof(Measurement*));
    int num_lines = 0;
    while (fgets(line, 1024, file)) {
        if (num_lines >= MAX_LINES) {
            free_data(measurements, num_lines);
            fclose(file);
            // handle error, array too large or memory allocation failed
            return NULL;
        }

        Measurement *m = malloc(sizeof(Measurement));
        if (m == NULL) {
            free_data(measurements, num_lines);
            fclose(file);
            // handle error, memory allocation failed
            return NULL;
        }

        char *token = strtok(line, ",");
        m->timestamp = atof(token);
        token = strtok(NULL, ",");
        m->value = atof(token);
        token = strtok(NULL, "\n");
        if (token != NULL) {
            m->location = malloc((strlen(token) + 1) * sizeof(char));
            if (m->location == NULL) {
                free_data(measurements, num_lines);
                fclose(file);
                // handle error, memory allocation failed
                return NULL;
            }
            strcpy(m->location, token);
        } else {
            m->location = "";
