#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int id;
    char DL_Layer_Indication[20];
    char DMRS_Configuration[50];
} DCI_Message;

typedef struct Node {
    DCI_Message data;
    struct Node* next;
} Node;

Node* head = NULL;
pthread_mutex_t lock;

void initialize() {
    pthread_mutex_init(&lock, NULL);
}

DCI_Message create_message(int id, char* DL_Layer_Indication, char* DMRS_Configuration) {
    DCI_Message message;
    message.id = id;
    strcpy(message.DL_Layer_Indication, DL_Layer_Indication);
    strcpy(message.DMRS_Configuration, DMRS_Configuration);
    return message;
}

void add_message(DCI_Message data) {
    pthread_mutex_lock(&lock);
    Node* newNode = (Node*) malloc(sizeof(Node));
    newNode->data = data;
    newNode->next = head;
    head = newNode;
    pthread_mutex_unlock(&lock);
}

void delete_message(int id) {
    pthread_mutex_lock(&lock);
    Node *temp = head, *prev;

    while (temp != NULL && temp->data.id != id) {
        prev = temp;
        temp = temp->next;
    }

    if(temp == NULL){
        pthread_mutex_unlock(&lock);
        return;
    }

    prev->next = temp->next;
    free(temp);
    pthread_mutex_unlock(&lock);
}

DCI_Message* lookup_message(int id) {
    Node *temp = head;
    while (temp != NULL && temp->data.id != id) 
        temp = temp->next;

    if (temp == NULL) return NULL;

    DCI_Message* result = malloc(sizeof(DCI_Message));
    *result = temp->data;

    return result;
}

void traverse() {
    Node *temp = head;
    while (temp != NULL) {
        printf("id: %d, DL Layer Indication: %s, DMRS Configuration: %s\n", temp->data.id, 
               temp->data.DL_Layer_Indication, temp->data.DMRS_Configuration);
        temp = temp->next;
    }
}
```
