using namespace std;

struct DCIMessage {
    int dlIndication; // DL Layer Indication
    int dmrsConfig;   // DMRS configuration information
};

class LTE_DCI_Manager {
private:
    mutex mtx;
    vector<shared_ptr<DCIMessage>> DCIs;
public:
    void addMessage(const shared_ptr<DCIMessage>& dci) {
        lock_guard<mutex> lock(mtx);
        DCIs.push_back(dci);
    }

    bool removeMessageByDLIndication(int dlIndication) {
        unique_lock<mutex> lock(mtx);
        auto it = find_if(DCIs.begin(), DCIs.end(), [&dlIndication](const shared_ptr<DCIMessage>& msg) { return msg->dlIndication == dlIndication; });
        if (it != DCIs.end()) {
            DCIs.erase(it);
            return true;
        } else {
            return false;
        }
    }

    shared_ptr<DCIMessage> findMessageByDMRSConfig(int dmrsConfig) {
        lock_guard<mutex> lock(mtx);
        auto it = find_if(DCIs.begin(), DCIs.end(), [&dmrsConfig](const shared_ptr<DCIMessage>& msg) { return msg->dmrsConfig == dmrsConfig; });
        if (it != DCIs.end()) {
            return *it;
        } else {
            return nullptr;
        }
    }

    void printAllMessages() {
        lock_guard<mutex> lock(mtx);
        for(const auto& msg : DCIs) {
            cout << "DL Layer Indication: " << msg->dlIndication << ", DMRS config: " << msg->dmrsConfig << endl;
        }
    }
};
