#include <stdio.h>
#include <unistd.h>
#include <sys/wait.h>
#include <fcntl.h>

void execute_command(const char* cmd, int delete_before) {
    if (delete_before && access(cmd, F_OK) != -1) {
        remove(cmd);
    }

    pid_t pid = fork();

    if (pid == 0) { // Child process
        execl("/bin/sh", "sh", "-c", cmd, NULL); 
        _exit(EXIT_FAILURE); 
    } else if (pid < 0) { // Fork failed
        printf("Forking failed!\n");
        return;
    } else { // Parent process
        int status;
        waitpid(pid, &status, 0);

        if (WIFEXITED(status)) {
            int exit_code = WEXITSTATUS(status);

            if (exit_code != 0) {
                printf("Subprocess returned an error code: %d\n", exit_code);
            } else {
                printf("Subprocess executed successfully.\n");
            }
        } else {
            printf("Subprocess did not terminate normally!\n");
        }
    }
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        printf("Usage: %s <command>\n", argv[0]);
        return 1;
    }

    execute_command(argv[1], 0); // Call with delete_before=false
    return 0;
}
```
This program accepts a command-line argument and executes it. It uses fork() to create a new process, which then calls execl() to replace its code segment with the command's executable code. The parent process waits for the child process to finish using waitpid(), then checks if the subprocess terminated normally and printed an error message or success message accordingly.

