#include <stdlib.h>
#include <string.h>

typedef struct file_info {
    double size;
    char *filename;
    int status; // 0 = closed, 1 = open
    struct file_info *next;
} FileInfo;

FileInfo *head = NULL;
int count = 0;

void add_file(double size, const char* filename, int status) {
    FileInfo *newNode = (FileInfo*)malloc(sizeof(FileInfo));
    newNode->size = size;
    newNode->filename = malloc(strlen(filename) + 1); 
    strcpy(newNode->filename, filename);
    newNode->status = status;

    if (head == NULL) { // empty list
        head = newNode;
        newNode->next = head;
    } else {
        FileInfo *temp = head;
        while(temp->next != head) 
            temp = temp->next;

        temp->next = newNode;
        newNode->next = head;
    }
    ++count;
}

void update_status(const char* filename, int status) {
    if (head == NULL) 
        return;

    FileInfo *temp = head;
    do {
        if (strcmp(temp->filename, filename) == 0) {
            temp->status = status;
            break;
        }
        temp = temp->next;
    } while(temp != head);
}

void free_memory() {
    FileInfo *current = head;
    for (int i = 0; i < count; ++i) {
        FileInfo *temp = current;
        current = current->next;

        free(temp->filename);
        free(temp);
    }
}
