["Here is a basic outline of how you might implement this in C:

```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct record {
    int key;
    char* value;
} Record;

typedef struct data_store {
    pthread_mutex_t lock;
    size_t capacity;
    size_t count;
    Record** records;
} DataStore;

void init(DataStore *ds, size_t capacity) {
    ds->lock = (pthread_mutex_t) PTHREAD_MUTEX_INITIALIZER;
    ds->capacity = capacity;
    ds->count = 0;
    ds->records = malloc(sizeof(Record*) * capacity);
}

void destroy(DataStore *ds) {
    for (int i=0; i<ds->count; ++i) {
        free(ds->records[i]->value);
        free(ds->records[i]);
    }
    free(ds->records);
}

void resize_if_needed(DataStore *ds) {
    if (ds->count == ds->capacity) {
        ds->capacity *= 2;
        ds->records = realloc(ds->records, sizeof(Record*) * ds->capacity);
    }
}

int insert(DataStore *ds, int key, char* value) {
    pthread_mutex_lock(&ds->lock);

    for (int i=0; i<ds->count; ++i) 
        if (ds->records[i]->key == key) {
            pthread_mutex_unlock(&ds->lock);
            return -1; // Key already exists
        }

    resize_if_needed(ds);

    Record* r = malloc(sizeof(Record));
    r->key = key;
    size_t valueLen = strlen(value) + 1;
    r->value = malloc(valueLen);
    memcpy(r->value, value, valueLen);

    ds->records[ds->count++] = r;

    pthread_mutex_unlock(&ds->lock);

    return 0; // Insertion successful
}

int update(DataStore *ds, int key, char* value) {
    pthread_mutex_lock(&ds->lock);

    for (int i=0; i<ds->count; ++i) 
        if (ds->records[i]->key == key) {
            free(ds->records[i]->value);

            size_t valueLen = strlen(value) + 1;
            ds->records[i]->value = malloc(valueLen);
            memcpy(ds->records[i]->value, value, valueLen);

            pthread_mutex_unlock(&ds->lock);

            return 0; // Update successful
        }

    pthread_mutex_unlock(&ds->lock);

    return -2; // Invalid key
}
```
