```c
#include <pthread.h>
#define QUEUE_SIZE 1000 // Adjust according to your needs
typedef struct {
    int head;
    int tail;
    void* elements[QUEUE_SIZE];
    pthread_mutex_t lock;
} Queue;

void queueInit(Queue *q) {
    q->head = 0;
    q->tail = 0;
    pthread_mutex_init(&q->lock, NULL);
}

int enqueue(Queue *q, void* elem) {
    pthread_mutex_lock(&q->lock);
    int next = (q->head + 1) % QUEUE_SIZE;
    if (next == q->tail) { // Queue is full
        pthread_mutex_unlock(&q->lock);
        return -1;
    }
    q->elements[q->head] = elem;
    q->head = next;
    pthread_mutex_unlock(&q->lock);
    return 0;
}

void* dequeue(Queue *q) {
    pthread_mutex_lock(&q->lock);
    if (q->tail == q->head) { // Queue is empty
        pthread_mutex_unlock(&q->lock);
        return NULL;
    }
    void* elem = q->elements[q->tail];
    q->tail = (q->tail + 1) % QUEUE_SIZE;
    pthread_mutex_unlock(&q->lock);
    return elem;
}
```
Please note that these are very basic implementations and real-world applications require much more sophisticated handling. You should consider using a message queue service like RabbitMQ, Kafka or an event sourcing solution for distributed systems.
