#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct NetworkConfig {
    int id;
    char* params;
} NetworkConfig;

typedef struct ListNode {
    NetworkConfig* config;
    struct ListNode* next;
} ListNode;

ListNode* list_head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

NetworkConfig* init_network_config(int id, char* params) {
    NetworkConfig* config = malloc(sizeof(NetworkConfig));
    if (config == NULL) return NULL;

    config->id = id;
    config->params = strdup(params);

    return config;
}

void add_network_config(int id, char* params) {
    pthread_mutex_lock(&lock);

    NetworkConfig* config = init_network_config(id, params);
    if (config == NULL) {
        // Handle error
        goto UNLOCK;
    }

    ListNode* node = malloc(sizeof(ListNode));
    if (node == NULL) {
        free(config->params);
        free(config);
        // Handle error
        goto UNLOCK;
    }

    node->config = config;
    node->next = list_head;
    list_head = node;

UNLOCK:
    pthread_mutex_unlock(&lock);
}

void delete_network_config(int id) {
    pthread_mutex_lock(&lock);

    ListNode* prev_node = NULL;
    for (ListNode* node = list_head; node != NULL; node = node->next) {
        if (node->config->id == id) {
            if (prev_node != NULL) {
                prev_node->next = node->next;
            } else {
                list_head = node->next;
            }

            free(node->config->params);
            free(node->config);
            free(node);
        }

        prev_node = node;
    }

    pthread_mutex_unlock(&lock);
}

NetworkConfig* get_network_config(int id) {
    pthread_mutex_lock(&lock);

    for (ListNode* node = list_head; node != NULL; node = node->next) {
        if (node->config->id == id) {
            NetworkConfig* config = init_network_config(node->config->id, node->config->params);

            pthread_mutex_unlock(&lock);
            return config;
        }
    }

    pthread_mutex_unlock(&lock);
    return NULL;
}
