['Here is a simplified implementation of what you are asking for in C. The function takes in the size of arrays as parameters and returns a pointer to the start of allocated memory block along with total number of records created. Note that this code does not implement dynamic scaling mechanism, conflict resolution strategy and error handling fully as those could be very system specific or business logic dependent, so they have been left out for simplicity. 

```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    long offset;
    int key;
} Record;

long generateRandom(int min, int max) {
    return rand() % (max - min + 1) + min;
}

Record* allocateMemoryForRecords(size_t longSize, size_t intSize, size_t *totalRecords, size_t maxMemory){

    srand((unsigned int)time(NULL));  // use current time as seed for random generator

    size_t recordSize = sizeof(Record);
    size_t totalMemoryNeeded = longSize*sizeof(long) + intSize*sizeof(int) + longSize * intSize * recordSize;

    if (totalMemoryNeeded > maxMemory){  // check memory limit
        printf("Error: Insufficient memory.\n");
        return NULL;
    }

    Record *records = malloc(totalMemoryNeeded);
    if (!records) {  // handle allocation error
       printf("Error: Failed to allocate memory.\n");
       return NULL;
    }

    long* offsets = (long*) records;
    int* keys = (int*) &offsets[longSize];
    Record* allRecords = &keys[intSize];

    *totalRecords = longSize * intSize;  // assign total number of records created

    // Populate arrays with random values
    for(size_t i = 0; i < longSize; ++i){
        offsets[i] = generateRandom(1, 100);  // replace with your own random function
    }

    for(size_t i = 0; i < intSize; ++i){
        keys[i] = (int) generateRandom(1, 100);  // replace with your own random function
    }

    // Populate records array
    size_t index = 0;
    for (size_t i=0; i < longSize; ++i){
        for (size_t j=0; j < intSize; ++j) {
            allRecords[index].offset = offsets[i];
            allRecords[index].key = keys[j];
            ++index;
        }
    }

    return records;  // return start of allocated memory block.
}
```
