    int RX_UE_INFORMATION_TAG;
    int RNTI;
} dci_t;

GHashTable* hashTable = NULL;  // Hash table to store DCI messages
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;  // Mutex for thread safety

// Function to initialize the DCI message list
void dciInit() {
    hashTable = g_hash_table_new(g_direct_hash, g_direct_equal);
}

// Function to add a DCI message to the list
void dciAdd(dci_t* dci) {
    pthread_mutex_lock(&lock);
    g_hash_table_insert(hashTable, &dci->RX_UE_INFORMATION_TAG, dci);
    pthread_mutex_unlock(&lock);
}

// Function to delete a DCI message from the list
void dciDelete(int RX_UE_INFORMATION_TAG) {
    pthread_mutex_lock(&lock);
    g_hash_table_remove(hashTable, &RX_UE_INFORMATION_TAG);
    pthread_mutex_unlock(&lock);
}

// Function to lookup a DCI message in the list
dci_t* dciLookup(int RX_UE_INFORMATION_TAG) {
    pthread_mutex_lock(&lock);
    dci_t* dci = g_hash_table_lookup(hashTable, &RX_UE_INFORMATION_TAG);
    pthread_mutex_unlock(&lock);
    return dci;
}

// Function to traverse the DCI message list
void dciTraversal() {
    GHashTableIter iter;
    gpointer key, value;
    pthread_mutex_lock(&lock);
    g_hash_table_iter_init(&iter, hashTable);
    while (g_hash_table_iter_next(&iter, &key, &value)) {
        dci_t* dci = (dci_t*) value;
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d\n", dci->RX_UE_INFORMATION_TAG, dci->RNTI);
    }
    pthread_mutex_unlock(&lock);
}
