import java.util.*;
import java.util.concurrent.locks.*;

public class PokemonList {
    private static final int MAX_WAIT_TIME = 10; // Adjust based on expected wait time and system stability
    private Node head;
    private volatile WeaknessMap weaknessMap;
    private ReentrantLock lock = new ReentrantLock(true);
    private Condition notEmpty = lock.newCondition();

    public PokemonList() {
        this.head = new Node(null);
        this.weaknessMap = new WeaknessMap();
    }

    public void addPokemon(Pokemon p) throws InterruptedException {
        boolean acquiredLock = lock.tryLock(MAX_WAIT_TIME, TimeUnit.MILLISECONDS);

        if (acquiredLock) {
            try {
                Node newNode = new Node(p);
                newNode.next = head.next;
                head.next = newNode;

                weaknessMap.addTypes(p.getTypes());

                notEmpty.signal();
            } finally {
                lock.unlock();
            }
        } else {
            throw new RuntimeException("Failed to acquire lock within " + MAX_WAIT_TIME + "ms");
        }
    }

    // Other methods for removing and updating nodes...

    private static class Node {
        Pokemon pokemon;
        Node next;

        Node(Pokemon p) {
            this.pokemon = p;
        }
    }
}

class Pokemon {
    // Assume implemented...
}

class WeaknessMap {
    private volatile Map<Type, Set<Weakness>> map;

    public WeaknessMap() {
        this.map = new ConcurrentHashMap<>();
    }

    public void addTypes(Set<Type> types) {
        for (Type type : types) {
            if (!this.map.containsKey(type)) {
                synchronized (this) {
                    // If the map was modified before we could acquire the lock, recheck
                    if (!this.map.containsKey(type)) {
                        this.map.put(type, new HashSet<>());
                    }
                }
            }
        }
    }

    // Other methods for updating and compacting map...
}
``` 
This code implements a thread-safe, dynamic linked list of `Pokemon` objects with each node pointing to its type-specific weaknesses. The weakness map is a concurrent hashmap which ensures the fastest access time among regular hashmaps but also allows multiple threads to safely read and write data without locking. 

