    volatile sig_atomic_t isShuttingDown;
    ListNode *head;
} DCIManager;

void initManager(DCIManager* manager, int maxListSize) {
    pthread_mutex_init(&manager->lock, NULL);
    sem_init(&manager->listSizeSemaphore, 0, maxListSize);
    manager->maxListSize = maxListSize;
    manager->isShuttingDown = 0;
    manager->head = NULL;
}

void addDCI(DCIManager* manager, DCI *dci) {
    sem_wait(&manager->listSizeSemaphore);
    pthread_mutex_lock(&manager->lock);

    ListNode *node = malloc(sizeof(ListNode));
    node->dci = dci;
    node->next = manager->head;
    manager->head = node;

    pthread_mutex_unlock(&manager->lock);
}

// ... similarly for deleteDCI, lookupDCI, traverseList, etc.

void signalHandler(int signum) {
    DCIManager *manager = getInstanceOfManager();
    manager->isShuttingDown = 1;
}

int main() {
    DCIManager manager;
    initManager(&manager, 10);

    signal(SIGINT, signalHandler); // Handle SIGINT (Ctrl+C) for graceful shutdown.

    while(!manager.isShuttingDown) {
        /* ... */
    }

    return 0;
}
```
