class MemoryManager {
private:
    RandomRecordGenerator& record_generator_;

public:
    explicit MemoryManager(RandomRecordGenerator& rg) : record_generator_(rg) {}

    Record* allocateMemoryForArray(size_t size) {
        try {
            auto records = new Record[size];

            for (size_t i = 0; i < size; ++i) 
