// Function pointer to retrieve the IP address of an interface
typedef char *(*GetIPFunc)(char*);

struct NetworkInterface {
    char name[IFNAMSIZ];      // Interface name
    GetIPFunc get_ip;         // Function pointer to fetch IP address
    int activeAndConnected;   // Indicates if interface is active and connected. 1 for True, 0 for False.
};

struct NetworkInterface *getNetworkInterfaces(int *size) {
    static struct NetworkInterface interfaces[32];
    FILE* fp = NULL;
    char ip_addr[INET6_ADDRSTRLEN] = "";
    int count = 0;

    // Retrieve network interface names and statuses
    fp = popen("ip link show | grep 'state UP'", "r");
    while (fscanf(fp, "%*d: %[^:]", interfaces[count].name) == 1) {
        char tmp[512];
        fgets(tmp, sizeof(tmp), fp); // Read the rest of line to detect interface status
        if(strstr(tmp, "state UP") != NULL && strstr(tmp, "qlen") == NULL){ 
            interfaces[count].activeAndConnected = 1;
        }
        else{
            interfaces[count].activeAndConnected = 0;
        }

        interfaces[count].get_ip = GetIP; // Set the function pointer to fetch IP address
        count++;
    }

    pclose(fp);

    *size = count;
    return &interfaces[0];
}

char* GetIP(char* ifname) {
    static char ip_addr[INET6_ADDRSTRLEN] = "";
    FILE * fp = NULL;

    // Fetch the IP address of an interface using 'ip' command
    char cmd[256];
    sprintf(cmd, "ip addr show %s | awk '/inet /{print $2}' | cut -d/ -f1", ifname);
    fp = popen(cmd, "r");
    if (fp == NULL) {
        printf("Failed to get IP address for interface: %s\n", ifname);
        return NULL;
    }

    fgets(ip_addr, INET6_ADDRSTRLEN, fp); // Read the first line of output
    pclose(fp);

    ip_addr[strcspn(ip_addr, "\n")] = '\0';  // Remove trailing newline character if exists
    return ip_addr;
}
```
This code uses Linux command-line tools to fetch network interface information. It uses the 'popen' function to execute a shell command and get its output.

