using System;
using System.Collections.Concurrent;
using System.Threading;
using System.Diagnostics;

public class DynamicDataStructureManager {
    private ConcurrentDictionary<int, Record> records = new ConcurrentDictionary<int, Record>();
    private Random random = new Random();
    private int maxValue;
    private long offset = 0;

    public void SetRange(int max) {
        if (max <= 0) throw new ArgumentException("Max must be a positive number.");

        lock (this) {  // Lock for thread safety.
            this.maxValue = max;
        }
    }

    public void GenerateRandomInteger() {
        int value = 0;

        lock (this) {
            if (maxValue == 0) throw new InvalidOperationException("Max value not set.");

            value = random.Next(maxValue);
        }

        AddRecord((int)value, offset++);  // Thread safe add record operation.
    }

    public void GenerateRandomFloat() {
        double value = 0;

        lock (this) {
            if (maxValue == 0) throw new InvalidOperationException("Max value not set.");

            value = random.NextDouble() * maxValue;  // Convert to float.
        }

        AddRecord((int)value, offset++);  // Thread safe add record operation.
    }

    private void AddRecord(int key, long offset) {
        var record = new Record(key, offset);
        records[record.Key] = record;  // This will update the value if the key exists already.

        Debug.WriteLine("Added Record: " + record.ToString());
    }

    private class Record {
        public int Key { get; set; }
        public long Offset { get; set; }

        public Record(int key, long offset) {
            this.Key = key;
            this.Offset = offset;
        }

        public override string ToString() => $"[Key:{this.Key}, Offset:{this.Offset}]";
    }
}
