['Here is an example of how this might be accomplished in C using POSIX threads for thread-safety, with pthread_mutex locks to prevent data races:

```c
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <sys/time.h>
#include <unistd.h>

typedef struct {
    int value;
} Record;

typedef struct {
    long* offsets;
    int* keys;
    Record* records;
    pthread_mutex_t lock;

    // For caching
    time_t lastFetchTime;
    Configuration cachedConfig; 

} DataStructures;

// Function to initialize the data structures
void initDataStructures(DataStructures* ds, unsigned int seed) {
    srand(seed);

    // Allocate memory for arrays
    ds->offsets = malloc(sizeof(long)*1000); 
    if (ds->offsets == NULL) {
        // Handle out of memory error
        exit(-1);
    }

    ds->keys = malloc(sizeof(int)*1000); 
    if (ds->keys == NULL) {
        // Handle out of memory error
        free(ds->offsets);
        exit(-1);
    }

    ds->records = malloc(sizeof(Record)*1000); 
    if (ds->records == NULL) {
        // Handle out of memory error
        free(ds->offsets);
        free(ds->keys);
        exit(-1);
    }

    pthread_mutex_init(&ds->lock, NULL);
}

// Function to fetch configuration settings
void fetchConfiguration(DataStructures* ds) {
    time_t currentTime = time(NULL);
    double secondsSinceLastFetch = 
        difftime(currentTime, ds->lastFetchTime);

    if (secondsSinceLastFetch < 3600) { 
        // Use cached configuration within an hour
        return;
    }

    pthread_mutex_lock(&ds->lock);

    // Simulate fetching from external data source
    Configuration config = fetchExternalConfig();

    if (config == NULL) {
        sendAlertToAdmin("Failed to fetch configuration");
        config = ds->cachedConfig; 
    } else {
        ds->lastFetchTime = currentTime;
        ds->cachedConfig = config; 
    }

    pthread_mutex_unlock(&ds->lock);
}

// Function to clean up and free memory
void cleanup(DataStructures* ds) {
    free(ds->offsets);
    free(ds->keys);
    free(ds->records);

    pthread_mutex_destroy(&ds->lock);
}
```
Please note that this is a simplified example and might need to be extended or adapted based on the actual requirements. The logging mechanism, performance monitoring, caching strategy etc. are more complex topics which would require much more code to cover them thoroughly. You also may consider using a production ready framework or library for these tasks such as glib, boost or similar.
