<?php
function handleUserAccountRequests($request) {
    // Rate limiting 
    $ip = $_SERVER['REMOTE_ADDR'];
    $cacheKey = 'rate_limit:' . $ip;
    $allowedReqPerMin = 5;
    $expiry = 60; // In seconds

    $redis = new Redis();
    $redis->connect('127.0.0.1', 6379);
    $current = $redis->get($cacheKey);
    if ($current >= $allowedReqPerMin) {
        return ['success' => false, 'message' => 'Rate limit exceeded'];
    } else {
        $redis->incr($cacheKey);
        $redis->expire($cacheKey, $expiry);
    }

    // Data validation
    $requiredFields = ['name', 'email', 'password', 'profile_info', 'sub_action'];
    foreach ($requiredFields as $field) {
        if (!isset($request[$field])) {
            return ['success' => false, 'message' => "Missing required field: $field"];
        }
    }

    $namePattern = "/^[\p{L} ]+$/u"; // Unicode letters and spaces
    $emailPattern = '/^\S+@\S+$/';
    $passwordPattern = '/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)[a-zA-Z\d]{8,}$/m'; // At least 8 chars including a digit, lowercase and uppercase letter
    $profileInfoPattern = '/^\{"phone":"\+\d{1,3}\s?\(\d{2,3}\)\s?\d{3,4}\s?\d{2,4}","address":".*"\}$/'; // JSON with phone and address fields

