    class Record {
        int value;
        String key;
        Instant timestamp;

        public Record(int value, String key) {
            this.value = value;
            this.key = key;
            this.timestamp = Instant.now();
        }
    }

    // Function to fetch data from external API
    private Pokemon fetchPokemonData(String name) {
        try {
            URL url = new URL(API_URL + "cards/" + name);
            HttpURLConnection con = (HttpURLConnection) url.openConnection();

            BufferedReader in = new BufferedReader(new InputStreamReader(con.getInputStream()));
            String inputLine;
