            List<String> types = new ArrayList<>();
            types.add("Fire");  // Dummy data
            return new Pokemon(name, types);
        } catch (Exception e) {
            System.out.println("Failed to fetch data: " + e.getMessage());
            return null;
        }
    }

    public void updateRecord(String name, int value) {
        // Check if record exists in cache
        Record record = cache.get(name);

        if (record == null) {
            // Fetch data from API and create new Record
            Pokemon pokemon = fetchPokemonData(name);

            if (pokemon != null) {
                System.out.println("Fetched data for: " + name);
                record = new Record(value, name);
                cache.put(name, record);
            } else {
                // Handle the case when fetching data failed
                System.out.println("Failed to fetch data for: " + name);
            }
        } else {
            System.out.println("Record exists in cache");
            // Update value and timestamp
            record.value = value;
            record.timestamp = Instant.now();
            cache.put(name, record);
        }
    }
}
