        : strand_(io_service),
          work_(new boost::asio::io_service::work(io_service)) {}

    ~Pipeline() {
        delete work_;
    }

    void StartReceiving() {
        for (int i = 0; i < 16; ++i) {
            boost::thread thread([this, i](){
                this->io_service_.post(boost::bind(&Pipeline::DoWork, this, i));
            });
        }
    }

    std::string ParseMessage(const std::string& msg) override {
        return "Pipeline parsed: " + msg;
    }

private:
    void DoWork(int index) {
        // Replace with actual logic to handle incoming data streams.
        while (true) {
            boost::this_thread::sleep(boost::posix_time::millisec(100));
            std::cout << "Thread " << index << "\n";
        }
    }

    boost::asio::io_service io_service_;
    boost::asio::io_service::strand strand_;
    boost::asio::io_service::work* work_;
};

int main() {
    boost::asio::io_service io_service;
    Pipeline pipeline(io_service);

    // Start receiving data.
    pipeline.StartReceiving();

    // Run the IO service on a thread pool.
    boost::thread_group threads;
    for (int i = 0; i < 4; ++i) {
        threads.create_thread(boost::bind(&boost::asio::io_service::run, &io_service));
    }

    // Wait until all threads are finished.
    threads.join_all();

    return 0;
}
