using System;
using System.Collections.Generic;
using System.Net.Http;
using System.Threading.Tasks;
using System.Xml;

public class Program
{
    private static readonly HttpClient client = new HttpClient();

    public async Task ProcessFeedAsync(string url, string elementName, string attributeName)
    {
        Dictionary<string, List<XmlNode>> dictionary = new Dictionary<string, List<XmlNode>>();

        try
        {
            var responseString = await client.GetStringAsync(url);

            XmlDocument doc = new XmlDocument();
            doc.LoadXml(responseString);

            foreach (XmlNode node in doc.DocumentElement.SelectNodes(elementName))
            {
                string attributeValue = node.Attributes[attributeName]?.InnerText;

                if (!dictionary.ContainsKey(attributeValue))
                {
                    dictionary[attributeValue] = new List<XmlNode>();
                }

                dictionary[attributeValue].Add(node);
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine("Warning: " + ex.Message);
        }
    }
}
```

