```c
#include <stdlib.h>

typedef struct Record {
    int value;
} Record;

typedef struct Node {
    long offsetValue;
    int key;
    Record *record;
    struct Node *nextCircular;
    struct Node *nextInsertionOrder;
} Node;

Node* createLinkedList(int numRecords) {
    Node *head = NULL, *tail = NULL, *previousNode = NULL;
    for (int i = 0; i < numRecords; i++) {
        Node *newNode = malloc(sizeof(Node));
        newNode->offsetValue = rand() % 10000; // Assuming random offset values
        newNode->key = i + 1; // Assuming keys start from 1 and increment sequentially
        newNode->record = malloc(sizeof(Record));
        newNode->record->value = rand() % 10000; // Assuming random record values
        newNode->nextCircular = NULL;
        newNode->nextInsertionOrder = NULL;

        if (head == NULL) {
            head = tail = newNode;
        } else {
            previousNode->nextCircular = newNode;
            tail->nextInsertionOrder = newNode;
            tail = newNode;
        }

        // Make the list circular by pointing last node to first
        if (i == numRecords - 1) {
            newNode->nextCircular = head;
        }

        previousNode = newNode;
    }

    return head;
}
```
