#include <stdlib.h>
#include <pthread.h>

typedef struct record {
    int value;
    int* key;
    struct record *next, *prev;
} Record;

Record** initialize_records(long* offsets, int* keys, size_t count) {
    Record* records = malloc(count * sizeof(Record));
    Record** head_pointers = malloc(4 * sizeof(Record*));

    for (size_t i = 0; i < count; ++i) {
        records[i].value = keys[i];
        records[i].key = &keys[i];

        if (i > 0) {
            records[i-1].next = &records[i];
            records[i].prev = &records[i-1];
        }
    }

    // Making it circular doubly linked list
    records[0].prev = &records[count - 1];
    records[count - 1].next = &records[0];

    for (size_t i = 0; i < 4; ++i) {
        head_pointers[i] = NULL; // Initialize heads of linked lists to NULL.
    }

    return head_pointers;
}
``` 

