} Node;

// Function to create a new item and store it in heap
Item* createItem(const char* id, int value, time_t timestamp) {
    Item *item = malloc(sizeof(Item));
    if(!item) return NULL;

    // Copy the string identifier
    size_t len = strlen(id);
    item->id = malloc(len + 1);
    if(!item->id) {
        free(item);
        return NULL;
    }

    memcpy(item->id, id, len + 1);

    // Assign the rest of the properties
    item->value = value;
    item->timestamp = timestamp;

    return item;
}

// Function to insert an item into a BST
Node* insert(Node *node, Item *item) {
    if(!node) {
        node = malloc(sizeof(Node));
        if(!node) return NULL;

        node->item = item;
        node->left = node->right = NULL;
        pthread_mutex_init(&node->lock, NULL);
    } else {
        pthread_mutex_lock(&node->lock);
        if(strcmp(item->id, node->item->id) < 0) 
            node->left = insert(node->left, item);
        else if(strcmp(item->id, node->item->id) > 0) 
            node->right = insert(node->right, item);

        pthread_mutex_unlock(&node->lock);
    }

    return node;
}

Node* constructBST(Item *items, size_t nItems) {
    Node *root = NULL;

    for(size_t i = 0; i < nItems; ++i) 
        root = insert(root, &items[i]);

    return root;
}

Node* manageItemCollection() {
    // Assuming we have some mechanism to retrieve data from the database or file system.
    Item *items = retrieveDataFromStorage();

    qsort(items, nItems, sizeof(Item), cmpfunc);

    Node *root = constructBST(items, nItems);

    return root;
}
```
Please note that this is a rudimentary implementation. The function assumes the existence of `retrieveDataFromStorage` which retrieves data from some storage mechanism like database or file system but it's not shown in the code above. 

This also assumes that you have a mechanism to update and persist changes back to storage (like database or file). This can be added as needed.
