['Here is an example implementation for `renderFooterScripts` function in JavaScript, which takes into account all the constraints and requirements mentioned above:

```javascript
// Configuration object
const config = {
  developmentMode: true, // Set to false for production mode
};

async function fetchText(url) {
  const response = await fetch(url);
  if (response.ok) return await response.text();
  else throw new Error("HTTP error " + response.status);
}

const scriptCache = {}; // Cache for generated scripts

function renderFooterScripts(scripts) {
  let htmlString = "";

  scripts.forEach((scriptObj) => {
    const type = scriptObj.type || "text/javascript";

    if (scriptObj.src) {
      // Use src URL as cache key to avoid re-fetching the same script
      const cachedScript = scriptCache[scriptObj.src]; 

      // If script is in cache, use it; else fetch and cache it
      const scriptText =  cachedScript || fetchText(scriptObj.src).then((text) => {
        scriptCache[scriptObj.src] = text;
        return text;
      });

      htmlString += renderScriptTagWithContent(type, "", scriptText);
    } else if (scriptObj.code) {
      // If script has code directly, use it and cache it
      const scriptText =  scriptObj.code;
      scriptCache[`inline:${scriptObj.code}`] = scriptText;

      htmlString += renderScriptTagWithContent(type, scriptText);
    }
  });

  return htmlString;
}

function renderScriptTagWithContent(type, content) {
  let tag = `<script type="${type}">`;

  // In development mode, log the generated <script> tag to the console
  if (config.developmentMode) console.log(tag);

  // Add script content or async attribute based on presence of src or code
  tag += content ? `\n${content}\n` : "async";

  return tag + '</script>';
}
```

This function does not check for network errors when fetching scripts from remote URLs, it relies on the fetch API which throws an exception in case of a network error. We can add appropriate error handling to capture such errors and handle them accordingly.

