["Here's a basic example of how you might implement this in JavaScript/AngularJS using Promises for handling asynchronous operations and lodash for its functional programming features. For brevity and simplicity reasons, certain aspects such as error logging are omitted but can be added according to your needs.

```javascript
angular.module('myApp', [])
  .service('refreshService', ['$http', '$q', function($http, $q) {
    var cache = {};

    this.loadFields = function() {
      // load field names dynamically and return a promise with the list
      return $http.get('/api/fields').then(function(response) {
        return response.data;
      });
    }

    this.refreshField = function(field, timestamp) {
      if (cache[field] && cache[field].expiry > Date.now()) {
        // field already refreshed within the last 5 minutes, use cache
        return $q.resolve();
      }

      var deferred = $q.defer(),
          attempts = 0;

      function attemptRefresh() {
        $http.post('/api/refresh', {field: field, timestamp: timestamp})
            .then(function(response) {
              cache[field] = {expiry: Date.now() + 5*60*1000}; // cache for 5 minutes
              $q.resolve();
            })
            .catch(function(err) {
              if (attempts < 3) {
                attempts++;
                setTimeout(attemptRefresh, Math.pow(2, attempts) * 1000); // exponential backoff
              } else {
                $q.reject();
              }
            });
      }

      attemptRefresh();
      return deferred.promise;
    }

    this.refreshFields = function(timestamp) {
      var _this = this;

      return this.loadFields().then(function(fields) {
        // use lodash to batch promises and reduce DOM accesses
        return _.reduce(fields, function(chain, field) {
          return chain.then(function() {
            return _this.refreshField(field, timestamp);
          });
        }, $q.resolve());
      });
    };
  }]);
```

