["Here's a basic JavaScript implementation using async generators and Promises for handling asynchronous operations in an efficient manner. Please note that this does not include all the mentioned features, but it provides a starting point:

```js
class MergeStream {
    constructor() {
        this.streams = new Map();
    }

    add(id, stream) {
        if (this.streams.has(id)) throw Error('Stream already exists');

        const iterator = stream[Symbol.asyncIterator]();
        const nextBuffer = async () => {
            let result;

            try {
                result = await iterator.next();
            } catch (error) {
                console.log('Stream error', id, error);
                // If the stream fails, remove it and continue with the next one
                this.streams.delete(id);
                return;
            }

            if (!result.done && result.value instanceof Buffer) {
                return result.value;
            } else if (result.done) {
                // If the stream is done, remove it and continue with the next one
                this.streams.delete(id);
            }
        };

        const buffer = nextBuffer();
        this.streams.set(id, { id, buffer });
    }

    remove(id) {
        if (!this.streams.has(id)) throw Error('Stream not found');

        this.streams.delete(id);
    }

    async *merge() {
        while (this.streams.size > 0) {
            for (const [id, stream] of this.streams.entries()) {
                const buffer = await stream.buffer;

                if (buffer instanceof Buffer) yield { id, data: buffer };
            }
        }
    }
}
```
To use the above class:

