            // Process each sequence here, like calculating GC content and generating anagrams
            System.out.println("Sequence: " + sequence);

            float gcContent = calculateGCcontent(sequence);
            String category = categorizeBasedOnGcContent(gcContent);

            Set<String> anagrams = generateAnagrams(sequence);
            int countUniqueAnagrams = getNumberOfUniques(anagrams);

            System.out.println("GC content: " + gcContent*100 + "%");
            System.out.println("Category: " + category);
            System.out.println("Count of unique anagrams: " + countUniqueAnagrams);
        }
    }

    private static float calculateGCcontent(String sequence){
        long gcCount = sequence.chars().filter(ch -> ch == 'C' || ch == 'G').count();

        return (float) gcCount / sequence.length();
    }

    private static String categorizeBasedOnGcContent(float gcContent){
        if(gcContent < 0.3f){
            return "Low";
        } else if (gcContent >= 0.3f && gcContent <= 0.7f) {
            return "Medium";
        } else {
            return "High";
        }
    }

    private static Set<String> generateAnagrams(String sequence){
        if (sequence.isEmpty()) {
            return Collections.singleton("");
        }

        Set<String> result = new HashSet<>();
        for (int i = 0; i < sequence.length(); i++) {
            char c = sequence.charAt(i);

            String rest = sequence.substring(0, i) + sequence.substring(i + 1);
            Set<String> anagramsOfRest = generateAnagrams(rest);

            for (String anagram : anagramsOfRest) {
                result.add(c + anagram);
            }
        }

        return result;
    }

    private static int getNumberOfUniques(Set<String> sequences){
        // Implementation depends on the specifics of your database and caching needs 
        return sequences.size();
    }
}
