        monitoringSystem.logMetrics(service);

        // Implement a robust retry mechanism with exponential backoff and jitter to mitigate congestion in the messaging system.
        boolean messageProcessedSuccessfully = false;
        while (!messageProcessedSuccessfully) {
            try {
                messagingSystem.sendMessage(service);
