        .arg(&format_args_into_iterable(crate_path.display().to_string()))
        .spawn()?;

    let exit_code = catch_with_exit_code(|| {
        log("INFO", "Compiling %s", crate_path.display().to_string());
        rustc.wait()?
    });

    let end = Instant::now();

