#include <cmath>
#include <chrono>
#include <utility>
#include <algorithm>

class RandomDataGenerator {
private:
    std::mt19937 gen;
    double minVal, maxVal;
    int numRecords;
    const int MAX_MEMORY = (2 << 20); // 2GB
    std::vector<std::string> keys;
    std::vector<double> numericVals;
    std::vector<std::pair<int, std::string>> records;

public:
    RandomDataGenerator(double minVal_, double maxVal_, int numRecords_) : 
        gen(std::chrono::system_clock::now().time_since_epoch().count()),
        minVal(minVal_), maxVal(maxVal_), 
        numRecords(numRecords_) {
            if (!validateInputs()) {
                std::cerr << "Invalid input parameters" << std::endl;
                exit(1);
            }
    }

    bool validateInputs() {
        if (minVal > maxVal || numRecords < 0) 
            return false;

        // Check for memory constraints
        size_t estimatedMemory = sizeof(double)*numRecords + sizeof(std::pair<int, std::string>)*numRecords;
        if (estimatedMemory > MAX_MEMORY)
            return false;

        return true;
    }

    double generateRandomDouble() {
        std::uniform_real_distribution<> dis(minVal, maxVal);
        return dis(gen);
    }

    void populateDataStructures() {
        keys.reserve(numRecords);
        numericVals.reserve(numRecords);
        records.reserve(numRecords);

        for (int i = 0; i < numRecords; ++i) {
            keys.push_back("key"+std::to_string(i));

            double numericVal = generateRandomDouble();
            numericVals.push_back(numericVal);

            std::pair<int, std::string> record = std::make_pair(i, "val"+std::to_string(i));
            records.push_back(record);
        }
    }

    void logMetrics() {
        double averageMemoryUsagePerRecord = (sizeof(double) + sizeof(std::pair<int, std::string>)) / static_cast<double>(numRecords);

        std::cout << "Total number of records generated: " << numRecords << std::endl;
        std::cout << "Average memory usage per record: " << averageMemoryUsagePerRecord << " bytes" << std::endl;
    }
};
```
