```c
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <assert.h>

typedef struct FSAState {
    int state;
    struct FSAState* next;
} FSAState;

FSAState* create_state(int state) {
    FSAState* newState = (FSAState*) malloc(sizeof(FSAState));
    if (!newState) {
        return NULL;  // Error handling for memory allocation
    }
    newState->state = state;
    newState->next = NULL;
    return newState;
}

typedef struct FSA {
    pthread_mutex_t lock;
    FSAState* head;
} FSA;

FSA* create_fsa() {
    FSA* fsa = (FSA*) malloc(sizeof(FSA));
    if (!fsa) {
        return NULL;  // Error handling for memory allocation
    }
    pthread_mutex_init(&fsa->lock, NULL);
    fsa->head = NULL;
    return fsa;
}

int append_state(FSA* fsa, int state) {
    if (!fsa) {
        return -1;  // Error handling for invalid FSA pointer
    }

    pthread_mutex_lock(&fsa->lock);

    FSAState* newState = create_state(state);
    if (!newState) {
        pthread_mutex_unlock(&fsa->lock);
        return -1;  // Error handling for memory allocation within append_state function
    }

    if (fsa->head == NULL) {
        fsa->head = newState;
    } else {
        FSAState* temp = fsa->head;
        while(temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = newState;
    }

    pthread_mutex_unlock(&fsa->lock);
    return 0;
}
```
This code represents a thread-safe linked list for FSA states. It handles memory allocation and locking to ensure safe concurrent access from multiple threads. However, there are numerous ways it can be improved for better performance or robustness as mentioned in the problem's requirements. For example, error handling can be made more detailed to provide meaningful messages or utilize `errno` to store system-specific error information, etc.
