typedef struct Sensor {
    int id;
    double readings[READINGS_PER_SEC * TIME_WINDOW];
    double cumulativeDeviationScore;
} Sensor;

Sensor sensors[MAX_SENSORS] = {0};
double averageReadings[TIME_WINDOW];
pthread_mutex_t sensorMutex = PTHREAD_MUTEX_INITIALIZER;
int currReadingIndex = 0;
FILE *dataFile;

void writeToStorage(Sensor *sensor) {
    // Function to integrate with external data storage system
}

double calculateDeviation(double reading, double average) {
    return fabs(reading - average);
}

void processData() {
    pthread_mutex_lock(&sensorMutex);
    for (int i = 0; i < MAX_SENSORS; ++i) {
        if (sensors[i].id != 0) {
            double sum = 0.0;
            int count = 0;
            for (int j = currReadingIndex - TIME_WINDOW; j < currReadingIndex; ++j) {
                if (j >= 0 && sensors[i].readings[j] != 0.0) {
                    sum += sensors[i].readings[j];
                    ++count;
                }
            }
            double average = count > 0 ? sum / count : 0.0;

            // Calculate deviation score and cumulative deviation score
            double currReading = sensors[i].readings[currReadingIndex];
            double deviationScore = calculateDeviation(currReading, average);
            sensors[i].cumulativeDeviationScore += deviationScore;

            // Write data to external storage system
            writeToStorage(&sensors[i]);
        }
    }
    pthread_mutex_unlock(&sensorMutex);
}

void addSensor(int id) {
    for (int i = 0; i < MAX_SENSORS; ++i) {
        if (sensors[i].id == 0) {
            sensors[i].id = id;
            break;
        }
    }
}

void addReading(int sensorId, double reading) {
    pthread_mutex_lock(&sensorMutex);
    for (int i = 0; i < MAX_SENSORS; ++i) {
        if (sensors[i].id == sensorId) {
            sensors[i].readings[currReadingIndex] = reading;
            break;
        }
    }
    pthread_mutex_unlock(&sensorMutex);
    ++currReadingIndex;
}

int main() {
    // Initialize and run the data processing thread
    pthread_t processDataThread;
    if (pthread_create(&processDataThread, NULL, (void *)&processData, NULL) != 0) {
        printf("Failed to create thread\n");
        return 1;
    }

    // Handle sensor data input and add it to the system
