        sscanf(line, "%d %lf", &sensorId, &reading);

        if (!isnan(sensors[sensorId].id)) {
            addSensor(sensorId);
        }

        addReading(sensorId, reading);
    }

    fclose(sensorInput);

    // Wait for the processing thread to finish
    pthread_join(processDataThread, NULL);

    return 0;
}
