["Below is a potential JavaScript code solution for this problem utilizing Promises and async/await syntax along with some utility functions from Lodash library:

```js
const _ = require('lodash');

function createAggregator(asyncCallback, config) {
  const defaultConfig = { timeout: 10000, maxRetries: 3, successThreshold: 0.9 };

  const conf = _.merge({}, defaultConfig, config);

  return async function aggregate(arr) {
    let total = 0;

    for (let i = 0; i < arr.length; i++) {
      console.log('Starting aggregation of element ' + i);

      const startTime = Date.now();

      try {
        await retry(i, asyncCallback(arr[i]), conf.timeout, conf.maxRetries);

        total += arr[i].value || 0;
      } catch (err) {
        console.log('Error in aggregation of element ' + i + ': ' + err);
      } finally {
        const completionTime = Date.now();

        console.log(`Completed aggregation of element ${i} in ${(completionTime - startTime) / 1000} seconds`);
      }
    }

    return total;
  };

  async function retry(id, promiseFactory, timeout, maxRetries) {
    let attempt = 1;
    let delay = initialDelay;

    while (attempt <= maxRetries) {
      try {
        const res = await Promise.race([promiseFactory(), timeoutPromise(timeout)]);

        if (!res || typeof res.value !== 'number') {
          throw new Error('Invalid value from async callback');
        }

        return res;
      } catch (err) {
        console.log(`Retry ${attempt} for element ${id}: ` + err);

        attempt++;
        delay *= 2; // exponential backoff strategy

        if (attempt > maxRetries || Date.now() - startTime >= timeout) {
          throw new Error('Maximum retries reached or timeout exceeded');
        }
      }
    }
  }

  function timeoutPromise(ms) {
    return new Promise((resolve, reject) => {
      setTimeout(() => reject(new Error('Timed out')), ms);
    });
  }
}
```

The `createAggregator` factory takes an asynchronous callback and a configuration object for retries. It returns an aggregation function that processes the array using the given callback, retrying failed calls based on the config's policy.

This solution uses Promises to handle async operations and error handling in a clean way. The `retry` helper function keeps retrying promises until it either completes successfully or reaches maximum retries, while maintaining the backoff strategy for delays between attempts. 

The `timeoutPromise` function returns a Promise that gets rejected after a given timeout. This is used to enforce timeouts on individual calls and on the entire process if required by the config. The `createAggregator` factory logs each step's start, progress, and completion times for debugging purposes. 

Please note this code is just a base example and doesn't include all possible edge cases or optimizations that could be done in a production environment.
"]

