#include <iostream>
#include <libxml/parser.h>
#include <libxml/tree.h>
#include <libxml/xpath.h>

std::string processXML(const std::string& str, int limit, const char* xmlPath, const char* elemName) {
    xmlDocPtr doc = xmlParseFile(xmlPath);

    if (doc == NULL) {
        return "Error loading XML document.";
    }

    xmlXPathContextPtr context = xmlXPathNewContext(doc);
    const std::string queryStr = "/" + std::string(elemName);
    xmlXPathObjectPtr result = xmlXPathEvalExpression((const unsigned char*)queryStr.c_str(), context);

    if (result == NULL || context->error) {
        return "Error evaluating XPath expression.";
    }

    xmlNodeSetPtr nodeset = result->nodesetval;

    std::string finalString(str);

    if (finalString.length() < limit && nodeset->nodeNr > 0) {
        finalString += '_';  // Append separator character
    }

    xmlXPathFreeObject(result);
    xmlXPathFreeContext(context);
    xmlFreeDoc(doc);

    if (nodeset->nodeNr == 1) {
        return finalString;
    } 
    else if (nodeset->nodeNr == 0) {
        return "Element not found.";
    } 
    else {
        return "Multiple elements found.";
    }
}
```
