double fetchContext(int event_id);

void processLogFile(char *filename) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Unable to open file\n");
        return;
    }

    char *line = NULL;
    size_t len = 0;
    ssize_t read;

    double totalSum = 0.0;
    int lineCount = 0;
    double lastFive[5] = {0};

    while ((read = getline(&line, &len, file)) != -1) {
        char *token, *str, *sub_str, *contextStr;
        char *delim = ",";
        double sum = 0.0;
        int numericCount = 0;

        str = malloc(read);
        sub_str = malloc(read);
        contextStr = calloc(1, 50);
        strcpy(sub_str, line);
        token = strtok(line, delim);

        while (token != NULL) {
            double num;

            if (sscanf(token, "%lf", &num) == 1) { // Check numeric
                sum += num;
                lastFive[numericCount % 5] = num;
                numericCount++;

                totalSum += num;
            } else if (strncmp(token, "EVT", 3) == 0) { // Check event ID
                int evt_id;

                if (sscanf(token + 3, "%d", &evt_id) == 1) {
                    double context = fetchContext(evt_id);

                    sprintf(contextStr + strlen(contextStr), " [EVT%d:%.2lf]", evt_id, context);
                }
            } else if (strchr(token, '.') != NULL) { // Check float
                double num;

                if (sscanf(token, "%lf", &num) == 1) {
                    sum += num;

                    lastFive[numericCount % 5] = num;
                    numericCount++;

                    totalSum += num;
                } else { // Invalid data type
                    free(str);
                    free(sub_str);
                    free(contextStr);

                    continue;
                }
            } else { // Check integer
                int num;

                if (sscanf(token, "%d", &num) == 1) {
                    sum += (double) num;
                    lastFive[numericCount % 5] = (double) num;
                    numericCount++;

                    totalSum += (double) num;
                } else { // Invalid data type
                    free(str);
                    free(sub_str);
                    free(contextStr);

                    continue;
                }
            }

            token = strtok(NULL, delim);
        }

        double average = 0.0;

        if (numericCount > 5) { // Check if numeric count is more than 5
            for (int i = 0; i < 5; ++i) {
                average += lastFive[i];
            }

            average /= 5.0;
        } else if (numericCount > 0) { // Check if numeric count is more than 0
            average = sum / (double) numericCount;
        }

        sprintf(contextStr + strlen(contextStr), " [avg:%.2lf]", average);
        printf("%s%s\n", sub_str, contextStr);
        lineCount++;
    }

    fclose(file);
    if (line) {
        free(line);
    }
}
```
