// AES-256-CBC cipher
void aes_cipher(const unsigned char *in, unsigned char *out, size_t length, const char *password) {
    unsigned char key[32]; // 256 bits = 32 bytes
    unsigned char iv[16]; // 128 bits = 16 bytes

    EVP_BytesToKey(EVP_aes_256_cbc(), EVP_sha256(), NULL, (unsigned char*)password, strlen(password), 1, key, iv);

    AES_KEY aeskey;
    AES_set_encrypt_key(key, 256, &aeskey);

    unsigned char ecount[16] = {0};
    unsigned int num = 0;
    AES_cbc_encrypt(in, out, length, &aeskey, iv, AES_ENCRYPT);
}

// Simple cache management using linked list and mutex for thread safety
typedef struct node {
    void *data; // replace with your own data structure
    struct node *next;
} Node;

Node *cache = NULL; 
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void add_to_cache(void *data) {
    pthread_mutex_lock(&lock); // mutex to prevent race condition while adding to cache

    Node *newNode = malloc(sizeof(Node)); 
    newNode->data = data;
    newNode->next = NULL;

    if (cache == NULL) { 
        cache = newNode;
    } else {
        Node *temp = cache;

        while (temp->next != NULL) { 
            temp = temp->next;
        }

        temp->next = newNode;
    }

    pthread_mutex_unlock(&lock); // unlock mutex
}
```

To handle multiple threads safely, each thread should have its own cipher context and cache entry. This can be done by creating a separate `AES_KEY` for each thread or by using OpenSSL's thread-local storage feature (see [here](https://www.openssl.org/docs/man1.0.2/crypto/threads.html) for more information).
"]

