```java
import java.io.*;
import java.util.concurrent.*;
import org.apache.commons.lang3.time.StopWatch;

public class CommandExecutor {
    private static final int MAX_RETRY = 3;

    public void executeCommand(String command) throws InterruptedException, ExecutionException {
        ExecutorService executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
        Future<Integer> future = executor.submit(() -> {
            Process process = Runtime.getRuntime().exec(command);
            StopWatch watch = new StopWatch();
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));) {
                watch.start();
                String line;
                while ((line = reader.readLine()) != null) {
                    System.out.println(line);
                }
            } catch (IOException e) {
                throw new RuntimeException("Failed to read process output.", e);
            } finally {
                watch.stop();
                System.out.println("Execution time: " + watch.getTime());
            }

            int exitCode = -1;
            try {
                exitCode = process.waitFor();
                System.out.println("Exit code: " + exitCode);
            } catch (InterruptedException e) {
                throw new RuntimeException(e);
            }

            return exitCode;
        });

        for (int i = 0; i < MAX_RETRY; ++i) {
            try {
                int exitCode = future.get();

                if (exitCode != 0) {
                    System.out.println("Command execution failed with exit code: " + exitCode);

                    // Rollback changes, restore config etc...
                    continue;
                }

                break;
            } catch (InterruptedException | ExecutionException e) {
                throw new RuntimeException(e);
            }
        }

        executor.shutdown();
    }

    public static void main(String[] args) throws InterruptedException, ExecutionException {
        CommandExecutor executor = new CommandExecutor();
        executor.executeCommand("ls");  // Sample command, replace with your actual commands.
    }
}
```
This program creates a fixed thread pool that matches the number of available processors on the system, then submits tasks to this executor service which run the given shell commands and wait for their completion. It includes a retry mechanism up to three times upon transient failures, logs detailed timestamps and exit codes for each command execution, and rolls back changes if a command fails.

