typedef struct Node {
    Record record;
    struct Node *next;
} Node;
```
We can then implement functions for inserting, deleting, updating nodes and managing the list:

```c
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;  // Thread-safe operation
Node* head = NULL;  // Start of linked list

void insert(Record record) {
    pthread_mutex_lock(&lock);  // Lock to ensure thread safety

    Node *newNode = malloc(sizeof(Node));  
    newNode->record = record;
    newNode->next = head;
    head = newNode;

    pthread_mutex_unlock(&lock);  // Unlock after operation
}

void delete(char *key) {
    pthread_mutex_lock(&lock);  

    Node *temp = head, *prev;
    if (temp != NULL && strcmp(temp->record.key, key) == 0) {  // If the key matches head's key
        head = temp->next;
        free(temp);  
        return;
    }

    while (temp != NULL && strcmp(temp->record.key, key) != 0) {  
        prev = temp;
        temp = temp->next;
    }

    if (temp == NULL)  // Key not found
        return;

    prev->next = temp->next;  
    free(temp);  

    pthread_mutex_unlock(&lock);
}
```
