        try (FileInputStream fis = new FileInputStream(new File(this.storagePath))) {
            ObjectInputStream ois = new ObjectInputStream(fis);

            // Read the list of Struct objects from file
            structs = (List<Struct>)ois.readObject();
        } catch(IOException | ClassNotFoundException ioe) {
           logger.error("Error while reading data from storage", ioe);
        } 

        return structs;
    }

    public List<Struct> getStructs() {
        List<Struct> structs = null;

        try (Jedis jedis = this.pool.getResource()) {
            if(jedis.exists("structs")) {
                // If the data is cached, retrieve it from cache. 
                structs = (List<Struct>)jedis.get("structs");
            } else {
                // Otherwise read from storage and then store in cache for future use.
                structs = this.readStructsFromStorage();

                jedis.set("structs", structs);
            }
        } catch(JedisConnectionException jce) {
           logger.error("Redis is down, using cached data or fallback mechanism", jce);
        } 

        return structs;
    }

    // This method will be called in case of any error or when the Redis server is down. 
    public void fallBack() {
      logger.warn("Fallback condition, using cached data");

      // Use the cached data and notify system administrator
    }
}
```
