async function uploadFileFromURL(fileUrl, loggingService = console, notificationService = notify) {
  if (!validUrl.isUri(fileUrl)) throw new Error('Invalid URL');

  const url = new URL(fileUrl);
  if (!TRUSTED_DOMAINS.includes(url.hostname)) throw new Error('Unauthorized domain');

  const fileStream = fs.createWriteStream(path.basename(fileUrl));
  let uploadInProgress = true;

  // File upload process with timeout, progress tracking and logging
  try {
    const startTime = Date.now();

    while (uploadInProgress) {
      if (Date.now() - startTime > TIMEOUT) throw new Error('Upload timed out');

      const response = await fetch(fileUrl);
      const data = await response.buffer();

      // Check file size and reject large files
      if (data.length > MAX_FILE_SIZE) {
        uploadInProgress = false;
        throw new Error('File too large');
      }

      fs.writeFileSync(fileStream, data);
      loggingService.log(`Upload progress: ${(data.length / MAX_FILE_SIZE * 100).toFixed(2)}%`);
    }

    // Notify successful upload
    notificationService('Upload successful');
  } catch (error) {
    // Notify about failure and rethrow the error
    notificationService(`Upload failed: ${error.message}`);
