['Here is the code for managing user sessions in PHP using Redis for session storage. Please note that this is just a starting point and you might need to adjust it according to your application's requirements. Also, please handle error handling properly before you use it in production.

```php
<?php
class SessionManager {
    private $redis;

    public function __construct() {
        $this->redis = new Redis();
        if(!$this->redis->connect('127.0.0.1', 6379)) throw new Exception('Unable to connect to Redis server');
    }

    public function handleRequest(array $request) {
        $sessionId = $request['session_id'] ?? null;
        $username = $request['username'] ?? null;
        $password = $request['password'] ?? null;
        $subAction = $request['sub_action'] ?? null;

        if($subAction === 'logout') {
            return $this->handleLogOut();
        } 

        if ($sessionId) {
            return $this->verifyAndExtendSession($sessionId);
        } elseif ($username && $password) {
            $user = $this->validateUserFromAuthService($username, $password);

            if ($user) {
                return $this->handleLogin($user);
            } else {
                return ['message' => 'error', 'session_id' => null];
            }
        } 
    }

    private function verifyAndExtendSession(string $sessionId) {
        $user = $this->redis->get('session:' . $sessionId);

        if ($user) {
            $newSessionId = $this->generateNewSession();
            $this->redis->setex("session:" . $newSessionId, 3600, $user);

            return ['message' => 'success', 'session_id' => $newSessionId];
        } else {
            return ['message' => 'error', 'session_id' => null];
        }
    }

    private function handleLogin(array $user) {
        $newSessionId = $this->generateNewSession();

        $this->redis->setex("session:" . $newSessionId, 3600, json_encode($user));

        return ['message' => 'success', 'session_id' => $newSessionId];
    }

    private function handleLogOut() {
        $this->redis->del('session:' . $this->getCurrentSession());

        return ['message' => 'logged out'];
    }

    // To be implemented: interaction with an external authentication service
    private function validateUserFromAuthService(string $username, string $password) {
        $user = [];
        // Implement the validation here. You might use a database query or API call to check credentials

        return $user;
    }

    private function generateNewSession() {
        return bin2hex(random_bytes(16));
    }

    private function getCurrentSession() {
        // Implement this based on your application's session management strategy
    }
}
?>
```
