    public function __construct() {
        $this->client = new OAuth2\Client(CLIENT_ID, CLIENT_SECRET);
    }

    public function authenticateUser() {
        // Set the grant type to client credentials (our PHP server will act as a client)
        $this->client->setGrantType(OAuth2\Client::GRANT_TYPE_CLIENT_CREDENTIALS);

        // Request a new access token and refresh token
        $response = $this->client->getAccessToken();

        if ($response && isset($response['access_token'])) {
            // Store the access token in a secure session variable
            $_SESSION['access_token'] = $response['access_token'];

            return true;
