```c
#include <pthread.h>
#include <stdio.h>

typedef struct {
    int log_level;
    char* config_path;
} LogConfig;

static pthread_rwlock_t rwlock = PTHREAD_RWLOCK_INITIALIZER;
static LogConfig* currentConfig = NULL;

int initLoggingSystem(char* config_file, int logLevel) {
    FILE *fptr = fopen(config_file, "r");

    if (fptr == NULL){
        printf("Unable to open file.\n");
        return -1;  // or handle error as needed
    }

    LogConfig* newConfig = malloc(sizeof(LogConfig));
    if (!newConfig) {
        printf("Failed to allocate memory for log configuration\n");
        return -1;  // or handle error as needed
    }

    /* parse config file and populate newConfig */
    // ...

    pthread_rwlock_wrlock(&rwlock);
    if (currentConfig) {
        free(currentConfig);
    }
    currentConfig = newConfig;
    pthread_rwlock_unlock(&rwlock);

    fclose(fptr);
    return 0; // success
}

void logMessageAtLevel(int level, char* message) {
    LogConfig* configToUse;
    int currentLogLevel = 0;

    pthread_rwlock_rdlock(&rwlock);
    if (currentConfig) {
        configToUse = currentConfig;
        currentLogLevel = configToUse->log_level;
    } else {
        /* fallback to default log level */
        // ...
    }
    pthread_rwlock_unlock(&rwlock);

    if (level >= currentLogLevel) {
        printf("%s\n", message);
        // ... further processing, i.e., logging to external services 
    }
}
```

This is a basic setup and doesn't handle all edge cases such as log file rotation or complex error handling. In real-world use case you would probably want to have more robust error handling (i.e., using setjmp/longjmp for non-local exits, error enums etc.) and more advanced memory management techniques (like pool allocators). 

