    long len = ftell(f);
    fseek(f, 0, SEEK_SET);

    char* buffer = malloc(len + 1);
    if (!buffer) {
        return -2;
    }

    fread(buffer, 1, len, f);
    fclose(f);
    buffer[len] = 0;

