    free(buffer);
    if (!json) {
        return -3;
    }

    pthread_mutex_lock(&mutexlock);
    config.timeout = cJSON_GetObjectItem(json, "timeout")->valueint;
    config.retry_limits = cJSON_GetObjectItem(json, "retry_limits")->valueint;
    pthread_mutex_unlock(&mutexlock);

    cJSON_Delete(json);
    return 0;
}

