["Here's a rough sample code in C that meets your requirements, but it doesn't cover all aspects you've asked for due to its complexity. Please consider this as a starting point and further enhancements are necessary based on actual use cases:

```c
#include <pthread.h>
#include <stdlib.h>
#include <string.h>

// Forward declaration of 'entry' structure for simplicity
typedef struct entry Entry;

struct bucket {
    pthread_mutex_t lock;
    Entry** entries; // Array of pointers to entries
};

struct entry {
    char* key; // Unique string identifier
    void* payload; // Pointer to data payload
    struct bucket* parentBucket; // Back pointer to the containing bucket
};

typedef struct dht_data {
    int numBuckets;
    struct bucket* buckets; // Array of buckets
} DHTData;

// Hash function for mapping keys to bucket indices
unsigned long hash(const char *str)
{
    unsigned long hash = 5381;
    int c;

    while ((c = *str++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */

    return hash;
}

// Allocate and initialize the DHT
DHTData* create_dht(int numBuckets, int bucketSize){
    DHTData* d = malloc(sizeof(DHTData));

    // Allocate buckets
    d->numBuckets = numBuckets;
    d->buckets = calloc(d->numBuckets, sizeof(struct bucket));

    for (int i = 0; i < d->numBuckets; i++){
        pthread_mutex_init(&(d->buckets[i].lock), NULL);
        // Allocate entries in each bucket
        d->buckets[i].entries = calloc(bucketSize, sizeof(Entry*));
    }

    return d;
}

// Insert an entry to the DHT
void insert_dht(DHTData *d, const char* key, void* payload){
    // Map the key to a bucket index using our hash function
    unsigned long bucketIdx = hash(key) % d->numBuckets;

    pthread_mutex_lock(&(d->buckets[bucketIdx].lock));
    for (int i = 0; i < bucketSize; i++){
        // Find an empty slot in the bucket
        if (d->buckets[bucketIdx].entries[i] == NULL){
            Entry* e = malloc(sizeof(Entry));
            e->key = strdup(key);
            e->payload = payload;
            e->parentBucket = &(d->buckets[bucketIdx]);

            d->buckets[bucketIdx].entries[i] = e;
            break;
        }
    }
    pthread_mutex_unlock(&(d->buckets[bucketIdx].lock));
}
``` 

This is a basic implementation that includes a simple hash function to distribute keys, uses mutex locks for synchronization and supports insert operations. You may want to add more features such as deletion, search and update operations in your real-world application scenario. Also, remember always to free the memory allocated to avoid leaks.
"]

