$dotenv->load();

use Psr\Log\LoggerInterface;
use Monolog\Handler\StreamHandler;
use Monolog\Logger;
use Symfony\Component\Lock\StoreInterface;
use Symfony\Component\Lock\Factory;
use SplQueue;
use Spatie\Async\Pool;

class MemoryManager {
    private $pool;
    private $queue;

    public function __construct(LoggerInterface $logger, StoreInterface $store) {
        $factory = new Factory($store);
        $this->lock = $factory->createLock('memory');
        $this->pool = Pool::create();
        $this->queue = new SplQueue(); // Using PHP's built-in Queue for a circular queue
    }

    public function addRecord($key, $offset) {
        if (!$this->lock->acquire()) {
            throw new \RuntimeException('Unable to acquire the lock.');
        }

        $record = ['key' => $key, 'offset' => $offset];
        $this->queue->enqueue($record);

        $this->lock->release();
    }

    public function removeRecord() {
        if (!$this->lock->acquire()) {
            throw new \RuntimeException('Unable to acquire the lock.');
        }

        if(count($this->queue) > 0){
            $record = $this->queue->dequeue();
        } else{
            $record = null;
        }

        $this->lock->release();
    }
}
?>
```
The example above uses a SplQueue which is a circular queue in PHP. The locking mechanism was implemented using Symfony's Lock component, which allows you to handle critical sections of code that should not be executed by more than one thread at the same time.

