['Here is the C code that meets all the requirements you've specified. It uses POSIX threading model for concurrency, error logging via fprintf(), and dynamic memory allocation and deallocation using malloc() and free(). Note that the program doesn't currently handle command-line arguments or multiple files. 

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Structure to hold a line of numbers
typedef struct {
    double* numbers; // Dynamically allocated array of doubles
    int size;        // Size of the array
} LineData;

// Function to process a line of text, dynamically allocate memory for its elements, sort them and calculate average.
LineData* process_line(const char* line, FILE* logFile) {
    LineData* data = malloc(sizeof(LineData)); // Allocate memory for the structure

    int maxSize = 10; // Initial maximum size of the array
    data->numbers = malloc(maxSize * sizeof(double)); // Allocate initial memory for numbers
    data->size = 0;  // Initialize current number count

    char* numStr = strtok((char*)line, " "); // Tokenize the line by spaces

    while (numStr != NULL) {
        double value = atof(numStr); // Convert string to double

        if (value == 0.0 && strcmp(numStr, "0") != 0) { 
            fprintf(logFile, "Non-numeric value skipped: %s\n", numStr); // Log non-numeric values to the log file
        } else {
            if (data->size == maxSize) { // Check if we need more space for new number
                maxSize *= 2;  // Double the maximum size of array
                data->numbers = realloc(data->numbers, maxSize * sizeof(double)); // Reallocate memory with increased size
            }

            data->numbers[data->size++] = value;  // Add number to the array and increase count
        }

        numStr = strtok(NULL, " "); // Get next token
    }

    qsort(data->numbers, data->size, sizeof(double), compare); // Sort numbers in ascending order using quicksort

    double sum = 0.0;  // Calculate average of sorted numbers
    for (int i = 0; i < data->size; ++i) {
        sum += data->numbers[i];
    }
    double avg = sum / data->size;

    if(data->size > 0)  // If array is not empty, append average to the end
        data->numbers = realloc(data->numbers, (++data->size)* sizeof(double));
        data->numbers[data->size - 1] = avg;

    return data; // Return filled structure with sorted numbers and their average appended
}

// Function to compare doubles for qsort
int compare (const void * a, const void * b) {
   if (*(double*)a > *(double*)b) 
      return 1;
   else if (*(double*)a < *(double*)b) 
      return -1;
   else 
      return 0;
}

// Function to handle lines in a separate thread
void* process_line_thread(void* arg) {
    // Extract the line and log file from argument structure
    char* line = ((char**)arg)[0];
    FILE* logFile = fopen(((char**)arg)[1], "w");

    LineData* data = process_line(line, logFile);  // Process line of text

    for (int i = 0; i < data->size; ++i) {  // Print the processed numbers to standard output
        printf("%f ", data->numbers[i]);
    }
    printf("\n");

    free(data->numbers); // Free dynamically allocated memory
    free(data);          // Free structure

    fclose(logFile);      // Close log file
    return NULL; 
}

int main() {
    char* line = "5.2 -10 3 7";  // Dummy line of text for testing
    FILE* logFile = fopen("log.txt", "w");  // Open log file in write mode

    pthread_t thread;   // Create a new thread to handle the line
    char** arg = malloc(sizeof(char*) * 2);  // Argument structure for thread function
    arg[0] = line;      // First argument is the line of text
    arg[1] = "log.txt"; // Second argument is the log file name

    pthread_create(&thread, NULL, process_line_thread, (void*)arg);  // Start thread to handle line of text

    pthread_join(thread, NULL);  // Wait for thread to finish before exiting program

    free(arg);   // Free argument structure
    return 0;
}
```
