    strcpy(newNode->DL_Layer_Indication, DL_Layer_Indication);
    strcpy(newNode->DMRS_Configuration, DMRS_Configuration);
    newNode->next = NULL;
    return newNode;  // return new node pointer
}

void addMessage(char *DL_Layer_Indication, char *DMRS_Configuration) {
    pthread_mutex_lock(&lock);  // acquire lock to prevent data corruption in multithreaded environment

    DCI_message *newNode = createMessage(DL_Layer_Indication, DMRS_Configuration);

    fprintf(logFile,"ADD: %s - %s\n", DL_Layer_Indication, DMRS_Configuration);  // write to log file

    if (head == NULL) {
        head = newNode;
    } else {
        DCI_message *last = head;
        while(last->next != NULL){
            last = last->next;
        }
        last->next = newNode;
    }

    pthread_mutex_unlock(&lock);  // release lock after operation
}

void deleteMessage(char *DL_Layer_Indication) {
    pthread_mutex_lock(&lock);

    DCI_message *temp = head, *prev;

    if (temp != NULL && strcmp(temp->DL_Layer_Indication, DL_Layer_Indication) == 0) {  // message to be deleted is the first in list
        head = temp->next;
        fprintf(logFile,"DELETE: %s\n", DL_Layer_Indication);
        free(temp);
        pthread_mutex_unlock(&lock);
        return;
    }

    // Find the message to be deleted and its previous node in list
    while (temp != NULL && strcmp(temp->DL_Layer_Indication, DL_Layer_Indication) != 0){ 
        prev = temp;
        temp = temp->next;
    }

    // Message not found in list
    if (temp == NULL) {
        fprintf(logFile,"DELETE: FAILED\n");
        pthread_mutex_unlock(&lock);
        return; 
