typedef struct {
    int value;
} record;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
long* offsets;
int* keys;
record* records;

void initArrays() {
    srand(time(NULL));   // initialize random seed

    int fd = shm_open("/my_shm", O_CREAT | O_RDWR, 0600);
    if (fd < 0) { perror("Error creating shared memory object"); exit(1); }

    offsets = mmap(NULL, 10000 * sizeof(long), PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    keys = mmap(NULL, 10000 * sizeof(int), PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    records = mmap(NULL, 10000 * sizeof(record), PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);

    if (offsets == MAP_FAILED || keys == MAP_FAILED || records == MAP_FAILED) { perror("Error mapping memory"); exit(1); }

    for(int i = 0; i < 10000; ++i){
        offsets[i] = rand(); // initialize with random value
        keys[i] = rand(); 
        records[i].value = rand() % (upper - lower + 1) + lower; // initialize 'int' field to a random value within a specified range.
    }
}

void* write_records(void *ptr){
    int index = *((int *) ptr);
    for(int i=0; i<100; ++i){
        pthread_mutex_lock(&mutex);
        records[index].value += rand(); // simulate frequent write operations
        pthread_mutex_unlock(&mutex); 
    }
}

void* read_records(void *ptr){
    int index = *((int *) ptr);
    for(int i=0; i<100; ++i){
        pthread_mutex_lock(&mutex);
        printf("%d\n", records[index].value); // simulate frequent read operations
        pthread_mutex_unlock(&mutex); 
    }
}
```

