For implementing LRU cache with thread safety, we might use a combination of pthreads and linked list. Here is a simple version:

```C
#include <pthread.h>
#define MAX_SIZE 10000
struct Node {
   int key;
   struct Node *next;
   struct Node *prev;
};

struct Cache {
   pthread_mutex_t lock;
   struct Node *head, *tail;
   unsigned int size;
} cache;

void initCache() {
    cache.size = 0;
    cache.head = NULL;
    cache.tail = NULL;
    pthread_mutex_init(&cache.lock, NULL);  // Initialize mutex
}
```
Adding elements to the linked list and maintaining LRU:

```C
void addToCache(int key) {
   pthread_mutex_lock(&cache.lock);
   struct Node *node = (struct Node*) malloc(sizeof(struct Node));
   node->key = key;
   node->next = cache.head;
   if(cache.size == 0) {
       cache.tail = node;
   } else {
       cache.head->prev = node;
   }
   cache.head = node;
   ++cache.size;
   if(cache.size > MAX_SIZE) {
       struct Node *tmp = cache.tail;
       cache.tail = cache.tail->prev;
       free(tmp);  // Remove LRU element
   }
   pthread_mutex_unlock(&cache.lock);
}
```
