#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <pthread.h>

typedef struct record {
    int value;
} Record;

typedef struct cache_entry {
    char* hostname;
    char ip[INET6_ADDRSTRLEN];
    pthread_mutex_t mutex;
    struct cache_entry* next;
} CacheEntry;

CacheEntry* cache = NULL;
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;

void* resolve(void* arg) {
    char* hostname = (char*)arg;

    struct addrinfo hints, *res, *p;
    int status;
    void* addr;
    char ipstr[INET6_ADDRSTRLEN];

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC; // either IPv4 or IPv6
    hints.ai_socktype = SOCK_STREAM; // TCP stream sockets
    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return NULL;
    }

    pthread_mutex_lock(&cache_lock);
    for (p = res; p != NULL; p = p->ai_next) {
        if (p->ai_family == AF_INET) { // IPv4
            addr = &((struct sockaddr_in*)p->ai_addr)->sin_addr;
            inet_ntop(p->ai_family, addr, ipstr, sizeof(ipstr));
        } else { // IPv6
            addr = &((struct sockaddr_in6*)p->ai_addr)->sin6_addr;
            inet_ntop(p->ai_family, addr, ipstr, sizeof(ipstr));
        }

        CacheEntry* new_entry = malloc(sizeof(CacheEntry));
        if (!new_entry) {
            fprintf(stderr, "Memory allocation error\n");
            return NULL;
        }

        new_entry->hostname = strdup(hostname);
        if (!new_entry->hostname) {
            fprintf(stderr, "Memory allocation error\n");
            free(new_entry);
            return NULL;
        }

        strncpy(new_entry->ip, ipstr, sizeof(new_entry->ip));
        new_entry->next = cache;
        pthread_mutex_init(&new_entry->mutex, NULL);
        pthread_mutex_lock(&new_entry->mutex);
        cache = new_entry;
    }
    pthread_mutex_unlock(&cache_lock);

    freeaddrinfo(res); // free the linked list
    return NULL;
}

Record* resolveHostnames(char** hostnames, int nhosts) {
    Record* records = calloc(nhosts, sizeof(Record));
    if (!records) {
        fprintf(stderr, "Memory allocation error\n");
        return NULL;
    }

    pthread_t threads[nhosts];
    for (int i = 0; i < nhosts; ++i) {
        if (pthread_create(&threads[i], NULL, resolve, hostnames[i])) {
            fprintf(stderr, "Thread creation error\n");
            free(records);
            return NULL;
        }
    }

    for (int i = 0; i < nhosts; ++i) {
        pthread_join(threads[i], NULL);
    }

    srand(time(NULL)); // seed the random number generator
    for (int i = 0; i < nhosts; ++i) {
        records[i].value = rand() % 100 + 1; // a value in the range [1, 100]
    }

    return records;
}
```
