typedef struct Record {
    int value;
    int* key;
} Record;

typedef struct Node {
    Record* record;
    struct Node* next;
    struct Node* prev;
} Node;

Node* createList(size_t size, long* offsets, int* keys, int minVal, int maxVal) {

    if (size <= 0 || !offsets || !keys) {
        fprintf(stderr, "Invalid argument\n");
        return NULL;
    }

    Record** records = malloc(size * sizeof(Record*));
    Node* head = NULL;
    Node* prevNode = NULL;

    for (size_t i = 0; i < size; ++i) {

        // Allocate memory for record and key
        records[i] = malloc(sizeof(Record));
        if (!records[i]) {
            fprintf(stderr, "Memory allocation failed\n");
            return NULL;  // Handle error: free all previous allocations before returning
        }

        // Initialize record and key
        records[i]->value = minVal + rand() % (maxVal - minVal + 1);
        records[i]->key = &keys[(int)offsets[i]];  // Assuming offsets are within keys array bounds

        Node* newNode = malloc(sizeof(Node));
        if (!newNode) {
            fprintf(stderr, "Memory allocation failed\n");
            return NULL;  // Handle error: free all previous allocations before returning
        }
        newNode->record = records[i];

        // Link node to list
        if (prevNode) {
            prevNode->next = newNode;
            newNode->prev = prevNode;
        } else {
            head = newNode;
        }
        newNode->next = NULL;  // End of list

        prevNode = newNode;
    }

    if (head) {
        Node* tail = prevNode;  // Last node in the list
        tail->next = head;
        head->prev = tail;
    }

    return head;
}
```
This code creates a circular doubly linked list of `Record` structures, each containing an integer value and a pointer to its corresponding key. The size of the list is given by the input parameter `size`, and the values for keys are randomly generated between `minVal` and `maxVal` (inclusive).

Note that memory allocation failure isn't handled in the best way here, as it would require freeing all previously allocated records before returning. A more comprehensive error handling mechanism could be implemented to ensure no resource leaks occur in case of failure. Also note that this code doesn't yet manage any potential performance bottlenecks from high load conditions and does not include optimization for either memory usage or execution speed.
