    // Lock the bucket to ensure thread safety
    pthread_mutex_lock(&dht->buckets[index]->lock);

    for (size_t i = 0; i < dht->buckets[index]->size; ++i) {
        if (!strcmp(key, dht->buckets[index]->entries[i]->key)) {
            pthread_mutex_unlock(&dht->buckets[index]->lock);
