#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <stdint.h>

// Define record structure
typedef struct Record {
    int64_t offset;
    int key;
    void* value;
    struct Record *next;
} Record;

// Define linked list structure and its mutex
typedef struct LinkedList {
    Record *head;
    sem_t semaphore;
} LinkedList;

// Custom memory allocator
Record* createRecord(int64_t offset, int key, void* value) {
    Record *record = malloc(sizeof(Record));
    record->offset = offset;
    record->key = key;
    record->value = value;
    return record;
}

// Initialization of linked list and its mutex
void initializeLinkedList(LinkedList *list) {
    sem_init(&list->semaphore, 0, 1);
    list->head = NULL;
}

// Adding records to the linked list with thread safety
void addRecord(LinkedList *list, Record* record) {
    sem_wait(&list->semaphore);

    if (list->head == NULL) {
        list->head = record;
        record->next = record; // Making it circular
    } else {
        Record *current = list->head;
        while(current->next != list->head) current = current->next; 
        current->next = record;
        record->next = list->head;
    }

    sem_post(&list->semaphore);
}

// Retrieving a record from the linked list with thread safety
Record* getRecord(LinkedList *list, int key) {
    sem_wait(&list->semaphore);

    Record *current = list->head;
    do {
        if (current->key == key) {
            sem_post(&list->semaphore);
            return current;
        }
        current = current->next;
    } while(current != list->head); 

    sem_post(&list->semaphore);
    return NULL; // Record not found
}

// Serialization mechanism (simplified)
void serializeList(LinkedList *list, FILE* file) {
    fwrite(&list->head, sizeof(Record), 1, file);
}
