typedef struct record {
    long *offset;
    int key;
} record_t;

int checkPrime(int num) {
    if (num <= 1) return 0;
    for (int i = 2; i <= sqrt(num); i++) {
        if (num % i == 0) {
            return 0;
        }
    }
    return 1;
}

record_t *allocateMemory(size_t size, long max_offset, int max_key) {
    // allocate memory for offset and key arrays
    long* offsetArray = (long*)malloc(sizeof(long)*size);
    if(!offsetArray){
        return NULL; // handle allocation failure
    }
    memset(offsetArray, -1, sizeof(long)*size);

    int* keyArray = (int*)malloc(sizeof(int)*size);
    if(!keyArray){
        free(offsetArray);
        return NULL; // handle allocation failure
    }
    memset(keyArray, -1, sizeof(int)*size);

    record_t *recordArray = (record_t*)malloc(sizeof(record_t)*size);
    if(!recordArray){
        free(offsetArray);
        free(keyArray);
        return NULL; // handle allocation failure
    }
    memset(recordArray, 0, sizeof(record_t)*size);

    for (size_t i = 0; i < size; ++i) {
        offsetArray[i] = rand() % max_offset;

        int key;
        do{
            key = rand() % max_key;
        }while(!checkPrime(key));

        // Ensure uniqueness
        for (size_t j = 0; j < i; ++j) {
            if (keyArray[j] == key || offsetArray[i] == key) {
                --i; 
                continue;
            }
        }

        recordArray[i].offset = &(offsetArray[i]);
        recordArray[i].key = key;
    }

    // Cleanup upon failure
    /*if (!recordArray) {
        free(offsetArray);
        free(keyArray);
        return NULL;
    }*/

    return recordArray;
}
