['The following Python function implements the requirements using `concurrent.futures` for parallel processing, `os.walk()` to traverse directories recursively, and `hashlib.sha256()` for checksum generation. It also uses a `datetime` object to track timestamps and a progress indicator.

```python
import os
import hashlib
from datetime import datetime
import concurrent.futures

def generate_checksums(directory, file_types=None, chunk_size=50 * 1024 * 1024):
    if not file_types:
        file_types = []

    start_time = datetime.now()
    files_processed = 0
    total_size = 0
    excluded_files = 0
    checksums = {}
    timestamps = {}

    with concurrent.futures.ProcessPoolExecutor(max_workers=5) as executor:
        for root, _, files in os.walk(directory):
            futures = []

            for file in files:
                if any(file.endswith(ftype) for ftype in file_types):
                    excluded_files += 1
                    continue

                filename = os.path.join(root, file)
                try:
                    futures.append(executor.submit(_get_checksum, filename, chunk_size))
                except PermissionError:
                    print(f'Permission denied for {filename}')

            for future in concurrent.futures.as_completed(futures):
                files_processed += 1

                try:
                    filename, checksum = future.result()
                    total_size += os.path.getsize(filename)

                    timestamps[filename] = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
                    checksums[filename] = {
                        'checksum': checksum, 
                        'last_modified': os.path.getmtime(filename),
                        'size': os.path.getsize(filename)
                    }
                except Exception as e:
                    print(f'Error processing file: {e}')

                if files_processed % 50 == 0 or files_processed == len(files):
                    _print_progress(start_time, files_processed, total_size)

    return checksums, timestamps, excluded_files, total_size

def _get_checksum(filename, chunk_size=50 * 1024 * 1024):
    sha256 = hashlib.sha256()

    with open(filename, 'rb') as f:
        while True:
            data = f.read(chunk_size)

            if not data:
                break

            sha256.update(data)

    return filename, sha256.hexdigest()

def _print_progress(start_time, files_processed, total_size):
    current_time = datetime.now()
    elapsed_time = (current_time - start_time).total_seconds()

    avg_processing_speed = 'N/A' if elapsed_time == 0 else f"{files_processed / elapsed_time:.2f} files/sec"
    print(f'\nProcessed {files_processed} files, total size: {total_size // (1024 * 1024)} MB')
    print(f'Average processing speed: {avg_processing_speed}, Elapsed time: {elapsed_time:.2f} secs\n')
```

Please use this function as a starting point and modify it to meet your specific needs. Keep in mind that parallel processing might consume significant system resources, so you need to find a balance between speed, memory usage, and stability. Also, the error handling could be improved for more robustness.
']

