void initializeRecords(size_t size) {
    long* offsets = (long*)malloc(size * sizeof(long));
    if (!offsets) {
        printf("Failed to allocate memory for offsets\n");
        return;
    }

    int* keys = (int*)malloc(size * sizeof(int));
    if (!keys) {
        free(offsets);
        printf("Failed to allocate memory for keys\n");
        return;
    }

    record* records = (record*)malloc(size * sizeof(record));
    if (!records) {
        free(offsets);
        free(keys);
        printf("Failed to allocate memory for records\n");
        return;
    }

    srand((unsigned int)time(NULL)); // initialize random number generator
    const int range_min = 0, range_max = 100;

    for (size_t i = 0; i < size; ++i) {
        offsets[i] = rand(); // assign a random value to each offset
        keys[i] = rand() % (range_max - range_min + 1) + range_min; // assign a random value within the specified range to each key
        records[i].value = keys[i]; // assign the same value as its corresponding key in the record array
    }

    free(offsets);
    free(keys);
    free(records);
}
```

