    if !path.exists() {
        fs::create_dir(&path)?;

        match env::var(env_var) {
            Ok(_) => warn_backingup_and_set_env_var(env_var, &format_args(&[dir_name]).to_string(), path),
            Err(_) => set_env_var(env_var, &path.display().to_string()),
        }
    } else {
        warn_backingup_and_set_env_var(env_var, &format_args(&[dir_name]).to_string(), path);
    }

    Ok(())
}

fn set_env_var(key: &str, value: &str) {
    env::set_var(key, value);
}

fn warn_backingup_and_set_env_var(env_var: &str, dir_name: &str, path: PathBuf){
    let backup_path = PathBuf::from(&format_args(&[dir_name, "_backup"]).to_string());

    if !backup_path.exists() {
        warn_on_failed(move || fs::create_dir(&backup_path), "Failed to create backup directory");

        set_env_var(env_var, &format_args(&[dir_name, "_backup"]).to_string());
    } else {
        warn("Backup path already exists. Please delete or rename it and try again.",);
    }
}
```
