double maxLimit = 1000.0;  // Initial maximum limit, may change dynamically
pthread_mutex_t lock;
FILE *filePtr = NULL;

// Function to initialize the records from a file
void loadRecordsFromFile(const char* filename) {
    FILE* fp = fopen(filename, "r");
    if (fp == NULL) {
        printf("Error opening file\n");
        return;
    }

    // Read records from the file and add to our list
    // Assuming format is key weight offset in each line
    while(!feof(fp)) {
        Record rec;
        fscanf(fp, "%d %lf %ld", &rec.key, &rec.weight, &rec.offset);

        addRecord(&rec);  // Assume we have a function to add record
    }

    fclose(fp);
}

// Function to add new record and ensure total weight doesn't exceed limit
void addRecord(const Record* rec) {
    pthread_mutex_lock(&lock);  // Lock for thread-safety

    if (records == NULL) {
        records = malloc(sizeof(Record));
    } else {
        double totalWeight = 0.0;
        for (int i = 0; i < recordCount; ++i) {
            totalWeight += records[i].weight;
        }

        if ((totalWeight + rec->weight) > maxLimit) {
            printf("Error: Total weight will exceed limit\n");
            pthread_mutex_unlock(&lock);  // Unlock before returning
            return;
        }

        records = realloc(records, (recordCount + 1)*sizeof(Record));
    }

    records[recordCount++] = *rec;  // Add new record and increment counter

    pthread_mutex_unlock(&lock);  // Unlock after operation
}

// Function to update a record
void updateRecord(int key, double weight, long offset) {
    pthread_mutex_lock(&lock);  // Lock for thread-safety

    for (int i = 0; i < recordCount; ++i) {
        if (records[i].key == key) {
            records[i].weight = weight;
            records[i].offset = offset;

            break;  // Found and updated, exit loop
        }
    }

    pthread_mutex_unlock(&lock);  // Unlock after operation
}

// Function to save all records to a file
void saveRecordsToFile(const char* filename) {
    FILE* fp = fopen(filename, "w");
    if (fp == NULL) {
        printf("Error opening file\n");
        return;
    }

    // Write all records to the file in same format as load function
    for (int i = 0; i < recordCount; ++i) {
        fprintf(fp, "%d %lf %ld\n", records[i].key, records[i].weight, records[i].offset);
    }

    fclose(fp);
}
``` 
This code implements a basic structure for managing dynamic collections of 'records'. It handles the loading and saving to files, adding and updating records, and ensuring that the total weight does not exceed a specified limit. The records are stored in an array and the memory is managed manually to ensure efficiency. However, this example does not integrate with a database or handle concurrent updates from multiple clients.

Implementing such features would require significantly more code and a deep understanding of your specific requirements, database structure, caching strategy, logging mechanism and monitoring tools you are using. I recommend breaking down the task into smaller tasks and implementing them one by one.
