```C
#include <stdio.h>
#include <stdlib.h>

typedef struct Record {
    int value;
    int* key; // You could use an array or pointer here depending on the actual need.
} Record;

typedef struct Node {
    long offsetValue;
    int key;
    Record record;
    struct Node *next;  // Pointer to the next node
} Node;

Node* createNode(long offset, int key, Record rec) {
    Node* new_node = (Node*) malloc(sizeof(Node));

    if (new_node == NULL) {
        printf("Memory allocation failed\n");
        exit(0);  // Terminate the program upon failure to allocate memory.
    }

    new_node->offsetValue = offset;
    new_node->key = key;
    new_node->record = rec;
    new_node->next = NULL;

    return new_node;
}

void insertNode(Node** head, long offset, int key, Record rec) {
    Node* new_node = createNode(offset, key, rec);

    if(*head == NULL){
        *head = new_node;
    } 
    else {
        Node* last = *head;

        // Navigate to the last node in the list.
        while (last->next != NULL) {
            last = last->next;
        }

        last->next = new_node;  // Insert the new node at the end of the list.
    }
}
```
