['Creating a semaphore management system in C# that meets all these requirements is complex and beyond simple code examples provided here due to its intricacies and various considerations needed for each feature. However, I will provide an outline of how such a system might be structured:

```csharp
using System;
using System.Collections.Concurrent;
using System.Threading;
using Microsoft.Extensions.Logging;

public class SemaphoreManager : IDisposable
{
    private readonly ConcurrentDictionary<string, SemaphoreSlim> _semaphores = new ConcurrentDictionary<string, SemaphoreSlim>();
    private readonly ILogger<SemaphoreManager> _logger;

    public SemaphoreManager(ILogger<SemappedorManager> logger) 
    {
        _logger = logger;
    }

    public void Acquire(string semaphoreId, int maxCount = 5000)
    {
        var semaphore = _semaphores.GetOrAdd(semaphoreId, s => new SemaphoreSlim(maxCount));

        try
        {
            semaphore.Wait();
        } 
        catch (Exception ex)
        {
            _logger.LogError(ex, $"Failed to acquire semaphore: {semaphoreId}");

            // Handle error and gracefully degrade if necessary
            throw;
        }
    }

    public void Release(string semaphoreId) 
    {
        if (_semaphores.TryGetValue(semaphoreId, out var semaphore))
        {
            try
            {
                semaphore.Release();
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, $"Failed to release semaphore: {semaphoreId}");

                // Handle error and gracefully degrade if necessary
                throw;
            }
        }
    }

    public void Dispose() 
    {
        foreach (var semaphore in _semaphores.Values)
        {
            semaphore.Dispose();
        }

        GC.SuppressFinalize(this);
    }
}
```
This is a very basic version of a system and does not include many things that are needed for production-level systems such as error handling, metrics collection, integration with external data stores, failover and recovery mechanisms, logging, etc. The code also assumes there's an external mechanism to manage scaling (such as Kubernetes or Docker Swarm), which is more complex to implement than what can be done in this simple example.
