                var updatedContent = await _updateService.UpdateElementHtmlContentAsync(sectionId, 
                    elementId, htmlContent, configuration);

                return Ok("Refresh the page to see the updates");
            }

            // If unable to acquire lock, indicate that another update is in progress.
