static pthread_mutex_t configLock = PTHREAD_MUTEX_INITIALIZER;

Config* getCurrentConfiguration() {
    static Config *currentConfig = NULL;
    pthread_mutex_lock(&configLock);

    if (currentConfig == NULL) {
