    private ConcurrentDictionary<byte[], byte[]> _cache = new ConcurrentDictionary<byte[], byte[]>();
    private readonly object _lockObject = new object();

    public async Task ProcessData(byte[] data)
    {
        var cachedResult = default(byte[]);
        if (!_cache.TryGetValue(data, out cachedResult))
        {
            lock (_lockObject)
            {
                if(!_cache.TryGetValue(data, out cachedResult)){
