Record* initialize_record(long offset, int key, time_t timestamp, const char* label, size_t id_size) {
    if (current_records >= MAX_RECORDS) {
        printf("Maximum record limit reached\n");
        return NULL;
    }

    pthread_mutex_lock(&lock); // Lock for thread safety
    Record* new_record = &records[current_records++]; // Get the current record and increment afterwards

    new_record->offset = offset;
    new_record->key = key;
    new_record->timestamp = timestamp;
