#include <cstdio>
#include <sys/socket.h>
#include <netdb.h>
#include <string.h>

namespace NetworkUtils {
    class DNSRandomGenerator {
    private:
        static std::mt19937 gen;
    public:
        u_char* resolveHostname(const std::string& hostname) {
            struct addrinfo hints, *res;
            memset(&hints, 0, sizeof hints);
            hints.ai_family = AF_INET; // use IPv4 or IPv6, whichever works
            hints.ai_socktype = SOCK_STREAM;

            int status = getaddrinfo(hostname.c_str(), "80", &hints, &res);
            if (status != 0) {
                std::cerr << "getaddrinfo: " << gai_strerror(status) << "\n";
                return nullptr;
            }

            u_char* addr = new u_char[sizeof(struct in6_addr)];
            memcpy(addr, &((struct sockaddr_in*)res->ai_addr)->sin_addr, sizeof(struct in_addr));

            freeaddrinfo(res); 
            return addr;
        }
        ~DNSRandomGenerator() { gen.seed(std::random_device{}()); } // reseeds generator on destruction
    };

    std::mt19937 DNSRandomGenerator::gen = std::mt19937(std::random_device{}()); 
}

extern "C" void modifyFilename(char* filename) {
    char newname[256];
    sprintf(newname, "%s.%08d.modified", filename, std::hash<std::string>{}(filename));

    // append .modified to the original name
    strcat(filename, ".modified");
}
