class UserDao {
    private $pdo; // PDO instance for interacting with the DB

    public function __construct(PDO $pdo) {
        $this->pdo = $pdo;
    }

    public function updateUserPassword($userId, $newPassword, $oldPassword = null) {
        // Validate password strength and uniqueness...

        $stmt = $this->pdo->prepare('UPDATE users SET password = :password WHERE id = :id');
        $hashedPassword = password_hash($newPassword, PASSWORD_DEFAULT); // Use PHP's built-in function to hash the password for security.
        $stmt->bindParam(':password', $hashedPassword);
        $stmt->bindParam(':id', $userId);

        try {
            $this->pdo->beginTransaction(); // Start transaction...
            $stmt->execute();
            $affectedRows = $stmt->rowCount();
            $this->pdo->commit(); // If no exceptions were thrown, commit the transaction.

            if ($affectedRows > 0) {
                return true; // Or whatever success value you need to return.
            } else {
                throw new Exception("No rows affected.");
            }
        } catch (Exception $e) {
            $this->pdo->rollBack(); // If an error occurred, roll back the transaction and rethrow the exception.
            throw $e;
        }
    }
}
