void* memoryManagement(int MAX_KEYS, int minVal, int maxVal) {
    const size_t align = 8; // Align to 8 bytes for efficient use of memory
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; // Lock for thread-safe operations

    srand(time(NULL)); // Seed the random number generator

    size_t offsetArraySize = 0, recordArraySize = 1024 * 1024 / sizeof(record_t); // Define maximum memory usage as 1 MB

    while (offsetArraySize + MAX_KEYS + recordArraySize > offsetArraySize) {
        // Break when we exceed the maximum memory limit after this operation
        if (MAX_KEYS + recordArraySize > 0xffffffff) { // Handle potential overflow
            return NULL; // Return an error code or appropriate response indicating failure to prevent further errors
        }

        int* keys = malloc(sizeof(*keys) * MAX_KEYS); // Allocate memory for the keys array

        if (!keys) { 
            break; // Break on allocation failure
        }

        record_t* records = calloc(recordArraySize, sizeof(*records)); // Allocate memory for the records array

        if (!records) {
            free(keys); // Free allocated keys in case of allocation failure
            break; 
        }

        pthread_mutex_lock(&lock); // Lock for thread-safe operations

        for (int i = 0; i < recordArraySize; ++i) {
            records[i].y = minVal + rand() % ((maxVal + 1) - minVal); // Set a random int value to the int field of each record
        }

        pthread_mutex_unlock(&lock); // Unlock after operation is complete
    }

    return records; // Return the pointer to first record structure in array
}
