    for(int i=0; i<number; i++) {
        tasks[i].identifier = i;
        tasks[i].status = (rand() % (maxStatus - minStatus + 1)) + minStatus; // Random status in the range [minStatus, maxStatus]
        tasks[i].data = NULL;
    }

    return tasks;
}
```
