["```python
import requests
from datetime import datetime, timedelta
import time
import threading
import json

class PaymentManager():
    def __init__(self):
        self._payments = {}  # Key: region, Value: list of transactions
        self.api_configs = {}  # Key: region, Value: API config (endpoint and keys)

    def add_transaction(self, user_id, amount, currency, api_region):
        if not self._payments.get(api_region):
            self._payments[api_region] = []

        transaction = {
            'user_id': user_id,
            'amount': amount,
            'currency': currency,
            'date': datetime.now()
        }

        self._payments[api_region].append(transaction)

    def update_configs(self, new_configs):
        for region in new_configs:
            if not self.api_configs.get(region):
                self.api_configs[region] = {}

            self.api_configs[region].update(new_configs[region])

    def process_transactions(self):
        threads = []

        for region, transactions in self._payments.items():
            thread = threading.Thread(target=self.process_transaction, args=(region, transactions))
            threads.append(thread)

        # Start all threads
        for thread in threads:
            thread.start()

    def process_transaction(self, api_region, transactions):
        endpoint = self.api_configs[api_region]['endpoint']
        key = self.api_configs[api_region]['key']

        for transaction in transactions:
            # Check if transaction is older than 7 days
            if (datetime.now() - transaction['date']).days > 7:
                continue  # Ignore this transaction and delete from logs

            headers = {'Authorization': 'Bearer {}'.format(key)}
            data = {
                'user_id': transaction['user_id'],
                'amount': transaction['amount'],
                'currency': transaction['currency']
            }

            retries = 0
            while retries < 3:  # Max 3 attempts to process the transaction
                try:
                    response = requests.post(endpoint, headers=headers, data=json.dumps(data), timeout=5)

                    if response.status_code != 200:
                        raise Exception('API call failed')

                    break  # Transaction processed successfully, move to next one
                except (requests.exceptions.RequestException, ValueError):
                    retries += 1
                    time.sleep(5)  # Wait for a while before retrying

            if retries == 3:  # Failed after max attempts
                print('Failed to process transaction for user', transaction['user_id'])

        self._payments[api_region] = []  # Clear logs after processing

    def purge_old_transactions(self):
        current_time = datetime.now()
        old_time = current_time - timedelta(days=7)

        for region, transactions in self._payments.items():
            self._payments[region] = [t for t in transactions if t['date'] > old_time]
``` 
