```c
#include <stdlib.h>
#include <string.h>
#include <assert.h>
#define INIT_CAPACITY 1024 // Initial capacity of the list
#define MAX_MEMORY 5*1024*1024 // Maximum memory usage threshold (5 MB)

typedef struct {
    double d;
    char* str;
    int i;
} item;

typedef struct {
    size_t capacity;
    size_t size;
    item** list;
} dynamicList;

dynamicList* createDynamicList() {
    dynamicList* list = malloc(sizeof(dynamicList));
    if (!list) return NULL; // out of memory

    list->capacity = INIT_CAPACITY;
    list->size = 0;
    list->list = malloc(list->capacity * sizeof(*list->list));
    if(!list->list) {
        free(list); // out of memory
        return NULL;
    }

    return list;
}

item* createItem(double d, const char* str, int i) {
    item* new_item = malloc(sizeof(item));
    if(!new_item) return NULL; // out of memory

    new_item->d = d;
    new_item->i = i;

    new_item->str = malloc((strlen(str) + 1) * sizeof(*str));
    if(!new_item->str){
        free(new_item); // out of memory
        return NULL;
    }

    strcpy(new_item->str, str);

    return new_item;
}

void destroyItem(item* item) {
    assert(item != NULL && "Null item in destroy function");

    free(item->str);
    free(item);
}

int appendToList(dynamicList* list, double d, const char* str, int i) {
    if (list->size * sizeof(*list->list) > MAX_MEMORY){
        return -1; // Memory usage limit exceeded
    }

    item* new_item = createItem(d, str, i);
    if(!new_item){
        return -2; // out of memory
    }

    list->list[list->size++] = new_item;

    if (list->size == list->capacity) {
        size_t newCapacity = 2 * list->capacity;
        item** tempList = realloc(list->list, newCapacity * sizeof(*tempList));

        // If memory allocation fails after the successful one above, we have a memory leak. 
        if(!tempList) return -3; // out of memory

        list->capacity = newCapacity;
        list->list = tempList;
    }

    return 0;
}
```

