```java
import java.io.IOException;
import java.nio.file.*;
import java.util.*;
import java.util.logging.Logger;
import java.util.stream.Collectors;

public final class FileSizeUtility {
    private static final Logger LOGGER = Logger.getLogger(FileSizeUtility.class.getName());

    public static Map<String, Long> getFilesSizes(List<Path> paths) {
        return paths.parallelStream().collect(Collectors.toMap(
            path -> path.toString(), 
            FileSizeUtility::getFileSize,
            (path1, path2) -> path2, // If duplicate key found, use the latter one
            LinkedHashMap::new   // keep insertion order and allow null keys/values
        ));
    }

    private static long getFileSize(Path path) {
        try {
            return Files.size(path);
        } catch (IOException ex) {
            LOGGER.warning("Failed to calculate size for file: " + path);
            return 0L; // Return zero if operation failed
        }
    }
}
```

Usage:

