```c
#include <stdlib.h>
#include <pthread.h>
#define MAX_TASKS 100000
#define MAX_CATEGORIES 256

typedef struct {
    char *name;
    int priority;
    time_t dueDate;
    char *status;
} Task;

typedef struct Node{
    Task* task;
    struct Node *next;
}Node;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
Task *taskArray[MAX_TASKS];
char *categoryArray[MAX_CATEGORIES];
Node* head = NULL;
size_t tasksCount = 0, categoriesCount = 0;

void insert(Task* task){
    Node* newNode = malloc(sizeof(Node));
    pthread_mutex_lock(&lock);
    if (newNode == NULL) { 
        // Handle Error. Retry allocation or fallback.
        return;
    }
    tasksCount++;
    pthread_mutex_unlock(&lock);

    newNode->task = task;
    newNode->next = head;
    head = newNode;
}

void delete(Task* task){
    Node *temp = head, *prev = NULL;
    pthread_mutex_lock(&lock);

    if (temp != NULL && temp->task == task) { 
        head = temp->next;  
        free(temp->task->name);
        free(temp->task->status);
        free(temp->task);
        free(temp); 
        tasksCount--;
        pthread_mutex_unlock(&lock);
        return;
    } 

    while (temp != NULL && temp->task != task) { 
        prev = temp; 
        temp = temp->next; 
    }  
    if (temp == NULL){
        pthread_mutex_unlock(&lock);
        return; // Task not found.
    } 

    prev->next = temp->next; 
    free(temp->task->name);
    free(temp->task->status);
    free(temp->task);
    free(temp);
    tasksCount--;
    pthread_mutex_unlock(&lock);
}

void update(Task* old, Task* new){
    Node *node = head;

    while (node != NULL) { 
        if(node->task == old){
            free(old->name);
            free(old->status);
            node->task = new;
            return; // Task updated.
        } 
        node = node->next; 
    }
}
```

