    Metric* metric = malloc(sizeof(Metric));
    metric->values = calloc(initial_capacity, sizeof(double));
    metric->capacity = initial_capacity;
    metric->count = 0;
    pthread_mutex_init(&metric->lock, NULL);
    return metric;
}

void add_value(Metric* metric, double value) {
    pthread_mutex_lock(&metric->lock);

    if (metric->count == metric->capacity) {
        metric->values = realloc(metric->values, sizeof(double) * metric->capacity * 2);
        metric->capacity *= 2;
    }

    metric->values[metric->count++] = value;

    pthread_mutex_unlock(&metric->lock);
}

double get_value(Metric* metric, size_t index) {
    double value = 0.0;

    pthread_mutex_lock(&metric->lock);

    if (index < metric->count) {
        value = metric->values[index];
    }

    pthread_mutex_unlock(&metric->lock);

    return value;
}

double calculate_mean(Metric* metric) {
    double sum = 0.0;

    pthread_mutex_lock(&metric->lock);

    for (size_t i = 0; i < metric->count; ++i) {
        sum += metric->values[i];
    }

    pthread_mutex_unlock(&metric->lock);

    return sum / metric->count;
}

double calculate_median(Metric* metric) {
    double median = 0.0;

    pthread_mutex_lock(&metric->lock);

    qsort(metric->values, metric->count, sizeof(double), compare);

    if (metric->count % 2 == 0) {
        median = (metric->values[metric->count / 2 - 1] + metric->values[metric->count / 2]) / 2;
    } else {
        median = metric->values[metric->count / 2];
    }

    pthread_mutex_unlock(&metric->lock);

    return median;
}

double calculate_stddev(Metric* metric) {
    double mean = calculate_mean(metric);
    double sum = 0.0;

    pthread_mutex_lock(&metric->lock);

    for (size_t i = 0; i < metric->count; ++i) {
        sum += pow(metric->values[i] - mean, 2);
    }

    pthread_mutex_unlock(&metric->lock);

    return sqrt(sum / metric->count);
}

int compare(const void* a, const void* b) {
    double fa = *(double*)a;
    double fb = *(double*)b;
    return (fa > fb) - (fa < fb);
}
```
This is an oversimplification and in practice you would also need to handle errors, add configuration options, log metrics data etc. For real-world applications, consider using existing high-performance libraries or frameworks which have been tested for performance, reliability, and scalability.
