typedef struct node {
    record_t* data;
    struct node *next, *prev;
} node_t;

void insert(node_t** head_ref, record_t* new_record) {
    // allocate new node and set its data
    node_t* new_node = (node_t*)malloc(sizeof(node_t)); 
    assert(new_node != NULL);
    new_node->data = new_record;

    if (*head_ref == NULL) {  // if list is empty, point to itself
        new_node->next = new_node->prev = new_node;
    } else {
        node_t* last = (*head_ref)->prev;
        new_node->next = *head_ref;  // insert at the end of list
        (*head_ref)->prev = new_node;
        new_node->prev = last;
        last->next = new_node;
    }

    *head_ref = new_node;  // set head to newly inserted node
}

// function that creates and initializes records, linked list and balanced tree
