```c
#include <stdio.h>
#include <stdlib.h>

// Node structure for the circular linked list
typedef struct node {
    int data;
    struct node* next;
} Node;

// Structure for the binary search tree
typedef struct bstNode {
    int key;
    struct bstNode *left, *right;
} BSTNode;

// Function to create a new BST node
BSTNode* newBSTNode(int item) {
    BSTNode* temp = (BSTNode*)malloc(sizeof(BSTNode));
    temp->key = item;
    temp->left = temp->right = NULL;
    return temp;
}

// Function to perform an inorder traversal of the BST
void inorder(BSTNode* root) {
    if (root != NULL) {
        inorder(root->left);
        printf("%d ", root->key);
        inorder(root->right);
    }
}

// Function to insert a new node with given key in BST 
BSTNode* insert(BSTNode* node, int key) {
    if (node == NULL) return newBSTNode(key);

    if (key < node->key)
        node->left = insert(node->left, key);
    else if (key > node->key)
        node->right = insert(node->right, key); 

    return node;
}

// Function to add a new node at the end of the circular linked list
Node* append(Node** head_ref, int new_data) {
    Node* new_node = (Node*) malloc(sizeof(Node));
    Node* last = *head_ref;

    new_node->data  = new_data;
    new_node->next = *head_ref; 

    if (*head_ref != NULL) {
        while (last->next != *head_ref)
            last = last->next;

        last->next = new_node;
    } else
        new_node->next = new_node; 

    *head_ref = new_node;

    return new_node;
}

int main() {
    Node* head = NULL;
    BSTNode* root = NULL;

    append(&head, 1);
    append(&head, 2);
    append(&head, 3);

    root = insert(root, 1);
    insert(root, 2);
    insert(root, 3);

    printf("Circular Linked List: ");
    Node* temp = head;
    do {
        printf("%d ",temp->data);
        temp = temp->next;
    } while (temp != head);

    printf("\nBinary Search Tree inorder traversal: ");
    inorder(root);

    return 0;
}
```
