['```C
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct entry {
    unsigned long timestamp;
    char *message;
} Entry;

typedef struct collection {
    pthread_mutex_t lock;
    size_t count;
    size_t capacity;
    Entry **entries;
} Collection;

Collection *new_collection() {
    Collection *c = malloc(sizeof(Collection));
    if (c == NULL) {
        fprintf(stderr, "Failed to allocate memory for collection\n");
        exit(EXIT_FAILURE);
    }

    c->lock = PTHREAD_MUTEX_INITIALIZER;
    c->count = 0;
    c->capacity = 10000;
    c->entries = malloc(c->capacity * sizeof(Entry*));

    if (c->entries == NULL) {
        fprintf(stderr, "Failed to allocate memory for entries\n");
        free(c);
        exit(EXIT_FAILURE);
    }

    return c;
}

void add_entry(Collection *c, char *message) {
    pthread_mutex_lock(&c->lock);

    if (c->count >= c->capacity) {
        fprintf(stderr, "Collection is full\n");
        pthread_mutex_unlock(&c->lock);
        return;
    }

    Entry *e = malloc(sizeof(Entry));
    if (e == NULL) {
        fprintf(stderr, "Failed to allocate memory for entry\n");
        pthread_mutex_unlock(&c->lock);
        return;
    }

    e->timestamp = time(NULL);
    e->message = strdup(message);

    if (e->message == NULL) {
        fprintf(stderr, "Failed to allocate memory for message\n");
        free(e);
        pthread_mutex_unlock(&c->lock);
        return;
    }

    c->entries[c->count++] = e;

    pthread_mutex_unlock(&c->lock);
}

Entry *get_entry(Collection *c, size_t index) {
    if (index >= c->count) {
        fprintf(stderr, "Index out of range\n");
        return NULL;
    }

    pthread_mutex_lock(&c->lock);
    Entry *e = c->entries[index];
    pthread_mutex_unlock(&c->lock);

    return e;
}

void free_collection(Collection *c) {
    for (size_t i = 0; i < c->count; ++i) {
        Entry *e = c->entries[i];
        free(e->message);
        free(e);
    }

    pthread_mutex_destroy(&c->lock);
    free(c->entries);
    free(c);
}
```

This code creates a dynamic collection of entries. It uses mutex locks to ensure thread safety, and gracefully handles allocation failures by printing error messages and exiting the program. It's important to note that this code doesn't use a linked list for its implementation, but an array-based approach which is more efficient for lookups. However, insertions and deletions would require shifting elements in the array, leading to O(n) time complexity. If frequent insertions and deletions are expected, a linked list might be a better choice.
']

