void manage_memory(int* keys, long* offsets, size_t size) {
    static record* records = NULL;
    static size_t allocated_size = 0;

    // Validate the sizes of the arrays
    if (sizeof(keys)/sizeof(*keys) < sizeof(offsets)/sizeof(*offsets)) {
        printf("Error: Size of keys array is less than size of offsets array.\n");
        return;
    }

    // Dynamically allocate memory for new records if necessary
    if (allocated_size < size) {
        record* new_records = realloc(records, sizeof(*new_records) * size);
        if (!new_records) {
            printf("Error: Failed to allocate memory.\n");
            return;
        }

        // Zero the newly allocated memory
        memset(&new_records[allocated_size], 0, sizeof(*new_records) * (size - allocated_size));

        records = new_records;
        total_allocated += size - allocated_size;
        allocated_size = size;
    }

    // Initialize the record values
    for (size_t i = 0; i < size; ++i) {
        records[i].value = rand();  // Initialize value with random number, adjust as needed.
        records[i].key = &keys[i];
        records[i].offset = offsets[i];
    }

    printf("Total allocated memory: %ld bytes\n", total_allocated);
}
```
This function manages the memory for multiple instances of `record` structures. It validates that the size of the `keys` array is never less than the size of the `offsets` array and dynamically allocates memory as needed. The function also initializes each record with a random number, adjusting it according to your requirements.

