static Window window = {PTHREAD_MUTEX_INITIALIZER, 10 * 1000, NULL};  // sliding window in milliseconds

void processPacket(Window *window, Packet *packet) {
    pthread_mutex_lock(&window->lock);

    if (window->packets == NULL || packet->delay - window->packets->delay > window->period) {
        // if it's the first packet or its delay is too high, pop one out from the list.
        Packet *temp = window->packets;
        window->packets = temp->next;
        free(temp);
    }

    // Add new packet into the list.
    packet->next = window->packets;
    window->packets = packet;

    pthread_mutex_unlock(&window->lock);
}

Metrics getMetrics() {
    Metrics m = metrics;  // make a copy for thread safety.
    return m;
}

int configure(char *config) {
    /* parse config and set thresholds, criteria... */
    return 0;  // success
}
