```C
#include <stdlib.h>
#include <pthread.h>

typedef struct data_record {
    int value;
    float weight;
    int *key;
    size_t refcount;
    pthread_mutex_t lock; // for concurrent access
} data_record;

data_record* new_record(int v, float w, int *k) {
    data_record *rec = malloc(sizeof(data_record));
    if (rec == NULL) exit(EXIT_FAILURE);  // handle memory allocation failure
    rec->value = v;
    rec->weight = w;
    rec->key = k;
    rec->refcount = 1;
    pthread_mutex_init(&rec->lock, NULL);
    return rec;
}

void record_retain(data_record *r) {
    pthread_mutex_lock(&r->lock);  // lock for concurrent access
    r->refcount++;
    pthread_mutex_unlock(&r->lock);
}

void record_release(data_record *r) {
    pthread_mutex_lock(&r->lock);  // lock for concurrent access
    if (--r->refcount == 0) free(r);  // free the record when no longer in use
    else if (r->refcount < 0) exit(EXIT_FAILURE);  // handle ref count underflow
    pthread_mutex_unlock(&r->lock);
}
```

