['Here's a C implementation of your request. The first function creates an array of records with random int values, each pointing to corresponding key in keys array. It then builds a circular linked list from these records. The second function takes Base64 encoded message and decrypt it using AES encryption with given key and IV.

```c
#include <openssl/aes.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <assert.h>

typedef struct Record {
    int value;
    long* key_ptr;
} Record;

Record* createRecords(long* keys, size_t len) {
    srand((unsigned int) time(NULL));

    Record* records = malloc(sizeof(Record)*len);
    assert(records != NULL);

    for (int i = 0; i < len; ++i) {
        records[i].value = rand();  // Change the range as needed.
        records[i].key_ptr = &keys[i];
    }

    return records;
}

Record* createCircularLinkedList(Record* records, size_t len) {
    if (len <= 1) {
        return records;
    }

    for (int i = 0; i < len - 1; ++i) {
        records[i].key_ptr = &records[i+1].value;
    }
    records[len-1].key_ptr = &records[0].value;  // Last node points to first.

    return records;
}

char* decryptAES(const char* message, const unsigned char* key) {
    AES_KEY aesKey;
    if (AES_set_decrypt_key(key, 128, &aesKey) < 0) {
        fprintf(stderr, "Failed to set decryption key for AES\n");
        return NULL;
    }

    unsigned char* plainText = malloc(strlen(message));
    assert(plainText != NULL);

    // Assuming 'message' is already Base64 encoded. Decode it first before decrypting here.
    AES_decrypt((unsigned char*) message, plainText, &aesKey);

    return (char*) plainText;
}
```
Please note that this code assumes you have OpenSSL installed and properly linked in your project. You'll need to handle base64 decoding separately since openssl AES functions do not support it.

The `createRecords` function creates an array of Record structs, each containing a random int value and a pointer to its corresponding key from the keys array. 

The `createCircularLinkedList` function takes these records and creates a circular linked list out of them by making the 'key_ptr' field of each record point to the 'value' field of the next record in the list, with the last node pointing back to the first.

The `decryptAES` function decodes a base64 encoded message using openssl AES functions and returns the plaintext as a string.
