```c
#include <stdlib.h>
#include <pthread.h>

typedef struct Record {
    int value;
    long offset;
} Record;

typedef struct Node {
    int key;
    struct Record* record;
    struct Node *next, *prev;
} Node;

typedef struct List {
    Node *head;
    int size;
    pthread_mutex_t lock;
} List;

// Initialize the list with a single node.
List* init_list() {
    List *l = malloc(sizeof(List));
    l->head = NULL;
    l->size = 0;
    pthread_mutex_init(&l->lock, NULL);
    return l;
}

// Add a new node to the list.
void add_node(List *list, int key) {
    Node *newNode = malloc(sizeof(Node));
    newNode->key = key;
    pthread_mutex_lock(&list->lock);
    if (list->head == NULL) {
        list->head = newNode;
        newNode->next = newNode;
        newNode->prev = newNode;
    } else {
        newNode->next = list->head;
        newNode->prev = list->head->prev;
        list->head->prev->next = newNode;
        list->head->prev = newNode;
    }
    pthread_mutex_unlock(&list->lock);
}

// Remove a node from the list.
void remove_node(List *list, Node *n) {
    if (n == NULL || list == NULL) return;
    pthread_mutex_lock(&list->lock);
    n->prev->next = n->next;
    n->next->prev = n->prev;
    if(list->head == n) list->head = n->next;
    free(n);
    pthread_mutex_unlock(&list->lock);
}

// Clean up the list.
void cleanup_list(List *l) {
    while (l->size > 0) {
        remove_node(l, l->head);
    }
    pthread_mutex_destroy(&l->lock);
    free(l);
}
```
