#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdarg.h>

// Define LogEntry struct for storing log messages
typedef struct {
    char* message;
    // Add other fields as necessary (e.g., timestamp, thread ID)
} LogEntry;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
static LogEntry** logEntries;
static size_t numLogEntries = 0;
static size_t capacity = 16;  // Initial capacity of the array

void addLog(const char* format, ...) {
    pthread_mutex_lock(&lock);

    if (numLogEntries == capacity) {
        capacity *= 2;
        logEntries = realloc(logEntries, sizeof(*logEntries) * capacity);

        if (!logEntries) {
            perror("Failed to allocate memory for log entries");
            pthread_mutex_unlock(&lock);
            return;
        }
    }

    va_list args;
    va_start(args, format);
    size_t len = vsnprintf(NULL, 0, format, args) + 1; // Include space for '\0'
    va_end(args);

    char* message = malloc(len);
    if (!message) {
        perror("Failed to allocate memory for log message");
        pthread_mutex_unlock(&lock);
        return;
    }

    va_start(args, format);
    vsnprintf(message, len, format, args);
    va_end(args);

    LogEntry* newLog = malloc(sizeof(*newLog));
    if (!newLog) {
        perror("Failed to allocate memory for log entry");
        free(message);
        pthread_mutex_unlock(&lock);
        return;
    }

    newLog->message = message;
    // Set other fields of the LogEntry as necessary (e.g., timestamp, thread ID)

    logEntries[numLogEntries++] = newLog;

    pthread_mutex_unlock(&lock);
}
```
In this code block, we have created a dynamic array to store `LogEntry` structures (which contain the formatted message and additional metadata). When adding a log entry, we first acquire a lock to ensure thread safety. If the array is full, we double its capacity using `realloc`. Then we format the message string, allocate memory for it, create a new `LogEntry` structure, add it to the array, and finally unlock the mutex.

