void serializeListToFile(FILE* file, Node* head) {
    for (Node* current = head; current != NULL; current = current->next) {
        fwrite(&current->data->value, sizeof(int), 1, file);
        size_t length = strlen(current->data->substring);
        fwrite(&length, sizeof(size_t), 1, file);
        fwrite(current->data->substring, sizeof(char), length, file);
    }
}
```
6. Deserialization:
```C
Node* deserializeListFromFile(FILE* file) {
    Node dummy = {NULL, NULL};
    Node* tail = &dummy;

    while (!feof(file)) {
        Record* record = (Record*)malloc(sizeof(Record));
        if (fread(&record->value, sizeof(int), 1, file) == 0) break;

        size_t length = 0;
        fread(&length, sizeof(size_t), 1, file);

        record->substring = (char*)malloc((length + 1) * sizeof(char));
        fread(record->substring, sizeof(char), length, file);
        record->substring[length] = '\0';

        Node* node = (Node*)malloc(sizeof(Node));
        node->data = record;
        node->next = NULL;

        tail->next = node;
        tail = node;
    }

    return dummy.next;
}
```
