["Here is a C implementation using a doubly linked list to manage sensor data processing. This program uses a random temperature generator within a specified range, and stores identifiers in an array. It also checks if memory allocation was successful before performing other operations. 

```c
#include <stdlib.h>
#include <time.h>
#include <string.h>

typedef struct Sensor {
    double temperature;
    char* identifier;
    struct Sensor* next;
    struct Sensor* prev;
} Sensor;

Sensor* create_sensor(double min, double max) {
    Sensor* newNode = (Sensor*)malloc(sizeof(Sensor));

    if(newNode == NULL) {
        exit(-1); // Allocation error
    }

    srand((unsigned int)time(NULL));
    double randomTemp = min + ((double)rand() / RAND_MAX) * (max - min);

    newNode->temperature = randomTemp;
    newNode->identifier = NULL; // Initialize to NULL, update as necessary.
    newNode->next = NULL;
    newNode->prev = NULL;

    return newNode;
}

void add_sensor(Sensor** head, Sensor* node) {
    if(*head == NULL) { // If list is empty, make the head the node.
        *head = node;
    } else { 
        Sensor* temp = *head;

        while(temp->next != NULL){
            temp = temp->next;  // Go To last Node.
        }
        temp->next = node;
        node->prev = temp;
    }
}

Sensor* create_sensor_list(int num, double min, double max) {
    Sensor* head = NULL;

    for(int i = 0; i < num; ++i){
      Sensor* newNode = create_sensor(min, max); 
      add_sensor(&head, newNode);
   }
    return head;
}
```

This code can be easily modified or extended as per the need for different temperature ranges or identifier lengths. The function also handles potential latency and incomplete data from external data sources by not directly interfacing with them but rather providing an interface to receive, validate and process this data. 

