// Function to handle reallocation of arrays
void *resizeArrays(void *oldPtr, size_t oldSize, size_t newSize) {
    void *newPtr = realloc(oldPtr, newSize);
    if (newPtr == NULL && newSize != 0) {
        free(oldPtr);
        return NULL;
    }

    return newPtr;
}

// Function to handle integer overflow
int safeAddInt(atomic_int* a, int b) {
    while(1){
        int current = atomic_load(a);
        if(b > 0 && INT_MAX - b < current) {
            printf("Integer overflow detected!\n");
            return 0;
        } else if (b < 0 && INT_MIN - b > current) {
            printf("Integer underflow detected!\n");
            return 0;
        }
        int old = atomic_compare_exchange_strong(a, &current, current+b);
        if(old == current) break;
    }
    return 1;
}

// Function to handle adding a record
void addRecord(int* key, long offset, char flag) {
    pthread_mutex_lock(&resizeLock);
    // If we need to resize the arrays...
    if (recordsSize == recordsCapacity) {
        size_t newRecordsCapacity = recordsCapacity == 0 ? 1 : recordsCapacity * 2;
        Record* newRecords = resizeArrays(records, sizeof(*newRecords) * recordsCapacity, sizeof(*newRecords) * newRecordsCapacity);

        if (newRecords == NULL) {
            pthread_mutex_unlock(&resizeLock);
            return;
        }

        records = newRecords;
        recordsCapacity = newRecordsCapacity;
    }

    // Add the record...
    Record* record = &records[recordsSize++];
    atomic_init(&record->intPointer, key);
    record->offset = offset;
    record->flag = flag;

    pthread_mutex_unlock(&resizeLock);
}
