// Define a struct for profiles
typedef struct Profile {
    char* name;
    unsigned int age;
    char** interests;
} Profile;

// Define a node structure for linked list
typedef struct Node {
    Profile profile;
    struct Node *prev;
    struct Node *next;
} Node;

// Initialize head and tail of the list
Node* head = NULL;
Node* tail = NULL;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

Profile* createProfile(char* name, unsigned int age, char** interests) {
    Profile *profile = (Profile*) malloc(sizeof(Profile));
    profile->name = strdup(name);
    profile->age = age;
    profile->interests = interests; // You need to implement copying the array here.
    return profile;
}

void addProfile(char* name, unsigned int age, char** interests) {
    Profile *profile = createProfile(name, age, interests);

    pthread_mutex_lock(&lock);
    Node *node = (Node*) malloc(sizeof(Node));
    node->profile = *profile;
    node->prev = NULL;
    if (head == NULL) {
        head = tail = node;
    } else {
        node->next = head;
        head->prev = node;
        head = node;
    }
    pthread_mutex_unlock(&lock);
}

void removeProfile(char* name) {
    Node *currentNode, *previousNode;
    currentNode = head;

    pthread_mutex_lock(&lock);
    while (currentNode != NULL && strcmp(name, currentNode->profile.name) != 0) {
        previousNode = currentNode;
        currentNode = currentNode->next;
    }

    if (currentNode == head) { // If the node to be deleted is head node 
        head = head->next;
    } else if(currentNode == tail){//change tail  
        tail = tail -> prev;  
    } else{  
        previousNode -> next = currentNode -> next; //here we are changing the next of previous node to skip current one.  
        currentNode->next->prev = previousNode;
    } 

    free(currentNode);
    pthread_mutex_unlock(&lock);
}

void updateProfile(char* name, unsigned int age, char** interests) {
    Node *currentNode;
    currentNode = head;

    pthread_mutex_lock(&lock);
    while (currentNode != NULL && strcmp(name, currentNode->profile.name) != 0) {
        currentNode = currentNode->next;
    }

    if(currentNode != NULL){
        free(currentNode->profile.name);
        free(currentNode->profile.interests);
        Profile *newProfile = createProfile(name, age, interests);
        currentNode->profile = *newProfile;
    }

    pthread_mutex_unlock(&lock);
}
```
