#define MAX_CONNECTIONS 1000

typedef struct {
    char IP[20];
    int port;
    char state[15];
    time_t lastActiveTimestamp;
} ConnectionRecord;

ConnectionRecord connections[MAX_CONNECTIONS];
int connectionCount = 0;

void addConnection(char *IP, int port, char *state) {
    if (connectionCount < MAX_CONNECTIONS) {
        strcpy(connections[connectionCount].IP, IP);
        connections[connectionCount].port = port;
        strcpy(connections[connectionCount].state, state);
        connections[connectionCount].lastActiveTimestamp = time(NULL);
        connectionCount++;
    } else {
        printf("Maximum limit reached\n");
    }
}

void deleteConnection(char *IP) {
    for (int i = 0; i < connectionCount; ++i) {
        if (strcmp(connections[i].IP, IP) == 0) {
            connections[i] = connections[connectionCount - 1];
            connectionCount--;
            return;
        }
    }
    printf("Connection not found\n");
}

void queryConnections() {
    for (int i = 0; i < connectionCount; ++i) {
        printf("%s:%d, %s, %ld\n", connections[i].IP, connections[i].port, connections[i].state, connections[i].lastActiveTimestamp);
    }
}

int main(void) {
    while (1) {
        char input[50];
        printf("Enter command: ");
        scanf("%s", input);

        if (strcmp(input, "add") == 0) {
            char IP[20];
            int port;
            char state[15];
            printf("Enter IP: ");
            scanf("%s", IP);
            printf("Enter port: ");
