            addConnection(IP, port, state);
        } else if (strcmp(input, "delete") == 0) {
            char IP[20];
            printf("Enter IP: ");
            scanf("%s", IP);
            deleteConnection(IP);
        } else if (strcmp(input, "query") == 0) {
            queryConnections();
        } else if (strcmp(input, "exit") == 0) {
            break;
        } else {
            printf("Invalid command\n");
        }
    }

    return 0;
}
```
