2. Custom memory pool allocator can be implemented using a linked list, each node representing an available block of memory:
```c
typedef struct MemoryBlock {
    void *mem_ptr;
    bool is_free;
    struct MemoryBlock* next;
} MemoryBlock;

// Function to initialize the pool and allocate space for records
void initMemoryPool(size_t size, int recordSize) {
    // Initialize head of linked list representing memory pool
    head = malloc(sizeof(MemoryBlock));
    current = head;

    // Allocate requested size for each block
    for (int i = 0; i < size / recordSize; ++i) {
        MemoryBlock* new_block = malloc(sizeof(MemoryBlock));
        new_block->mem_ptr = malloc(recordSize);
        new_block->is_free = true;
        current->next = new_block;
        current = new_block;
    }
}
```
3. The actual allocation can then be done by searching for a free block, and marking it as used:
```c
void* allocateMemory() {
    MemoryBlock* curr = head->next;
    while(curr != NULL) {
        if (curr->is_free){
            curr->is_free = false;
            return curr->mem_ptr;
        }
        curr = curr->next;
    }
}
```
4. Freeing memory involves simply marking a block as free:
```c
void deallocateMemory(void* ptr) {
    MemoryBlock* curr = head->next;
    while(curr != NULL) {
        if (curr->mem_ptr == ptr){
            curr->is_free = true;
            return;
        }
        curr = curr->next;
    }
}
```
