typedef struct {
    long* offsets;
    int* keys;
    Record* records;
    size_t array_size;
    pthread_mutex_t lock;
} MemoryContext;

void free_context(MemoryContext *ctx) {
    if (ctx == NULL) return;
    if (ctx->offsets != NULL) free(ctx->offsets);
    if (ctx->keys != NULL) free(ctx->keys);
    if (ctx->records != NULL) {
        for (size_t i = 0; i < ctx->array_size; ++i) {
            Record* record = &ctx->records[i];
            free(record);
        }
        free(ctx->records);
    }
    pthread_mutex_destroy(&ctx->lock);
}

MemoryContext init_context(size_t array_size, int min_value, int max_value) {
    srand((unsigned int) time(NULL));

    MemoryContext ctx;
    ctx.array_size = array_size;
    pthread_mutex_init(&ctx.lock, NULL);

    ctx.offsets = (long*) calloc(array_size, sizeof(long));
    if (ctx.offsets == NULL) goto error;

    ctx.keys = (int*) malloc(array_size * sizeof(int));
    if (ctx.keys == NULL) goto error;

    for (size_t i = 0; i < array_size; ++i) {
        ctx.offsets[i] = (long) i * rand();

