    Offset* offset_ptr;
    int record_int;
} Record;

typedef struct DataStructures {
    Offset* offsets;
    Key* keys;
    Record* records;
} DataStructures;

DataStructures* allocate_initialize(size_t size) {
    srand(time(NULL)); // initialize random number generator

    // Allocate and initialize all structures in one call to malloc.
    void* memory = malloc((3 * sizeof(Offset*) + size * (sizeof(Offset) + sizeof(Key) + sizeof(Record))) );
    if (!memory) {
        return NULL; // error, out of memory
    }

    DataStructures* data_structures = (DataStructures*) memory;
    memory += sizeof(DataStructures); 
    data_structures->offsets = (Offset*) memory;
    memory += size * sizeof(Offset);
    data_structures->keys = (Key*) memory;
    memory += size * sizeof(Key);
    data_structures->records = (Record*) memory;

    // Initialize structures
    for (size_t i = 0; i < size; ++i) {
        data_structures->offsets[i].value = 0;
        data_structures->keys[i].key_value = i;

        int record_int;
        do {
            record_int = rand(); // generate random number
        } while (record_int < 0 || record_int > size - 1); // ensure uniqueness within specified range
        data_structures->records[i].offset_ptr = &data_structures->offsets[i];
        data_structures->records[i].record_int = record_int;
    }

    return data_structures;
}

void free_memory(DataStructures* data_structures) {
