```c
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <assert.h>

typedef struct {
    char *name;
    char *contact_info;
    int duration_days;
    int reference_count;
} Project;

typedef struct {
    time_t due_date;
    Project *project;
} Milestone;

Milestone* milestones = NULL;
Project* projects = NULL;
int num_milestones = 0;
int num_projects = 0;

void add_project(const char *name, const char *contact_info, int duration) {
    Project *p = malloc(sizeof(Project));
    assert(p != NULL);

    p->name = strdup(name);
    assert(p->name != NULL);

    p->contact_info = strdup(contact_info);
    assert(p->contact_info != NULL);

    p->duration_days = duration;
    p->reference_count = 0;

    projects = realloc(projects, sizeof(Project) * (num_projects + 1));
    assert(projects != NULL);
    projects[num_projects] = p;
    num_projects++;
}

void remove_project(int index) {
    assert(index >= 0 && index < num_projects);

    // Update reference counts of milestones referencing the project to be removed
    for (int i = 0; i < num_milestones; ++i) {
        if (milestones[i].project == projects[index]) {
            --(milestones[i].project->reference_count);
        }
    }

    free(projects[index]->name);
    free(projects[index]->contact_info);
    free(projects[index]);

    // Shift projects after the removed one to fill the gap
    for (int i = index; i < num_projects - 1; ++i) {
        projects[i] = projects[i + 1];
    }

    --num_projects;
}

void add_milestone(int project_index, time_t due_date) {
    Milestone *m = malloc(sizeof(Milestone));
    assert(m != NULL);

    m->due_date = due_date;
    m->project = projects[project_index];
    ++(m->project->reference_count);  // Increase reference count of the project

    milestones = realloc(milestones, sizeof(Milestone) * (num_milestones + 1));
    assert(milestones != NULL);
    milestones[num_milestones] = m;
    ++num_milestones;
}

void remove_milestone(int index) {
    assert(index >= 0 && index < num_milestones);

    --(milestones[index].project->reference_count);  // Decrease reference count of the project
    free(milestones[index]);

    for (int i = index; i < num_milestones - 1; ++i) {
        milestones[i] = milestones[i + 1];
    }

    --num_milestones;
}
```
