['```c
#include <stdlib.h>
#include <stdio.h>
#define MAX_SIZE 1024

typedef struct Record {
    int key;
    long offset;
} Record;

typedef struct Collection {
    Record *records[MAX_SIZE];
    size_t count;
    size_t maxSize;
    long defaultOffset;
} Collection;

void initialize(Collection *collection, size_t maxSize, long defaultOffset) {
    collection->count = 0;
    collection->maxSize = (maxSize > MAX_SIZE)?MAX_SIZE:maxSize;
    collection->defaultOffset = defaultOffset;
}

int addRecord(Collection *collection, int key, long offset) {
    if (collection->count >= collection->maxSize) {
        fprintf(stderr, "Error: Maximum capacity reached. Record not added.\n");
        return -1;
    } 
    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->records[i]->key == key) {
            printf("Warning: Duplicate key detected. Updating offset.\n");
            collection->records[i]->offset = offset;
            return 1;
        }
    }
    Record *newRecord = (Record *) malloc(sizeof(Record));
    if (!newRecord) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return -2;
    }
    newRecord->key = key;
    newRecord->offset = offset;
    collection->records[collection->count++] = newRecord;
    printf("Info: Record added successfully.\n");
    return 0;
}

void incrementOffsets(Collection *collection, int factor) {
    for (size_t i = 0; i < collection->count; ++i) {
        collection->records[i]->offset += factor;
    }
    printf("Info: Offsets updated successfully.\n");
}

void destroy(Collection *collection) {
    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->records[i]);
    }
    collection->count = 0;
    printf("Info: Collection destroyed successfully.\n");
}
``` 
This code implements a simple dynamic array as the underlying data structure to store records. Each record is allocated memory when it is added and deallocated when the collection is destroyed. This should minimize unnecessary overhead due to frequent memory allocations and deallocations. The function `addRecord` checks for capacity before adding a new record, detects duplicates by key, and updates offset if necessary. It also provides informational messages via printf calls.
']

