    public void processFileInParallel(String filename) {
        Path path = Paths.get(filename);
        try (SeekableByteChannel channel = Files.newByteChannel(path, StandardOpenOption.READ)) {
            long fileSize = channel.size();
            for (long position = 0; position < fileSize; position += CHUNK_SIZE) {
                long endPosition = Math.min(position + CHUNK_SIZE, fileSize);
                executor.submit(() -> processChunk(channel, position, endPosition));
            }
