["Here is a basic implementation for your problem:

```C
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct entry {
    long timestamp;
    char* key;
} Entry;

typedef struct node {
    Entry* data;
    struct node* next;
} Node;

Node* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
time_t expirationThreshold = 1800; // 30 minutes default

void addEntry(long timestamp, char* key) {
    if (timestamp < 0 || !key) {
        return;
    }
    pthread_mutex_lock(&lock);

    Node* newNode = malloc(sizeof(Node));
    if (!newNode) {
        // Handle memory allocation failure.
        goto cleanup;
    }

    Entry* newEntry = malloc(sizeof(Entry));
    if (!newEntry) {
        free(newNode);
        goto cleanup;
    }

    newEntry->timestamp = timestamp;
    newEntry->key = strdup(key);
    if (!newEntry->key) {
        free(newEntry);
        free(newNode);
        goto cleanup;
    }

    newNode->data = newEntry;
    newNode->next = head;
    head = newNode;

cleanup:
    pthread_mutex_unlock(&lock);
}

char* getKey(long timestamp) {
    if (timestamp < 0) {
        return NULL;
    }
    pthread_mutex_lock(&lock);

    for (Node* current = head; current != NULL; current = current->next) {
        if (current->data->timestamp == timestamp) {
            char* key = strdup(current->data->key);
            pthread_mutex_unlock(&lock);
            return key;
        }
    }

    pthread_mutex_unlock(&lock);
    return NULL;
}

void cleanEntries() {
    time_t now = time(NULL);
    pthread_mutex_lock(&lock);

    while (head && head->data->timestamp + expirationThreshold < now) {
        Node* oldHead = head;
        head = head->next;

        free(oldHead->data->key);
        free(oldHead->data);
        free(oldHead);
    }

    pthread_mutex_unlock(&lock);
}

void setExpirationThreshold(time_t newThreshold) {
    expirationThreshold = newThreshold;
}
```
This code provides a simple implementation for the problem. It uses linked lists to store entries, and mutex locks to ensure thread safety. The addEntry function handles memory allocation failures by skipping subsequent steps if any step fails, and then cleaning up before moving on.

The getKey function searches through the list until it finds an entry with a matching timestamp or runs out of nodes. If none are found, NULL is returned.

Finally, the cleanEntries function removes entries that have expired based on the configured expirationThreshold, and sets a new threshold using setExpirationThreshold.

This code doesn't integrate with an external logging service, so it won't be suitable for a production environment where audit trails are necessary. It also assumes all strings passed to addEntry are valid and don't need to be validated.

Please note that this is a rudimentary solution and lacks many necessary features for a complete system (like error handling, configuration options). For such a complex system, you might want to consider using an existing library or framework instead of writing your own memory management and concurrency code from scratch.
