```c
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <assert.h>

typedef struct Entry {
    long timestamp;
    char* key; // Use a flexible array member for variable-length string key
} Entry;

// A simple locking mechanism using pthread_mutex
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; 

Entry** entries; // Array of Entry pointers
size_t capacity = 0; // Current array size

void insert(long timestamp, const char* key) {
    pthread_mutex_lock(&lock);

    if (entries == NULL || capacity == 0) {
        entries = malloc(1 * sizeof(Entry));
        capacity = 1;
    } else if (capacity <= timestamp) {
        // Increase the array size when necessary
        Entry** new_entries = realloc(entries, (timestamp + 1) * sizeof(Entry*));
        assert(new_entries != NULL); // Asserting the memory allocation success for simplicity

        entries = new_entries;
        capacity = timestamp + 1;
    }

    Entry* entry = malloc(sizeof(Entry) + strlen(key) + 1); // Include null-terminating character
    assert(entry != NULL); 

    entry->timestamp = timestamp;
    strcpy(entry->key, key);

    entries[timestamp] = entry;

    pthread_mutex_unlock(&lock);
}

char* lookup(long timestamp) {
    pthread_mutex_lock(&lock);
    assert(entries != NULL && capacity > timestamp && entries[timestamp] != NULL); 

    char* key = strdup(entries[timestamp]->key); // Duplicate string to prevent corruption from outside modification
    pthread_mutex_unlock(&lock);

    return key;
}
```

