typedef struct DCIMessage {
    int DLLayerIndication;
    int DMRSConfigurationDetails;
    struct DCIMessage *next;
} DCIMessage;

DCIMessage* head = NULL;
int capacity = 0;
pthread_mutex_t lock;
sem_t semaphore;

void initList(int maxCapacity) {
    if (maxCapacity <= 0) {
        printf("Invalid list size");
        exit(-1);
    }

    capacity = maxCapacity;
    pthread_mutex_init(&lock, NULL);
    sem_init(&semaphore, 0, capacity);
}

void addMessage(int DLLayerIndication, int DMRSConfigurationDetails) {
    DCIMessage *newNode = malloc(sizeof(DCIMessage));
    newNode->DLLayerIndication = DLLayerIndication;
    newNode->DMRSConfigurationDetails = DMRSConfigurationDetails;
    newNode->next = NULL;

    sem_wait(&semaphore);
    pthread_mutex_lock(&lock);

    if (head == NULL) {
        head = newNode;
    } else {
        DCIMessage *current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newNode;
    }

    pthread_mutex_unlock(&lock);
}

// Similar functions for delete, lookup and traverse...
```

