    void* next;   // Use a void pointer and typecasting to implement circular linked list without additional space for pointers to the next record.
} Record;

Record* createLinkedList(int num_records, int min, int max) {
    long* offsets = (long*) malloc(sizeof(long)*num_records); // Allocate memory for offset values
    int* keys = (int*) malloc(sizeof(int)*num_records);      // Allocate memory for keys array

    Record* firstRecord;
    Record* currentRecord;

    srand(time(0));  // Initialize random seed.

    for(int i=0;i<num_records;i++) {
        Record record = (Record*) malloc(sizeof(Record));

        record->value = rand() % (max - min + 1) + min;  // Set a random value within specified range.
        record->offset = &offsets[i];  
        record->next = NULL;

        if(i==0) {
            firstRecord = currentRecord = record;
        } else {
            currentRecord->next = (void*) record;  // Set the next pointer without additional space for pointers to the next record.
            currentRecord = record;
        }
    }

    currentRecord->next = (void*) firstRecord;  // Ensure last node points back to the first node.

    return firstRecord;  
}
