For decryption function:

```c
char* base64Decrypt(const char* b64message, const unsigned char* key) {
    EVP_CIPHER_CTX *ctx;
    int len;
    int plaintext_len;
    BIO *bio, *b64;

    // Create and initialise the context
    ctx = EVP_CIPHER_CTX_new();
    EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, NULL);

    // Decode base64
    bio = BIO_new_mem_buf((void*) b64message, -1); 
    b64 = BIO_new(BIO_f_base64());
    BIO_push(b64, bio);

    // Allocate memory for plaintext. We could make this more efficient by reading and decoding in chunks.
    unsigned char* ciphertext = (unsigned char*) malloc(strlen(b64message)); 
    BIO_read(b64, ciphertext, strlen(b64message));

    // Allocate memory for the plaintext
    unsigned char* plaintext = (unsigned char*) malloc(ciphertext); 

    EVP_DecryptUpdate(ctx, plaintext, &len, ciphertext, ciphertext_len);
    plaintext_len = len;

    // Finalise the decryption. Further plaintext bytes may be written at this stage.
    EVP_DecryptFinal_ex(ctx, plaintext + len, &len);
    plaintext_len += len;

    EVP_CIPHER_CTX_free(ctx); // Clean up

    return (char*)plaintext; // Convert the plaintext to a char* string.
}
```
