Node* createNode(int key, long offset, int value) {
    Node *node = (Node*) malloc(sizeof(Node));

    if (node == NULL) return NULL;

    node->record.key = key;
    node->record.offset = offset;
    node->record.value = value;
    node->next = node;
    node->prev = node;

    return node;
}

Node* insert(Node* head, int key, long offset) {
    Node *node = createNode(key, offset, externalDataSource());

    if (node == NULL) return head;

    if (head == NULL) {
        head = node;
    } else {
        node->next = head;
        node->prev = head->prev;

        head->prev->next = node;
        head->prev = node;

        if (key < head->record.key) {
            head = node;
        }
    }

    return head;
}

Node* delete(Node* head, int key) {
    Node *current;

    for (current = head; current->next != head && current->record.key != key; current = current->next);

    if (current->record.key == key) {
        if (head == current) {
            head = head->next;
        }

        current->prev->next = current->next;
        current->next->prev = current->prev;

        free(current);
    }

    return head;
}

