#include <unistd.h>
#include <fcntl.h>
#include <limits.h>

// Forward declaration of helper functions
int processImage(const char *inputPath, const char *outputPrefix, 
                 const char *params, const char *compressionSettings, int bufferSizeMB);
void logError(const char* errorMsg);

#define MAX_PATHLEN PATH_MAX
#define BUFFER_SIZE_BYTES 1024 * 1024

int batchProcessImages(const char *inputDirPath, const char *outputDirPath, 
                      const char *inputImagePattern, const char *outputPrefix, 
                      const char *params, const char *compressionSettings, int bufferSizeMB, 
                      const char *logLevel) {
    // Validate input directory and check if writable
    DIR* dir = opendir(inputDirPath);
    if (dir) {
        /* Directory exists. */
        closedir(dir);
    } else if (ENOENT == errno) {
        /* Directory does not exist. */
        logError("Input directory doesn't exist.");
        return -1;
    } else {
        /* opendir() failed for some other reason. */
        char errorMsg[MAX_PATHLEN + 20];
        sprintf(errorMsg, "Cannot open input directory: %s", strerror(errno));
        logError(errorMsg);
        return -1;
    }

    // Validate output directory and check if writable
    dir = opendir(outputDirPath);
    if (dir) {
        /* Directory exists. Check if it's writable. */
        int fd = open(outputDirPath, O_WRONLY);
        if (fd == -1) {
            logError("Output directory is not writable.");
            return -1;
        } else {
            close(fd);
        }
    } else if (ENOENT == errno) {
        /* Directory does not exist. */
        logError("Output directory doesn't exist.");
        return -1;
    } else {
        /* opendir() failed for some other reason. */
        char errorMsg[MAX_PATHLEN + 20];
        sprintf(errorMsg, "Cannot open output directory: %s", strerror(errno));
        logError(errorMsg);
        return -1;
    }

    // Process each image in the input directory...
    struct dirent *ent;
    while ((ent = readdir (dir)) != NULL) {
       if(!fnmatch(inputImagePattern, ent->d_name, 0)) {
           char fullInputPath[MAX_PATHLEN];
           sprintf(fullInputPath, "%s/%s", inputDirPath, ent->d_name);

           // Process the image...
           if(!processImage(fullInputPath, outputPrefix, params, compressionSettings, bufferSizeMB)) {
               logError("Failed to process an image.");
               return -1;
           } 
       }
    }

    closedir (dir);
}
```
