['Here's a simple implementation of your task using C. I assumed that file name "data.txt" will be passed as an argument to function. 

```C
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>

typedef struct record {
    int key;
} Record;

int processRecords(const char* filename, size_t numOfElements, long range) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        printf("Could not open file: %s\n", strerror(errno));
        return 0;
    }

    // Allocate memory for arrays
    long* offsetArray = malloc(numOfElements * sizeof(long));
    int* keyArray = calloc(numOfElements, sizeof(int));

    if (!offsetArray || !keyArray) {
        printf("Memory allocation failed: %s\n", strerror(errno));
        return 0;
    }

    Record* recordArray = malloc(numOfElements * sizeof(Record));

    if (!recordArray) {
        printf("Memory allocation failed: %s\n", strerror(errno));
        return 0;
    }

    // Initialize the record array by reading integers from file
    for (size_t i = 0; i < numOfElements; ++i) {
        if (fscanf(file, "%d", &recordArray[i].key) != 1) {
            printf("Error while reading from file\n");
            break;
        }
    }

    // Generate random long offset values and assign them to the offset array
    srand((unsigned int)time(NULL));
    for (size_t i = 0; i < numOfElements; ++i) {
        offsetArray[i] = rand() % range - (range / 2);
    }

    // Handle cases where an invalid index is encountered by skipping the record
    int processedCount = 0;
    for (size_t i = 0; i < numOfElements; ++i) {
        long sum = offsetArray[i] + recordArray[i].key;

        if (sum >= 0 && sum < numOfElements && !keyArray[sum]) {
            keyArray[sum] = 1;
            ++processedCount;
        } else {
            printf("Invalid index encountered, skipping this record.\n");
        }
    }

    // Free memory and return processed count
    free(offsetArray);
    free(keyArray);
    free(recordArray);
    fclose(file);

    return processedCount;
}
```

You can call the function like this:
