['The task described is quite complex and may require a full-fledged project rather than just writing one function, but I will provide an outline code base for your request. Due to the complexity of the task, there would be separate modules or files for each aspect like allocator, memory pool, concurrency control etc. 

For demonstration purposes only, I'll show a simplified version of how you can manage concurrent access and thread-safe operations using `pthread` library in C:

```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <pthread.h>
#include <time.h>

// Define a structure to hold the memory pool
typedef struct {
    int* keys;
    long* offsets;
} Record;

Record records[10]; // Assume 10 records as an example
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to allocate memory for the key and offset array
void* allocateMemory(int size) {
    void *mem = NULL;
    if (posix_memalign(&mem, getpagesize(), size)) {
        perror("Couldn't allocate memory: ");
        exit(EXIT_FAILURE);
    }
    return mem;
}

// Function to initialize the record and its fields
Record* initRecords() {
    srand(time(NULL)); // Seed for random number generation
    Record *r = malloc(sizeof(Record));
    r->keys = allocateMemory(10 * sizeof(int));
    r->offsets = allocateMemory(10 * sizeof(long));

    for (int i = 0; i < 10; ++i) {
        r->keys[i] = rand() % 100; // Assigning random values to keys
        r->offsets[i] = rand() % 100; // Assigning random values to offsets
    }

    return r;
}

// Thread function for concurrent access management
void* threadFunction(void *arg) {
    int index = *((int*) arg);

    pthread_mutex_lock(&lock); // Locking the memory pool for exclusive access

    records[index] = *initRecords(); // Assigning record to memory pool

    sleep(1); // Simulating heavy workload

    printf("Thread %d has finished its task\n", index); 

    pthread_mutex_unlock(&lock); // Unlocking the memory pool for other threads

    return NULL;
}

int main() {
    pthread_t threads[10]; // Assume we have 10 threads

    int indexes[10]; // Array to hold indexes of records
    for (int i = 0; i < 10; ++i) {
        indexes[i] = i;
    }

    for (int i = 0; i < 10; ++i) {
        pthread_create(&threads[i], NULL, threadFunction, &indexes[i]); // Creating threads and passing their index to identify the record they should use
    }

    // Wait for all threads to finish
    for (int i = 0; i < 10; ++i) {
        pthread_join(threads[i], NULL); 
    }

    // Clean up allocated memory when the function is no longer needed
    for (int i = 0; i < 10; ++i) {
        free(records[i].keys);
        free(records[i].offsets);
    }

    return 0;
}
```
This code demonstrates how to manage concurrent access and thread-safe operations using pthread library. It allocates memory for `Record` structure and its fields in a thread-safe manner by locking the mutex before accessing the memory pool and unlocking it after finished task. At last, it cleans up allocated memory when no longer needed.
']

