MemPoolAllocator pool;  // Global memory pool allocator instance.

// Function to initialize a node in the BST:
Node* initNode(float temp, char* sensorID) {
    Node* node = (Node*) malloc_pool(sizeof(Node));
    if(node == NULL) return NULL; // Handle allocation failure

    node->data.temp = temp;
    node->data.sensorID = sensorID;
    node->left = node->right = NULL;
    return node;
}

// Function to insert a new reading into the BST:
Node* insert(Node* node, float temp, char* sensorID) {
    if (node == NULL)  // If the tree is empty or we've reached a leaf.
        return initNode(temp, sensorID);

    // Insert in left subtree if temperature is less than current node.
    if (temp < node->data.temp)
        node->left = insert(node->left, temp, sensorID);

    // Else insert into the right subtree.
    else if (temp > node->data.temp)
        node->right = insert(node->right, temp, sensorID);

    return node;  // Return root of modified tree.
}

