import java.io.*;

public class Deserializer {
    public static Object deserializeObject(byte[] serialized, long seed) throws Exception {
        ByteArrayInputStream bais = new ByteArrayInputStream(serialized);
        try (ObjectInputStream ois = new ObjectInputStreamWithRandomSeed(bais, seed)) {
            return ois.readObject();
        } catch (InvalidClassException e) { // Handle version compatibility issues
            throw new Exception("Incompatible serialization version", e);
        } catch (IOException | ClassNotFoundException e) { // Handle other deserialization exceptions
            throw new Exception("Failed to deserialize object", e);
        }
    }
}

class ObjectInputStreamWithRandomSeed extends ObjectInputStream {
    private final Random rnd;

    public ObjectInputStreamWithRandomSeed(InputStream in, long seed) throws IOException {
        super(in);
        this.rnd = new Random(seed); // Use the provided seed for random number generation
    }

    @Override
    protected ObjectStreamClass readClassDescriptor() throws IOException, ClassNotFoundException {
        ObjectStreamClass desc = super.readClassDescriptor();

        if (desc.getSerialVersionUID() != rnd.nextLong()) { // Simulate random version compatibility issues
            throw new InvalidClassException("Incompatible serialization version");
        }

        return desc;
    }
}
```
