```C
#include <stdlib.h>
#include <pthread.h>
#include <stdio.h>

#define MAX_TASKS 10000

typedef enum {
    RUNNING,
    PAUSED,
    STOPPED,
} Status;

typedef struct Task {
    int id;
    int priority;
    Status status;
    char *description;
} Task;

// Linked list for task storage
typedef struct Node {
    Task *task;
    struct Node *next;
} Node;

Node *head = NULL;
int count = 0;  // to keep track of number of tasks in the system
pthread_mutex_t lock; // mutex lock for thread safety

// Custom allocator that switches between stack and heap allocation strategies based on task additions/deletions
void *myalloc(size_t size) {
    static int count = 0;
    ++count;
    if (count % 10 < 7) // switch to stack allocation after 7 continuous allocations, adjust the ratio as necessary
        return alloca(size);
    else
        return malloc(size);
}

// Add task to linked list, with thread safety
void addTask(int id, int priority, Status status, char *description) {
    pthread_mutex_lock(&lock);  // lock before adding a new task

    if (count >= MAX_TASKS) {
        printf("Maximum tasks limit reached. Cannot add more tasks.\n");
        return;
    }

    Task *task = myalloc(sizeof(Task));
    task->id = id;
    task->priority = priority;
    task->status = status;
    task->description = description;

    Node *node = myalloc(sizeof(Node));
    node->task = task;
    node->next = head;
    head = node;
    ++count;

    printf("Added task with id: %d\n", id);

    pthread_mutex_unlock(&lock);  // unlock after adding a new task
}

// Remove task from linked list, with thread safety
void removeTask(int id) {
    pthread_mutex_lock(&lock);  // lock before removing a task

    Node *temp = head;
    Node *prev = NULL;

    if (temp != NULL && temp->task->id == id) {
        head = temp->next;
        free(temp->task);
        free(temp);
        --count;
        printf("Removed task with id: %d\n", id);
    } else {
        while (temp != NULL && temp->task->id != id) {
            prev = temp;
            temp = temp->next;
        }

        if (temp == NULL) return; // task not found

        prev->next = temp->next; 
        free(temp->task);
        free(temp);
        --count;
        printf("Removed task with id: %d\n", id);
    }

    pthread_mutex_unlock(&lock);  // unlock after removing a task
}
```
This code snippet demonstrates how to use mutex locks for thread safety, and a custom allocator that switches between stack allocation (`alloca()`) and heap allocation (`malloc()`), based on the frequency of task additions/deletions. The actual implementation would need to consider various factors like logging mechanism, error handling, efficient memory deallocation etc. This is just a simple illustration of how you can approach this problem using C language.
