// Function to allocate and initialize primary arrays and linked list of messages.
void init_messages(int numMessages, int idRange) {
    long *timestamps = (long*)malloc(sizeof(long)*numMessages);
    char **contents = (char**)malloc(sizeof(char*)*numMessages);
    int *ids = (int*)malloc(sizeof(int)*numMessages);
    Message *messages = (Message*)malloc(sizeof(Message)*numMessages);

    // Initialize arrays and linked list
    for(int i=0; i<numMessages; i++) {
        timestamps[i] = 0L;
        contents[i] = malloc(256); // Allocate space for message content

        // Generate random unique identifier within specified range
        int newId;
        do {
            newId = rand() % idRange;
        } while(!unique_id(newId, i, ids));
        ids[i] = newId;

        // Initialize each message structure with timestamps, content, and ID
        messages[i].timestamp = 0L;
        messages[i].content = contents[i];
        messages[i].id = ids[i];
    }

    // Form a doubly linked list where each message points to next & previous
    for(int i=0; i<numMessages; i++) {
        if(i==0) {
            messages[i].prev = &messages[numMessages-1];
        } else {
            messages[i].prev = &messages[i-1];
        }

        if(i == numMessages - 1) {
            messages[i].next = &messages[0];
        } else {
            messages[i].next = &messages[i+1];
        }
    }

    // Free the memory and return
    for(int i=0; i<numMessages; i++) {
        free(contents[i]);
    }
    free(timestamps);
    free(contents);
    free(ids);
    free(messages);
}

// Helper function to check if ID is unique in the array
int unique_id(int id, int size, int *array) {
    for(int i=0; i<size; i++){
        if(array[i] == id){
            return 0; // Not unique
        }
    }
    return 1; // Unique
}
