#include <stdlib.h>
#include <pthread.h>
#include <sys/time.h>

// Define the structure to hold metadata and pointers to previous & next records
typedef struct Record {
    int value;
    void *key;
    time_t timestamp;
    struct Record *prev, *next;
} Record;

// Define a memory pool for efficient allocation and deallocation of memory blocks.
typedef struct MemoryPool {
    size_t blockSize;
    size_t numBlocks;
    void **blocks;
    pthread_mutex_t lock; // For thread safety
} MemoryPool;

// Function to initialize the memory pool
MemoryPool *initMemoryPool(size_t blockSize, size_t numBlocks) {
    MemoryPool *pool = malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->blockSize = blockSize;
    pool->numBlocks = numBlocks;
    pool->blocks = calloc(numBlocks, sizeof(void*));
    pthread_mutex_init(&pool->lock, NULL);

    for (size_t i = 0; i < numBlocks; ++i) {
        pool->blocks[i] = malloc(blockSize);
    }
    return pool;
}

// Function to allocate memory from the pool
void *allocFromPool(MemoryPool *pool) {
    void *ptr = NULL;

    pthread_mutex_lock(&pool->lock); // Lock for thread safety
    for (size_t i = 0; i < pool->numBlocks; ++i) {
        if (pool->blocks[i]) {
            ptr = pool->blocks[i];
            pool->blocks[i] = NULL;
            break;
        }
    }
    pthread_mutex_unlock(&pool->lock); // Unlock after allocation

    return ptr;
}

// Function to deallocate memory back to the pool
void freeToPool(MemoryPool *pool, void *ptr) {
    pthread_mutex_lock(&pool->lock); // Lock for thread safety
    for (size_t i = 0; i < pool->numBlocks; ++i) {
        if (!pool->blocks[i]) {
            pool->blocks[i] = ptr;
            break;
        }
    }
    pthread_mutex_unlock(&pool->lock); // Unlock after deallocation
}
```
