['Here is the C code for the problem:

```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <assert.h>

typedef struct {
    double value;
    time_t timestamp;
    char *id;
} data_point;

typedef struct node{
    data_point dp;
    struct node* next;
}node;

// Dummy function to allocate memory for a new data point
data_point* create_datapoint(double value, time_t timestamp, const char *id){
    data_point* newDP = malloc(sizeof(data_point));
    assert(newDP != NULL);
    newDP->value = value;
    newDP->timestamp = timestamp;
    newDP->id = strdup(id);  // Allocate and copy the ID string
    return newDP;
}

// Dummy function to free memory of a data point
void destroy_datapoint(data_point* dp){
    free(dp->id);
    free(dp);
}

node *head = NULL, *tail=NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Adding a data point to the collection
void addDataPoint(data_point* dp){
    pthread_mutex_lock(&lock);
    node *newNode= malloc(sizeof(node));
    assert(newNode != NULL);
    newNode->dp = *dp; // Copy the data point, not just reference
    newNode->next = NULL;
    if(tail == NULL){
        head = tail = newNode;
    }else{
        tail->next = newNode;
        tail = newNode;
    }
    pthread_mutex_unlock(&lock);
}

// Iterating over existing data points
void iterateDataPoints(void (*callback)(data_point*)){
    for(node *n=head; n != NULL; n = n->next){
        callback(&n->dp); // Apply the callback function
    }
}

// Clearing the collection
void clearDataPoints(){
    pthread_mutex_lock(&lock);
    node* currNode;
    while(head != NULL){
        currNode = head;
        head = head->next;
        destroy_datapoint(&currNode->dp); // Free the data point memory
        free(currNode); // Free the node memory
    }
    tail = NULL;
    pthread_mutex_unlock(&lock);
}
``` 
This is a simple implementation that uses a linked list for efficient insertion and deletion. The `pthread` library is used to ensure thread safety with mutual exclusion (mutex) locks. Memory usage has been kept to a minimum by only allocating and freeing memory when necessary, and the code has been designed with error handling in mind.
