#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    double number;
    char *str;
} Structure;

typedef struct {
    pthread_mutex_t lock;
    int size;
    int capacity;
    Structure *array;
} Array;

Array create(int maxSize, int stringLength) {
    srand((unsigned int)time(NULL)); // Seed the random number generator.
    Array array = { .capacity = 0, .size = 0 };
    if (pthread_mutex_init(&array.lock, NULL)) {
        fprintf(stderr, "Failed to initialize mutex.\n");
        exit(EXIT_FAILURE);
    }
    int chunkSize = maxSize < 16 ? maxSize : 16; // Start with a small allocation for efficiency.
    while (array.capacity < maxSize) {
        Structure *newArray = realloc(array.array, sizeof(*newArray) * (chunkSize + array.capency));
        if (!newArray) {
            fprintf(stderr, "Failed to allocate memory.\n");
            exit(EXIT_FAILURE); // Failed to resize array. Abort with a graceful error message.
        }
        array.array = newArray;
        for (int i = array.capacity; i < chunkSize + array.capency; i++) {
            array.array[i].number = ((double)rand() / RAND_MAX); // Assign random floating-point number between 0 and 1.
            array.array[i].str = malloc(stringLength + 1); // Allocate memory for string with null terminator.
            if (!array.array[i].str) {
                fprintf(stderr, "Failed to allocate memory.\n");
                exit(EXIT_FAILURE); // Failed to allocate string memory. Abort with a graceful error message.
            }
            for (int j = 0; j < stringLength; j++) {
                array.array[i].str[j] = 'a' + rand() % 26; // Assign random alphabet character.
            }
            array.array[i].str[stringLength] = '\0'; // Null terminate the string.
        }
        array.capacity += chunkSize;
    }
    return array;
}

void iterate(Array *array) {
    pthread_mutex_lock(&array->lock);
    for (int i = 0; i < array->size; i++) {
        printf("Number: %f, String: %s\n", array->array[i].number, array->array[i].str);
    }
    pthread_mutex_unlock(&array->lock);
}

void destroy(Array *array) {
    for (int i = 0; i < array->capacity; i++) {
        free(array->array[i].str); // Free the string memory.
    }
    free(array->array); // Free the main array memory.
    pthread_mutex_destroy(&array->lock); // Destroy the mutex lock.
}
