typedef struct record {
    _Atomic int value;
} record_t;

int keygen(long *offsets, int n) {
    srand((unsigned) time(NULL));
    for (int i = 0; i < n - 1; ++i) {
        if ((abs(offsets[i] - offsets[i+1])) < 20) {
            return i;
        }
    }
    return -1;
}

void initialize_records(record_t ** records, long *offsets, int n, int key) {
    for (int i = 0; i < n; ++i) {
        atomic_init(&((*records)[i].value), 0);
    }
}

void deallocate(record_t ** records) {
    free(*records);
}

long generate_prime() {
    // This is a very simple prime generator and has room for improvements.
    long value = 1;
    while (value < 2 || value > LONG_MAX / 20) {
        value = rand();
    }
    return value * 20 + 1;
}

void update(record_t ** records, int key, int index, long offset, atomic_int *total) {
    atomic_fetch_add(&((*records)[index - offset].value), generate_prime());
    atomic_fetch_add(total, (*records)[index-offset].value);
}

void memory_usage() {
    // This is a very simple implementation and has room for improvements.
    struct rusage usage;
    getrusage(RUSAGE_SELF, &usage);
    printf("Memory Usage: %ld\n", usage.ru_maxrss);
}

