typedef struct MemoryPool {
    void *memory;
    size_t blockSize;
    int numBlocks;
    bool *isAllocated;
} MemoryPool;

// Initialize pool.
MemoryPool* initMemoryPool(size_t blockSize, int numBlocks) {
   // Allocate memory of the required size.
   void *memory = allocate(blockSize * numBlocks);

   // Initialize isAllocated array indicating if each block is allocated or not.
   bool *isAllocated = (bool *)allocate(sizeof(bool) * numBlocks);

   // Return the memory pool.
   return &((MemoryPool){memory, blockSize, numBlocks, isAllocated});
}
