["Here is a basic implementation of such a function in C:

```C
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct Record {
    int key;
    int value;
} Record;

typedef struct Node {
    Record* record;
    struct Node *next, *prev;
} Node;

Node* new_node(int k, int v) {
    Node* node = malloc(sizeof(Node));
    if (node == NULL) exit(EXIT_FAILURE);

    Record* rec = malloc(sizeof(Record));
    if (rec == NULL) exit(EXIT_FAILURE);

    rec->key = k;
    rec->value = v;
    node->record = rec;
    node->next = NULL;
    node->prev = NULL;

    return node;
}

Node* initialize_list(int num, int min, int max) {
    srand(time(NULL));

    if (num <= 0 || min >= max) exit(EXIT_FAILURE);

    Node *head = new_node(rand() % 10 + 1, rand() % max + min), *tail = head;

    for (int i = 1; i < num; ++i) {
        tail->next = new_node(rand() % 10 + 1, rand() % max + min);
        tail->next->prev = tail;
        tail = tail->next;
    }

    head->prev = tail;
    tail->next = head;

    return head;
}
```
This code implements a doubly linked list where each node contains a pointer to a 'Record' structure. The 'initialize_list()' function generates and initializes this list, given the number of nodes ('num'), as well as minimum and maximum possible values for the record's value (inclusive). Keys are randomly generated between 1 and 10, while values are randomly generated within the specified range.
