#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int key;
    long offset;
} record;

void* allocate_memory(size_t size, const char *type) {
    void *ptr = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (ptr == MAP_FAILED) {
        perror("Allocation failed");
        exit(EXIT_FAILURE);
    } else {
        printf("%s memory allocated: %zu bytes at address: %p\n", type, size, ptr);
    }
    return ptr;
}

void initialize_keys(int *keys, int len, int initial) {
    for (int i = 0; i < len; i++) {
        keys[i] = initial + i; // Linear sequence starting from the initial key value
    }
}

long random_offset(const long max, const long min) {
    return rand() % (max - min + 1) + min;
}

void initialize_offsets(record *records, int len, const long max_offset, const long min_offset) {
    for (int i = 0; i < len; i++) {
        long offset = random_offset(max_offset, min_offset);
        // Verify that all offset values are unique and within the specified range
        for (int j = 0; j < i; j++) {
            if (records[j].offset == offset) {
                srand(time(NULL)); // Reinitialize random seed if duplicate detected
                offset = random_offset(max_offset, min_offset);
                j = -1; // Restart the loop to check for duplicates again with new random seed
            }
        }
        records[i].offset = offset;
    }
}

void* parallel_initialize(void *arg) {
    record *records = (record *) arg;
    initialize_keys(&records->key, 1, initial);
    return NULL;
}

int main() {
    const int num_elements = 1000000; // Example number of elements per array
    long max_offset = (long) 1e6;   // Example maximum offset value
    long min_offset = 0;            // Example minimum offset value
    int initial_key = 1000;         // Example initial key value
    srand(time(NULL));              // Random seed for rand() function

    // Allocate memory
    void *longs = allocate_memory(sizeof(long) * num_elements, "Long");
    void *ints = allocate_memory(sizeof(int) * num_elements, "Int");
    record *records = allocate_memory(sizeof(record) * num_elements, "Record");

    // Initialize keys in parallel
    pthread_t threads[num_elements];
    for (int i = 0; i < num_elements; i++) {
        if (pthread_create(&threads[i], NULL, &parallel_initialize, &records[i])) {
            perror("Thread creation failed");
            return EXIT_FAILURE;
        }
    }

    // Initialize offsets
    initialize_offsets(records, num_elements, max_offset, min_offset);

    // Wait for all threads to finish
    for (int i = 0; i < num_elements; i++) {
        if (pthread_join(threads[i], NULL)) {
            perror("Thread join failed");
            return EXIT_FAILURE;
        }
    }

    // Deallocate memory
    munmap(longs, sizeof(long) * num_elements);
    munmap(ints, sizeof(int) * num_elements);
    munmap(records, sizeof(record) * num_elements);

    return EXIT_SUCCESS;
}
```
