void initializeSensorArray(int numSensors) {
    for (int i = 0; i < numSensors; ++i) {
        Node* newNode = malloc(sizeof(Node));
        newNode->sensor.deviceId = i;
        newNode->sensor.timestamp = time(NULL);
        newNode->sensor.rawData = malloc(1024 * sizeof(char));

        pthread_mutex_lock(&lock);
        if (head == NULL) {
            head = tail = newNode;
            head->prev = tail;
            tail->next = head;
        } else {
            tail->next = newNode;
            newNode->prev = tail;
            tail = newNode;
            head->prev = tail;
        }
        ++size;
        pthread_mutex_unlock(&lock);
    }
}

void dequeueSensorData() {
    while (1) {
        pthread_mutex_lock(&lock);
        if (size > 0 && size % 10 == 0) {
            Node* oldNode = head;
            head = head->next;
            free(oldNode->sensor.rawData);
            free(oldNode);
            --size;
        }
        pthread_mutex_unlock(&lock);
    }
}
