#include <jemalloc/jemalloc.h>  // Example of an external library for memory management

typedef struct Record {
    int value;
    int* key_ptr;
} Record;

typedef struct Node {
    Record record;
    struct Node* next;
} Node;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; // Mutex for thread safety
int mem_used = 0, max_mem_used = 0;
int mem_frag = 0, max_mem_frag = 0;

void* allocate(size_t size) {
    pthread_mutex_lock(&lock);
    void *ptr = je_malloc(size); // Using a memory management library
    assert(ptr != NULL);

    int frag = (1 - ((float)(JETSSTATS.bytes_free+size)/JETSSTATS.bytes_total))*100;
    mem_used += size;
    if (mem_used > max_mem_used) max_mem_used = mem_used;
    if (frag > max_mem_frag) max_mem_frag = frag;

    pthread_mutex_unlock(&lock);
    return ptr;
}

void deallocate(void* ptr, size_t size) {
    pthread_mutex_lock(&lock);
    je_free(ptr); // Using a memory management library

    mem_used -= size;
    int frag = (1 - ((float)(JETSSTATS.bytes_free)/JETSSTATS.bytes_total))*100;
    if (frag > max_mem_frag) max_mem_frag = frag;

    pthread_mutex_unlock(&lock);
}
```
The above code implements a simple memory allocator that uses `je_malloc` and `je_free` from the Jemalloc library. It also keeps track of maximum memory usage and fragmentation levels using mutex locks for thread safety. 

