        offsets[i] = i;
    }

    pthread_mutex_lock(&lock);
    for (size_t i = 0; i < size; ++i) {
        keys[i] = seed + i * step;
        records[i].value = rand() % (range[1] - range[0]) + range[0];
        Node* node = malloc(sizeof(Node));
        if (!node) {
            // Log error and handle exception appropriately.
            goto cleanup;
        }
        node->value = rand() % (range[1] - range[0]) + range[0];
        atomic_init(&records[i].pointer, node);
    }
    pthread_mutex_unlock(&lock);

    return records;

cleanup:
    free(offsets);
    _mm_free(keys);
    free(records);
    return NULL;
}
