void initDataStructures() {
    dataSize = parser->dataSize;

    posix_memalign((void **)&offsets, alignof(max_align_t), sizeof(long) * dataSize);
    for (size_t i = 0; i < dataSize; ++i) {
        offsets[i] = i;
    }

    posix_memalign((void **)&keys, alignof(max_align_t), sizeof(int) * dataSize);
