        node->data = randomValue;
        records[i].value = randomValue;
        records[i].node = node;

        // Add to doubly linked list
        if (listHead == NULL) {
            listHead = node;
            listTail = node;
        } else {
            listTail->next = node;
            node->prev = listTail;
            listTail = node;
        }
    }

    // Process your data here...

    pthread_mutex_unlock(&lock); // Unlock after processing

    // Free allocated memory before exiting
    for (Node* current = listHead, *next = NULL; current != NULL; current = next) {
        next = current->next;
        free(current);
    }
    free(records);
    free(keys);
    free(offsets);
}
