['Here is an implementation using C and Pthreads for multi-threading in Linux environment:

```C
#include <pthread.h>
#include <stdlib.h>
#include <string.h>

typedef struct Role {
    char *name;
    char *description;
    struct Role *next;
} Role;

typedef struct UserProfile {
    char *username;
    char *emailAddress;
    int userID;
    Role *roles;
} UserProfile;

typedef struct HashTableNode {
    int key;
    UserProfile *profile;
    struct HashTableNode *next;
} HashTableNode;

HashTableNode **hash_table = NULL;
int hash_table_size = 0;
pthread_mutex_t lock;

unsigned long hash(int key) {
    return (key % hash_table_size);
}

UserProfile* initUserProfile(char *username, char *emailAddress, int userID, Role *roles) {
    UserProfile *newUser = malloc(sizeof(UserProfile));
    newUser->username = strdup(username);
    newUser->emailAddress = strdup(emailAddress);
    newUser->userID = userID;
    newUser->roles = roles;
    return newUser;
}

Role* initRole(char *name, char *description) {
    Role *newRole = malloc(sizeof(Role));
    newRole->name = strdup(name);
    newRole->description = strdup(description);
    newRole->next = NULL;
    return newRole;
}

void addUserProfileToHashTable(char *username, char *emailAddress, int userID, Role *roles) {
    UserProfile *new_profile = initUserProfile(username, emailAddress, userID, roles);

    pthread_mutex_lock(&lock);
    unsigned long index = hash(userID);

    HashTableNode *node = malloc(sizeof(HashTableNode));
    node->key = userID;
    node->profile = new_profile;
    node->next = hash_table[index]; 
    hash_table[index] = node;

    pthread_mutex_unlock(&lock);
}

HashTableNode* getUserProfileFromHashTable(int userID) {
    pthread_mutex_lock(&lock);

    unsigned long index = hash(userID);
    HashTableNode *node = hash_table[index];

    while (node != NULL && node->key != userID) 
        node = node->next;

    pthread_mutex_unlock(&lock);

    return node;
}

void deleteUserProfileFromHashTable(int userID) {
    pthread_mutex_lock(&lock);

    unsigned long index = hash(userID);
    HashTableNode *node = hash_table[index];
    HashTableNode *prev = NULL;

    while (node != NULL && node->key != userID) {
        prev = node;
        node = node->next;
    }

    if (node == NULL) return;  // No such user

    if (prev == NULL) 
        hash_table[index] = node->next;
    else 
        prev->next = node->next;

    free(node);  
    pthread_mutex_unlock(&lock);
}

HashTableNode* initHashTable() {
    pthread_mutex_init(&lock, NULL);

    hash_table_size = 1024;  // Arbitrary size, can be adjusted
    hash_table = malloc(hash_table_size * sizeof(HashTableNode*));  

    for (int i = 0; i < hash_table_size; i++) 
        hash_table[i] = NULL;

    return hash_table;
}
```

This code provides a simple implementation of user profiles and roles management. It uses a custom HashTable to store the UserProfile structs, which is thread-safe using a global mutex lock. A linked list for Roles is also implemented but not fully utilized in this example (roles assignment from external data sources can be integrated). 

This basic example does not handle cases where hash table needs to dynamically resize or fragmentation issues. For those, more complex code would be needed that handles resizing and redistribution of nodes among new buckets. It also does not cover asynchronous operations or handling network latency bottlenecks - these are significant topics in high-traffic systems and would require additional design consideration.
']

