['This is quite an extensive task, but I can provide you with a basic outline of how such a code might look like. Keep in mind that this will not work as a standalone solution for your specific needs, but it's a starting point to develop something more robust and comprehensive.

```C
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <unistd.h>
#include <errno.h>
#include <sys/mman.h>
#include <semaphore.h>
#include <stdio.h>

typedef struct {
    int value;
} record_t;

typedef struct metadata_s {
    long offset;
    int size;
    int accessFreq;
} metadata_t;

typedef struct memoryPool_s {
    pthread_mutex_t lock;
    sem_t semaphore;
    record_t *records;
    int *keys;
    metadata_t *metadata;
    int poolSize;
    clock_t startTime;
} memoryPool_t;

static memoryPool_t pool;
static const int MAX_POOL_SIZE = 1000000;
static const int BACKOFF_RETRIES = 5;

void initializeRecords() {
    // Initialize the mutex and semaphore
    if (pthread_mutex_init(&pool.lock, NULL) != 0) {
        printf("Failed to initialize mutex\n");
        return;
    }

    if (sem_init(&pool.semaphore, 0, MAX_POOL_SIZE) == -1) {
        printf("Failed to initialize semaphore\n");
        pthread_mutex_destroy(&pool.lock);
        return;
    }

    // Allocate memory for the pool
    pool.records = mmap(NULL, MAX_POOL_SIZE * sizeof(record_t), PROT_READ | PROT_WRITE, MAP_ANONYMOUS | MAP_SHARED, -1, 0);
    pool.keys = mmap(NULL, MAX_POOL_SIZE * sizeof(int), PROT_READ | PROT_WRITE, MAP_ANONYMOUS | MAP_SHARED, -1, 0);
    pool.metadata = mmap(NULL, MAX_POOL_SIZE * sizeof(metadata_t), PROT_READ | PROT_WRITE, MAP_ANONYMOUS | MAP_SHARED, -1, 0);

    if (pool.records == MAP_FAILED || pool.keys == MAP_FAILED || pool.metadata == MAP_FAILED) {
        printf("Failed to allocate memory for the pool\n");
        pthread_mutex_destroy(&pool.lock);
        sem_destroy(&pool.semaphore);
        return;
    }

    // Initialize pool size and start time
    pool.poolSize = 0;
    pool.startTime = clock();
}
```

This code initializes the memory pool with a maximum capacity of 1 million records. It also uses `mmap` to allocate shared memory for better performance across multiple threads, and it protects this allocation by using a semaphore to limit access when the pool is full, and a mutex to ensure synchronization. It logs errors if any operation fails.

