namespace RandomFramework {

    class DistributionInterface {
    public:
        virtual double generate() = 0;
        virtual void setParams(double mean, double stddev) = 0;
    };

    class UniformDistribution : public DistributionInterface {
    private:
        std::uniform_real_distribution<double> distr_;
        std::mt19937 gen_;
    public:
        explicit UniformDistribution(int seed) : gen_(seed), distr_(0.0, 1.0) {}
        double generate() override { return distr_(gen_); }
        void setParams(double mean, double stddev) override { distr_ = std::uniform_real_distribution<double>(mean - stddev, mean + stddev); }
    };

    // Implement other distributions similarly as needed...

    class RandomGenerator {
    private:
        DistributionInterface* distribution_;
        int seed_;
        double mean_, stddev_;
        mutable std::mutex mtx_;  // for thread safety
    public:
        explicit RandomGenerator(DistributionInterface* distr, int seed = 0, double mean = 0.0, double stddev = 1.0) : distribution_(distr), seed_(seed), mean_(mean), stddev_(stddev) {}
        ~RandomGenerator() { delete distribution_; }
        void setParams(double mean, double stddev) {
            std::lock_guard<std::mutex> lock(mtx_);
            mean_ = mean;
            stddev_ = stddev;
            distribution_->setParams(mean_, stddev_);
        }
        void reset() {
            std::lock_guard<std::mutex> lock(mtx_);
            delete distribution_;
            distribution_ = new UniformDistribution(seed_);  // replace with your chosen default distribution
            setParams(mean_, stddev_);
        }
        double generate() const {
            std::lock_guard<std::mutex> lock(mtx_);
            return distribution_->generate();
        }
    };
}
