```c
#include <stdlib.h>
#include <time.h>

typedef struct Record {
    int value;
    time_t timestamp;
    int* key;
    struct Record *prev, *next;
} Record;

typedef struct CacheNode {
    Record *record;
    struct CacheNode *prev, *next;
} CacheNode;

CacheNode* cache = NULL; // The head of the LRU cache list.
Record* records = NULL; // Head of circular doubly linked list of Records.
int recordCount = 0;

// Function to add a node to the head of a linked list
void addToHead(CacheNode** head, CacheNode* newNode) {
    if (*head != NULL) {
        (*head)->prev = newNode;
    }
    newNode->next = *head;
    newNode->prev = NULL;
    *head = newNode;
}

// Function to remove a node from its current position in the list
void removeFromList(CacheNode* node) {
    if (node->prev != NULL) {
        node->prev->next = node->next;
    } else {
        cache = node->next; // Update head of list.
    }
    if (node->next != NULL) {
        node->next->prev = node->prev;
    }
}

// Function to check the Cache for a Record with the given key, and adjust it's position in the Cache
CacheNode* lookupInCache(int *key) {
    CacheNode* current = cache;
    while (current != NULL) {
        if (current->record->key == key) {
            // If found move to head of list.
            removeFromList(current);
            addToHead(&cache, current);
            return current;
        }
        current = current->next;
    }
    return NULL; // Not found in cache
}

// Function to insert a Record into the Cache and maintain LRU property.
void insertIntoCache(Record* record) {
    if (recordCount == 0) {
        records = malloc(sizeof(Record));
    } else {
        records = realloc(records, sizeof(Record) * (recordCount + 1));
    }

    // Initialize the Record.
    Record* newRecord = &records[recordCount];
    newRecord->key = malloc(sizeof(int));
    newRecord->timestamp = time(NULL);
    newRecord->value = rand() % 100; // Random value within a specified range.

    if (cache == NULL) {
        cache = malloc(sizeof(CacheNode));
        cache->record = newRecord;
    } else {
        CacheNode* newCacheNode = malloc(sizeof(CacheNode));
        newCacheNode->record = newRecord;

        addToHead(&cache, newCacheNode); // Add to head of list.
        removeFromList(newCacheNode); // Remove from its current position in the cache.
    }

    recordCount++;
}
```
This is just an outline and does not handle deletion or updates in the Cache or the underlying Records correctly, nor does it handle concurrent accesses well. You would need to add appropriate locking mechanisms for this. Also, there are a lot of improvements that can be made based on your specific needs: thread-safety, memory efficiency, record deletion and updates, etc.
