Record* generate_records(int n, long* offsets, int** keys, double** precisions) {
    *offsets = (long*)malloc(n * sizeof(long));
    *keys = (int*)malloc(n * sizeof(int));
    *precisions = (double*)malloc(n * sizeof(double));

    for (int i = 0; i < n; ++i) {
        (*offsets)[i] = rand() % 100; // replace with actual offset generation logic if needed
        (*keys)[i] = rand() % 100; // replace with actual key generation logic if needed
        (*precisions)[i] = 5.0 * i * i - 3.0 * i + 2.0; // quadratic function, adjust coefficients as needed
    }

    Record* records = (Record*)malloc(n * sizeof(Record));

    for (int i = 0; i < n; ++i) {
        records[i].key = (*keys)[i];
        records[i].value = (*precisions)[i];

        if (i > 0) {
            records[i].prev_record = &records[i-1];
        } else {
            records[i].prev_record = &records[n - 1];
        }

        if (i < n - 1) {
            records[i].next_record = &records[i + 1];
        } else {
            records[i].next_record = &records[0];
        }
    }

    return records;
}
