    char* string;
    long offset;
} record;

int init(long n, long m, long minOffset, long maxOffset) {
    if (n <= 0 || n > MAX_SIZE || m < 0 || m > n) return -1;

    srand((unsigned int)time(NULL)); // seed the random number generator

    long* offsets = (long*)malloc(sizeof(long) * n);
    if (!offsets) return -1;  // memory allocation failure

    int* keys = (int*)malloc(sizeof(int) * n);
    if (!keys) { free(offsets); return -1; }  // memory allocation failure

    record* records = (record*)calloc(n, sizeof(record));
    if (!records) { free(offsets); free(keys); return -1; }  // memory allocation failure

    for (long i = 0; i < n; ++i) {
        offsets[i] = minOffset + rand() % (maxOffset - minOffset + 1);
        if (i > 0 && abs(offsets[i] - offsets[i-1]) > CONSECUTIVE_OFFSET_DIFF) 
            return -1; // offset difference constraint violated

        keys[i] = rand();
    }

    char* stringPool = (char*)malloc(sizeof(char) * n * 256);
    if (!stringPool) { free(offsets); free(keys); free(records); return -1; } // memory allocation failure
    memset(stringPool, 0, sizeof(char) * n * 256);

