        if (!records[i].string) { free(offsets); free(keys); free(records); return -1; }  // memory allocation failure
        strncpy(records[i].string, str, len);
    }

    // TODO: Add checks for leaks here. E.g., verify if all strings in the stringPool are allocated and only then free it.

