char *readLine(FILE *file) {
    char *line = malloc(1), *tmp;
    int size = 0, c;

    if(!line) return NULL; // handle allocation failure

    while((c = fgetc(file)) != '\n' && c != EOF){
        line[size++] = (char)c;

        tmp = realloc(line, size+1); // handle reallocation failure
        if(!tmp) {
            free(line); 
            return NULL;
        }
        line = tmp;
    }

    line[size++] = '\0'; // Null-terminate the string
    return line;
}

// Process a transaction (this function is run in separate threads)
