    temp->entry = entry;
    temp->left = temp->right = NULL;
    return temp;
}

// Function to do inorder traversal of BST. 
void inorder(Node* root) {
    if (root != NULL) {
        inorder(root->left);
        // process root here
        inorder(root->right);
    }
}

// Function to insert a new entry into the BST. 
Node* insert(Node* node, MetadataEntry entry) {
    if (node == NULL) return newNode(entry);
    // decide which subtree to go based on comparison of keys
    if (strcmp(entry.streamInfo.path, node->entry.streamInfo.path) < 0)  // Compare path for simplicity
        node->left = insert(node->left, entry);
    else
        node->right = insert(node->right, entry);
   return node;
}

