    MetadataEntry metadata[50000];  // Assume we have these data from distributed file server.

    for (int i = 0; i < 50000; i++) {
        pthread_mutex_lock(&lock);
        if (i == 0) root = insert(root, metadata[i]);
        else insert(root, metadata[i]);
        pthread_mutex_unlock(&lock);
    }
}
