// Memory Pool
typedef struct MemoryPool {
    void *memory;
    size_t size;
    pthread_mutex_t mutex;
    struct MemoryPool *next;
} MemoryPool;

MemoryPool *freeList = NULL;
pthread_mutex_t freeListMutex = PTHREAD_MUTEX_INITIALIZER;

void* allocate(size_t size) {
    void *block = NULL;
    pthread_mutex_lock(&freeListMutex);
    MemoryPool **last = &freeList;
    MemoryPool *curr = freeList;
    while (curr != NULL && block == NULL) {
        if (curr->size >= size) {
            *last = curr->next;
            curr->next = NULL;
            block = curr->memory;
        } else {
            last = &(*last)->next;
        }
    }
    pthread_mutex_unlock(&freeListMutex);
    if (block == NULL) {
        // Allocate new memory and add it to the pool.
        block = malloc(size);
        MemoryPool *newNode = malloc(sizeof(MemoryPool));
        newNode->memory = block;
        newNode->size = size;
        pthread_mutex_init(&newNode->mutex, NULL);
        pthread_mutex_lock(&freeListMutex);
        newNode->next = freeList;
        freeList = newNode;
        pthread_mutex_unlock(&freeListMutex);
    }
    return block;
}

void deallocate(void *block, size_t size) {
    MemoryPool *node = malloc(sizeof(MemoryPool));
    node->memory = block;
    node->size = size;
    pthread_mutex_init(&node->mutex, NULL);
    pthread_mutex_lock(&freeListMutex);
    node->next = freeList;
    freeList = node;
