int validateInput(int n) {
    if (n < 0 || n > INT_MAX / 1024 / 1024) // Assuming system limit is 1MB
        return -1;
    return 0;
}

void* safeMalloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        printf("Memory allocation failed\n");
        exit(-1);
    }
    return ptr;
}

int initializeRecords(int n, int m, long minOffset, long maxOffset) {
    if (validateInput(n)) return -1;

    // Allocate memory for arrays
    long* offsets = safeMalloc(sizeof(long) * n);
    int* keys = safeMalloc(sizeof(int) * n);

    // Initialize keys and offsets
    for (int i = 0; i < n; ++i) {
        keys[i] = rand();
        if (i > 0 && abs(offsets[i-1] - minOffset) > MAX_OFFSET_DIFF)
            return -2; // Offset difference exceeded threshold.
        offsets[i] = minOffset + rand() % (maxOffset - minOffset + 1);
    }

    Record* records = safeMalloc(sizeof(Record) * n);

    for (int i = 0; i < m && i < n; ++i) {
        // Initialize a record
        records[i].key = keys[i];
        records[i].offset = offsets[i];

        // Generate unique random string. Implement hash function to check for collisions.
        char* str = safeMalloc(sizeof(char) * STRING_LEN);
        // Append additional characters based on the record index.

        records[i].string = str;
    }

    // Populate string with random alphanumeric characters. Optimize for cache misses and large n.

    // Free memory when done.
    free(offsets);
    free(keys);
    for (int i = 0; i < m && i < n; ++i) {
        free(records[i].string);
    }
    free(records);

    return m < n ? m : n; // Return the number of successfully initialized records.
}
