    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(0, keyRange);

    std::unordered_set<int> keys;
    Record* records = new Record[num];
    for (int i = 0; i < num; i++) {
        int key;
        do {
            key = dis(gen);
        } while (keys.find(key) != keys.end());
        keys.insert(key);

        records[i].key = key;
        records[i].offset = 0L;
        records[i].nested_record.value = key;
        records[i].nested_record.timestamp = new double(clock() / (double)CLOCKS_PER_SEC);

        *records[i].nested_record.timestamp *= std::pow(10, precision);
        int statusInt = key % 3;
