def generate_password(size=12, chars=string.ascii_letters + string.digits):
    return ''.join(random.choice(chars) for _ in range(size))

def encrypt_password(pwd, method, key):
    if method == "base64":
        return base64.b64encode(pwd.encode()).decode()
    elif method == "hashlib":
        h = hashlib.new(key)
        h.update(pwd.encode())
        return h.hexdigest()
    else:
        raise ValueError("Invalid encryption method")

def sed_inplace(filename, oldstr, newstr):
    p = Popen(['sed', '-i', f's/{oldstr}/{newstr}/g', filename], stderr=STDOUT)
    if p.wait():
        raise Exception(f"Sed command failed with return code {p.returncode}")

def handle_config(filename, section):
    config = {}  # load configuration from file or generate default
    newpass = getpass.getpass("Enter your password: ")
    encrymethod = os.environ.get('ENCRYPTION_METHOD', 'base64')
    encrykey = os.environ.get('ENCRYPTION_KEY', 'md5')
    encryptedpwd = encrypt_password(newpass, encrymethod, encrykey)

    if section not in config:
        config[section] = {}

    # replace placeholders with actual values
    for k, v in config[section].items():
        sed_inplace(filename, k, v)

    # append new encrypted password line
    with open(filename, "a") as file:
        file.write(f"EncryptedPassword={encryptedpwd}\n")

def generate_data(size):
