typedef struct {
    int value;
} nested_record;

typedef struct {
    int key;
    long offset;
    double timestamp;
    char status;
    nested_record record;
} record;

enum Status { Active = 'A', Inactive = 'I', Expired = 'X' };

#define MAX_RECORDS 1024
#define PRECISION 6

void *xmalloc(size_t size) {
    void *ptr = malloc(size);
    if (!ptr && (size > 0)) {
        fprintf(stderr, "Out of memory.\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void xfree(void **ptr) {
    free(*ptr);
    *ptr = NULL;
}

record* allocateRecords(int num_records, int key_range) {
    if (num_records > MAX_RECORDS) {
        fprintf(stderr, "Too many records requested.\n");
        return NULL;
    }

    record *recs = xmalloc(sizeof(*recs)*num_records);
    int i, j, temp;
    srand((unsigned)time(NULL));  // Seed the random number generator

    for (i = 0; i < num_records; ++i) {
        recs[i].key = rand() % key_range;
        recs[i].offset = i * sizeof(record);
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);  // Get current time
        recs[i].timestamp = (double)ts.tv_sec + ((double)ts.tv_nsec / pow(10, PRECISION));

        if (recs[i].key % 3 == 0) {
            recs[i].status = Inactive;
        } else if (recs[i].key % 2 == 0) {
            recs[i].status = Expired;
        } else {
            recs[i].status = Active;
        }

        // Set nested record value to a random number within range of the key
        temp = rand() % (recs[i].key + 1);
        if (temp < recs[i].record.value) {  // Assumes there's only one nested record
            i--;
            continue;
        } else {
            recs[i].record.value = temp;
        }
    }

    return recs;
}

void deallocateRecords(record **recs) {
    if (recs != NULL && *recs != NULL) {
        xfree((void**)recs);
    }
}
```

