    }
}

// Add role to a user's profile
void addRoleToUser(char* id, char* name, char* description) {
    pthread_rwlock_rdlock(&profileLock); // Acquire read lock for concurrent access

    UserProfile *curr = userProfiles;
    while(curr != NULL){
        if(strcmp(curr->id, id) == 0){
            Role* newRole = (Role*)malloc(sizeof(Role));
            strcpy(newRole->name, name); // copy role details from external source
            strcpy(newRole->description, description); 
            pthread_mutex_lock(&curr->lock); // Lock for exclusive access to this user's profile
            newRole->next = curr->roles; // Add new role at the head of the list
            curr->roles = newRole;
            pthread_mutex_unlock(&curr->lock); 
            break;
        }
        curr = curr->next;
    }

    pthread_rwlock_unlock(&profileLock); // Release lock after modification is done
}

// Free memory function to call at the end of application or when no longer needed
