void renameFile(char *filename) {
    char newFilename[MAX_FILENAME] = "";
    int version = 1; // start with version 1
    int numCharsToSum = 0;

    for (int i=0; filename[i]; i++) {
        if ((filename[i] >= 'a' && filename[i] <= 'z') || (filename[i] >= 'A' && filename[i] <= 'Z')) { // check vowel
            char lowerCase = tolower(filename[i]);
            if (strchr("aeiou", lowerCase)) numCharsToSum++;
        } else if (isdigit((int)filename[i])) { // check numeric character
            numCharsToSum += filename[i] - '0';
        }
    }

    // copy the filename without .gz and append new extension
    strncpy(newFilename, filename, MAX_FILENAME-strlen(".gz")-4);
    strcat(newFilename, "v");
    char versionStr[10];
    sprintf(versionStr, "%d", version);
    strcat(newFilename, versionStr);
    if (strcmp(&filename[strlen(filename)-strlen(".gz")], ".gz")) { // check if it is a compressed file
        strcat(newFilename, ".log");
    } else { // replace the extension with .log
        newFilename[strlen(newFilename)-strlen(".gz")] = '\0'; 
        strcat(newFilename, ".log");
    }

    printf("Old filename: %s\n", filename);
    printf("New filename: %s\n", newFilename);
}

