RecordCollection* create_collection(size_t initial_capacity) {
    // Allocate and initialize a new collection
    RecordCollection *collection = malloc(sizeof(RecordCollection));
    if (collection == NULL) return NULL;

    pthread_mutex_init(&collection->mutex, NULL);

    collection->records = malloc(initial_capacity * sizeof(record*));
    if (collection->records == NULL) {
        free(collection);
        return NULL;
    }

    collection->size = 0;
    collection->capacity = initial_capacity;
    return collection;
}

void add_record(RecordCollection* collection, int key, long offset, int value) {
    // Add a new record to the collection
    pthread_mutex_lock(&collection->mutex);

    if (collection->size == collection->capacity) {
        // Resize the array when it's full
        size_t newCapacity = collection->capacity * 2;
        record** newRecords = realloc(collection->records, newCapacity * sizeof(record*));

        if (newRecords == NULL) {
            // Failed to allocate memory: handle error and return
            pthread_mutex_unlock(&collection->mutex);
            return;
        }

        collection->records = newRecords;
        collection->capacity = newCapacity;
    }

    // Allocate memory for the new record
    record* newRecord = malloc(sizeof(record));
    if (newRecord == NULL) {
        pthread_mutex_unlock(&collection->mutex);
        return;  // Failed to allocate memory: handle error and return
    }

    // Initialize the record
    newRecord->key = key;
    newRecord->offset = offset;
    newRecord->value = malloc(sizeof(int));
    if (newRecord->value == NULL) {
        free(newRecord);  // Failed to allocate memory: handle error and return
    } else {
        *(newRecord->value) = value;
    }

    collection->records[collection->size++] = newRecord;

    pthread_mutex_unlock(&collection->mutex);
}
