        if (keys[i] == key) {
            pthread_mutex_unlock(&lock);
            return -1;  // Duplicate key found, return error
        }
    }

    // Add the new key to the array
    keys[keysSize++] = key;

    pthread_mutex_unlock(&lock);
    return 0;  // Success
}

