#include <limits.h>
#include <stdbool.h>

typedef struct Record {
    long offset;
    int key;
    int value;
} Record;

Record* allocate_records(size_t numRecords, int minRange, int maxRange) {
    if (numRecords * sizeof(Record) > INT_MAX) {
        fprintf(stderr, "Memory allocation error: Total memory usage exceeds limit.\n");
        return NULL;
    }

    srand((unsigned int) time(NULL));

    Record* records = (Record*) malloc(numRecords * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Memory allocation error.\n");
        return NULL;
    }

    bool keys[INT_MAX] = {false}; // Using boolean array for tracking existing keys.
    for (size_t i = 0; i < numRecords; ++i) {
        int key, value;

        do {
            key = rand() % ((maxRange - minRange + 1)) + minRange;
        } while(keys[key]); // Retry if collision found.

        keys[key] = true; // Mark the key as used.

        value = rand() % (maxRange - minRange + 1) + minRange;
        records[i].offset = i;
        records[i].key = key;
        records[i].value = value;
    }

    return records;
}
``` 
This code initializes the seed for random number generation only once to ensure uniqueness of keys. The boolean array `keys[]` keeps track of existing keys, making collision checking efficient. Please note that this implementation assumes that the total memory usage is checked against a system-dependent maximum integer value (INT_MAX). Adjustments may be needed depending on your specific use case and platform.
