void modifyRecordsAndList(std::forward_list<std::string>& records, const std::string &target, const std::string &newValue, std::mt19937& rng) {
    bool found = false;
    for (auto itr = records.begin(); itr != records.end(); ++itr) {
        if (*itr == target) {
            records.insert_after(itr, newValue);
            found = true;
            break;
        }
    }
    if (!found) {
        records.push_front(newValue);
    }

    std::uniform_int_distribution<std::mt19937::result_type> dist(0,1<<24); // adjust this to fit your needs

    const size_t numRecords = std::distance(records.begin(), records.end());

    long* offsets = new (std::nothrow) long[numRecords];
    int* keys = new (std::nothrow) int[numRecords];
    record* rcrds = new (std::nothrow) record[numRecords];

    if(offsets && keys && rcrds){
        for(size_t i = 0; i < numRecords; ++i){
            offsets[i] = dist(rng);
            keys[i] = static_cast<int>(dist(rng));
            rcrds[i].value = static_cast<int>(dist(rng));
        }
    } else {
        delete[] offsets;
        delete[] keys;
        delete[] rcrds;

        // log error and take appropriate action (e.g., shut down system, retry operation)
    }

    delete[] offsets;
    delete[] keys;
    delete[] rcrds;
}
