```c
#include <stdlib.h>
#include <pthread.h>

typedef struct Record {
    long offset;
    int key;
    double value;
    char status;
} Record;

typedef struct Node {
    Record* record;
    struct Node* next;
    struct Node* prev;
} Node;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;  // For thread-safe operations
Node *head, *tail;  // Head and tail of doubly linked list
Node *insertionOrderHead, *insertionOrderTail;  // Head and tail of insertion order linked list

void* processRecords(Record** records) {
    int i = 0;
    while (records[i] != NULL && i < 500000) {
        Record* record = records[i];

        pthread_mutex_lock(&lock);  // Lock for thread-safe operations

        Node* newNode = malloc(sizeof(Node));
        if (newNode == NULL) {
            // handle memory allocation failure
            exit(1);
        }

        newNode->record = record;
        newNode->next = NULL;
        newNode->prev = tail;  // New node is added at the end of doubly linked list

        if (tail == NULL) {
            head = newNode;
        } else {
            tail->next = newNode;
        }

        tail = newNode;

        Node* insertionOrderNewNode = malloc(sizeof(Node));
        if (insertionOrderNewNode == NULL) {
            // handle memory allocation failure
            exit(1);
        }

        insertionOrderNewNode->record = record;
        insertionOrderNewNode->next = NULL;
        insertionOrderNewNode->prev = insertionOrderTail;  // New node is added at the end of insertion order linked list

        if (insertionOrderTail == NULL) {
            insertionOrderHead = insertionOrderNewNode;
        } else {
            insertionOrderTail->next = insertionOrderNewNode;
        }

        insertionOrderTail = insertionOrderNewNode;

        pthread_mutex_unlock(&lock);  // Unlock for thread-safe operations

        i++;
    }

    Node** result = malloc(2 * sizeof(Node*));  // Allocate memory for an array of two pointers
    if (result == NULL) {
        exit(1);
    }

    result[0] = head;
    result[1] = insertionOrderHead;

    return result;  // Return the heads of both linked lists
}
