```C
#include <stdlib.h>
#include <pthread.h>
#include <assert.h>

typedef struct {
    int value;
    int* key;
} record;

typedef struct Node{
    long offset;
    int key;
    record* data;
    struct Node *next;
    struct Node *prev;
} Node;

pthread_mutex_t memoryPoolLock = PTHREAD_MUTEX_INITIALIZER;
Node *head = NULL;
Node *tail = NULL;
size_t poolSize = 0;
size_t allocatedBlocks = 0;
void* memoryPool = NULL;

void *allocateBlock(size_t size) {
    pthread_mutex_lock(&memoryPoolLock);
    assert((poolSize + size) <= allocatedBlocks * sysconf(_SC_PAGESIZE)); // Ensure there's enough memory left in the pool

    void* block = memoryPool + poolSize; 
    poolSize += size;

    pthread_mutex_unlock(&memoryLock);
    return block;
}

void initializeMemoryPool(size_t initialSize) {
    assert(memoryPool == NULL && "Memory Pool is already initialized!"); // Ensure the memory pool hasn't been previously initialized

    allocatedBlocks = (initialSize / sysconf(_SC_PAGESIZE)) + 1; 
    memoryPool = malloc(allocatedBlocks * sysconf(_SC_PAGESIZE)); 
    assert(memoryPool != NULL && "Failed to allocate initial memory pool!"); // Check if allocation was successful
}

void insertNodeAtEnd(int key, record* data) {
    pthread_mutex_lock(&memoryPoolLock);

    Node *newNode = allocateBlock(sizeof(Node)); 
    newNode->key = key;
    newNode->data = data;
    if (head == NULL) { // If the list is empty, set head and tail to the new node.
        head = newNode;
        tail = newNode;
        newNode->next = newNode;
        newNode->prev = newNode;
    } else { // Otherwise, insert the new node at the end of the list.
        newNode->next = head;
        newNode->prev = tail;
        tail->next = newNode;
        head->prev = newNode;
        tail = newNode;
    }

    pthread_mutex_unlock(&memoryPoolLock);
}
```
This is a basic example of how you could implement the features you described. It initializes a circular linked list with nodes containing keys and records, as well as an allocator for managing memory. There's no support for variable-size blocks or external data storage system integration in this version because it would dramatically complicate the code. Also note that the insert operation at both ends doesn't currently handle memory reallocation when the pool is full; you could add that functionality if needed.
