#include <stdlib.h>
#include <pthread.h>
#include <assert.h>
#include <time.h>

typedef struct record {
    int value;
    long* key;
} record_t;

typedef struct memoryPoolNode {
    long offset;
    int key;
    record_t* record;
    struct memoryPoolNode *next, *prev;
} memoryPoolNode_t;

#define CACHE_SIZE 1024 /* Adjust this as needed */
static __thread memoryPoolNode_t** cache = NULL;
static __thread size_t cacheIndex = 0;

typedef struct {
    pthread_mutex_t lock;
    memoryPoolNode_t* head;
} memoryPool_t;

memoryPoolNode_t* newMemoryPoolNode(long offset, int key) {
    memoryPoolNode_t *node = (memoryPoolNode_t *)malloc(sizeof(memoryPoolNode_t));
    assert(node != NULL);

    node->offset = offset;
    node->key = key;
    node->record = malloc(sizeof(record_t));
    node->next = node->prev = node;

    return node;
}

void freeMemoryPoolNode(memoryPoolNode_t *node) {
    assert(node != NULL);

    free(node->record);
    free(node);
}

memoryPoolNode_t* addRecordToMemoryPool(memoryPool_t* pool, long offset, int key) {
    memoryPoolNode_t *node;
    pthread_mutex_lock(&pool->lock);

    node = newMemoryPoolNode(offset, key);
    if (cacheIndex < CACHE_SIZE) {
        cache[cacheIndex++] = &node;
    } else {
        freeMemoryPoolNode(*cache[rand() % CACHE_SIZE]);
        *cache[rand() % CACHE_SIZE] = node;
    }

    if (pool->head != NULL) {
        node->prev = pool->head->prev;
        node->next = pool->head;

        pool->head->prev->next = node;
        pool->head->prev = node;
    } else {
        pool->head = node;
    }

    pthread_mutex_unlock(&pool->lock);
    return node;
}

void initMemoryPool(memoryPool_t* pool) {
    assert(pool != NULL);
    srand((unsigned int)time(NULL));

    cache = malloc(sizeof(memoryPoolNode_t *) * CACHE_SIZE);
    pthread_mutex_init(&pool->lock, NULL);
    pool->head = NULL;
}

void destroyMemoryPool(memoryPool_t* pool) {
    assert(pool != NULL);

    memoryPoolNode_t *node = pool->head, *nextNode;
    if (node != NULL) do {
        nextNode = node->next;

        freeMemoryPoolNode(node);
        node = nextNode;
    } while (node != pool->head);

    pthread_mutex_destroy(&pool->lock);
    free(cache);
}
```
