#include <stdatomic.h>

// Prime checking function (not optimized)
int is_prime(int n) {
    if (n <= 1) return 0;
    for (int i = 2; i * i <= n; ++i)
        if (n % i == 0) return 0;
    return 1;
}

// Forward declaration
typedef struct Record Record;

// Define Record Structure
typedef struct Record {
    long* offset_ptr;
    int key;
    Record* prev;
    Record* next;
} Record;

// Add function to add new record into linked list
void add(Record** head, long* offset_ptr, int key) {
    // Create new node
    Record* newNode = malloc(sizeof(Record));
    newNode->offset_ptr = offset_ptr;
    newNode->key = key;
    newNode->prev = NULL;
    newNode->next = *head;

    // Change head pointer
    if ((*head) != NULL) (*head)->prev = newNode;
    *head = newNode;
}

// Add function to remove a node from linked list
void remove_node(Record** head, Record* del) {
    assert(*head); // Cannot delete from an empty list

    if (*head == del) *head = del->next; 
    if (del->next != NULL) del->next->prev = del->prev; 
    if (del->prev != NULL) del->prev->next = del->next; 

    free(del);  // Free memory
}

// Function to initialize and allocate memory for an array of unique long offsets
long* init_offset_array(_Atomic(int)* max_offset, int size) {
    srand(time(NULL));
    _Atomic(long)* offset_ptr = malloc(sizeof(long) * size);

    for (int i = 0; i < size; ++i) {
        long unique_value = rand() % atomic_load(max_offset);

        // Ensure uniqueness by looking through the array
        int j;
        for (j = 0; j < i; ++j) 
            if (atomic_load(&offset_ptr[j]) == unique_value) break;

        if (j == i) atomic_store(&offset_ptr[i], unique_value); // If value is unique, store it
        else --i; // Decrement i to try again with a new random number
    }

    return offset_ptr;
}

// Function to initialize and allocate memory for an array of prime keys
int* init_prime_key_array(int max_key, int size) {
    srand(time(NULL));
    int* key_ptr = malloc(sizeof(int) * size);

    for (int i = 0; i < size; ++i) {
        int unique_value = rand() % max_key + 1;

        // Ensure uniqueness by looking through the array and prime check
        if (is_prime(unique_value)) key_ptr[i] = unique_value; 
        else --i; // Decrement i to try again with a new random number
    }

    return key_ptr;
}
