["Here's a C example that handles most of these requirements. It uses POSIX threads for thread safety and re-entrant memory allocation functions (malloc/free) for efficiency. For simplicity, it uses random() function without setting up a seed to get repeatable results on different runs. 

```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct Record {
    int key;
    char* identifier;
    int value;
} Record;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

Record** createRecords(const char* identifiers[], size_t count, int minValue, int maxValue) {
    if (count == 0 || minValue > maxValue) return NULL;

    Record** records = malloc(sizeof(Record*) * count);
    if (!records) {
        // Log error - memory allocation failure
        return NULL; 
    }

    for (size_t i = 0; i < count; ++i) {
        records[i] = malloc(sizeof(Record));
        if (!records[i]) {
            // Log error - memory allocation failure, need to free already allocated memory
            for (; i >= 0; --i) free(records[i]);
            free(records);
            return NULL; 
        }

        records[i]->identifier = malloc(strlen(identifiers[i]) + 1);
        if (!records[i]->identifier) {
            // Log error - memory allocation failure, need to free already allocated memory
            free(records[i]); 
            for (--i; i >= 0; --i) free(records[i]);
            free(records);
            return NULL; 
        }

        strcpy(records[i]->identifier, identifiers[i]); // Assume strlen() + 1 doesn't exceed INT_MAX

        pthread_mutex_lock(&lock);  // Ensure thread safety
        records[i]->key = i;  
        records[i]->value = (rand() % (maxValue - minValue + 1)) + minValue;
        pthread_mutex_unlock(&lock);
    }

    return records;
}
```
