['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Record structure
typedef struct record {
    int value;
    struct record *next_circular;
    struct record *next_ordered;
} record;

// List structure
typedef struct list {
    record *head;
    record *tail;
    pthread_mutex_t mutex; // for thread safety
} list;

// Initialize a new list
void initialize(list* l) {
    l->head = NULL;
    l->tail = NULL;
    pthread_mutex_init(&l->mutex, NULL);
}

// Add record to circular linked list
record* add_circular(list* l, int value) {
    pthread_mutex_lock(&l->mutex); // critical section start

    record *new = malloc(sizeof(record));
    new->value = value;

    if (l->head == NULL) {
        l->head = new;
        l->tail = new;
        new->next_circular = new;
    } else {
        new->next_circular = l->head;
        l->tail->next_circular = new;
        l->tail = new;
    }

    pthread_mutex_unlock(&l->mutex); // critical section end

    return new;
}

// Add record to ordered linked list
record* add_ordered(list* l, int value) {
    pthread_mutex_lock(&l->mutex); // critical section start

    record *new = malloc(sizeof(record));
    new->value = value;

    if (l->head == NULL || l->tail->value < value) {
        new->next_ordered = NULL;
        if (l->head != NULL) l->tail->next_ordered = new;
        l->tail = new;
    } else {
        record *current = l->head;
        while(current->next_ordered != NULL && current->next_ordered->value < value) {
            current = current->next_ordered;
        }
        new->next_ordered = current->next_ordered;
        current->next_ordered = new;
    }

    pthread_mutex_unlock(&l->mutex); // critical section end

    return new;
}
