// Define the record structure
struct Record {
    char* identifier;
    struct tm timestamp;
    int messageLevel;
};

// Define a hash map for indexing
std::unordered_map<std::string, Record*> indexMap;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; 

int MAX_IDENTIFIER_LEN = 256; // default maximum length for identifiers
int MAX_MESSAGE_LENGTH = 1024; // default maximum message length

// Error codes
#define ALLOCATION_FAILURE -1
#define OUT_OF_MEMORY -2

// Function to allocate memory and initialize records
Record* createRecords(const char** identifierList, const struct tm* timestampList, 
                      const int* messageLevels, int size) {
    Record *records = (Record*)calloc(sizeof(Record), size);
    if (!records) {
        return NULL;
    }

    for (int i = 0; i < size; ++i) {
        // Allocate memory and initialize each record
        records[i].identifier = strndup(identifierList[i], MAX_IDENTIFIER_LEN);
        if (!records[i].identifier) {
            for (int j = 0; j < i; ++j) {
                free(records[j].identifier);
            }
            return NULL;
        }

        records[i].timestamp = timestampList[i];
        records[i].messageLevel = messageLevels[i];

        // Build the secondary index
        std::string idStr = identifierList[i];
        if (indexMap.find(idStr) == indexMap.end()) {
            indexMap[idStr] = &records[i];
        }
    }

    return records;
}

// Function to free allocated memory
void deleteRecords(Record* records, int size) {
    for (int i = 0; i < size; ++i) {
        std::string idStr = records[i].identifier;

        indexMap.erase(idStr); // remove record from the secondary index
        free(records[i].identifier);
    }

    free(records);
}
```

In this code, the `createRecords` function allocates memory for each record and initializes it with given identifiers, timestamps, and message levels. It also builds a secondary index (implemented as an unordered_map) to enable efficient lookups by identifier. If allocation fails, the function frees all previously allocated records before returning NULL.

The `deleteRecords` function iterates over each record, erases it from the secondary index, and then frees its memory. After that, it also releases the array of records itself.
