    pthread_mutex_lock(&pool->lock);
    size_t numLists = 1 + (pool->lists ? pool->numChildren : 0);
    pool->lists = realloc(pool->lists, sizeof(LinkedList*) * numLists);
    pool->lists[numLists - 1] = initLinkedList();
    pthread_mutex_unlock(&pool->lock);
}

void addNodeToMemPool(MemPool* pool, char* condition) {
    TreeNode *newNode = createTreeNode(condition);
    if (strcmp(pool->root->condition, "Root") == 0 && strlen(condition) != 0) {
        free(pool->root->condition);
        pool->root->condition = newNode->condition;
    } else {
        size_t numNodes = 1 + (pool->root->children ? pool->numChildren : 0);
        pool->root->children = realloc(pool->root->children, sizeof(TreeNode*) * numNodes);
        pool->root->children[numNodes - 1] = newNode;
    }
}

void addDataToMemPool(MemPool* pool) {
    srand((unsigned int)time(NULL));
    double data = (double) rand()/RAND_MAX;

    pthread_mutex_lock(&pool->lists[0]->lock);
    Node *node = allocate(sizeof(Node));
    node->data = data;
    if (!pool->lists[0]->head) {
        pool->lists[0]->head = node;
    } else {
        Node* current_node = pool->lists[0]->head;
        while (current_node->next != NULL) {
            current_node = current_node->next;
        }
        current_node->next = node;
    }
    pthread_mutex_unlock(&pool->lists[0]->lock);
