['Sure, here's an outline C code snippet that implements a custom memory pool allocator using pthread library for thread-safe operations and logging with the help of printf statement:

```c
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#define POOL_SIZE 10000000 // Assuming each record takes up 4KB

typedef struct Record {
    long offset;
    int key;
    struct Record* next, *prev;
    struct {
        int value;
        int* pKey;
        long indices[2];
    } data;
} Record;

Record* memoryPool = NULL;  // Memory pool to hold records
int remainingRecords = POOL_SIZE;   // Remaining slots in the pool
pthread_mutex_t mutex; // Mutex for thread-safe operations

// Dynamically allocates memory for and initializes an arbitrary number of records.
Record* createRecords(int num, int range) {
    srand(time(0)); 
    pthread_mutex_lock(&mutex);   // Locking mutex to ensure thread-safety

    Record* head = NULL;
    Record* tail = NULL;

    for (int i = 0; i < num && remainingRecords > 0; ++i, --remainingRecords) { 
        if(memoryPool == NULL){   // If memory pool is not allocated
            memoryPool = malloc(POOL_SIZE * sizeof(Record));
            head = &memoryPool[0];
            tail = &memoryPool[POOL_SIZE -1];
        }

        Record* newRecord = memoryPool++;  // Allocate from the pool
        newRecord->offset = i;   // Set offset value
        newRecord->key = rand() % range + 1;    // Set key value to a random value within specified range
        newRecord->data.value = rand() % range + 1;  // Set int field of data structure to a random value
        newRecord->data.pKey = &newRecord->key;   // Pointer to corresponding key

        if(head == NULL) {  // If first record, make it head and tail
            head = newRecord;
            tail = newRecord;
        } else {    // If not, append the new record at the end
            tail->next = newRecord;
            newRecord->prev = tail;
            tail = newRecord; 
        }

        // Make it circular by linking head and tail of list
        tail->next = head;  
        head->prev = tail;
    }

    pthread_mutex_unlock(&mutex);  // Unlocking mutex after critical section
    printf("Memory Usage: %luKB, Remaining Records: %d\n", (memoryPool - &memoryPool[0]) * sizeof(Record), remainingRecords);

    return head;   // Return the head of circular doubly linked list.
}
```

This code does not include logging memory usage or resizing the memory pool dynamically as those would require further implementation and are complex operations requiring careful consideration of potential concurrency issues etc., hence aren't included here for simplicity. Please make sure to handle these in a production scenario. 

Note: This is a simple example and does not cover all edge cases or real-world scenarios that might occur, but it should be a good starting point for further development. Always remember to test your code thoroughly under load conditions and consider additional error checking and handling measures as needed.
