from kafka import KafkaProducer, KafkaConsumer

class DataProcessor(Process):
    def __init__(self, config, consumer_lock):
        super().__init__()
        self.config = config
        self.consumer_lock = consumer_lock
        self.producer = KafkaProducer(bootstrap_servers=config['kafka']['broker'])
        self.redis_client = Redis(host=config['redis']['host'], port=config['redis']['port'])
        self.consumer = KafkaConsumer(self.config['topic'], group_id='data-processor', bootstrap_servers=[self.config['kafka']['broker']])

    def run(self):
        for message in self.consumer:
            with self.consumer_lock:
                if not self.is_paused():
                    data = self.transform(message)
                    self.producer.send(self.config['output'], value=data)

    def transform(self, message):
        # Implement the transformation logic here
        return message

    def is_paused(self):
        if int(self.redis_client.get('pause')) == 1:
            return True
        else:
            return False

class DataProducer(Thread):
    def __init__(self, config):
        super().__init__()
        self.config = config
        self.producer = KafkaProducer(bootstrap_servers=[config['kafka']['broker']])

    def run(self):
        for i in range(1000):
            message = f'Message number {i}'
            self.producer.send(self.config['topic'], value=message)
            time.sleep(0.5)

class ConsumerManager:
    def __init__(self, config):
        self.config = config
        self.consumer_lock = Lock()

    def pause_consumers(self):
        Redis(host=self.config['redis']['host'], port=self.config['redis']['port']).set('pause', 1)

    def resume_consumers(self):
        Redis(host=self.config['redis']['host'], port=self.config['redis']['port']).set('pause', 0)

    def scale(self, instances):
        self.pause_consumers()

        for i in range(instances):
            DataProcessor(self.config, self.consumer_lock).start()
```

