#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char *data;
    size_t used;
    size_t size;
} MemoryPool;

void init(MemoryPool *pool, size_t initialSize) {
    pool->used = 0;
    pool->size = initialSize;
    pool->data = malloc(initialSize);
}

void append(MemoryPool *pool, void *data, size_t dataSize) {
    if (pool->used + dataSize >= pool->size) {
        pool->size *= 2;
        pool->data = realloc(pool->data, pool->size);
    }
    memcpy(pool->data + pool->used, data, dataSize);
    pool->used += dataSize;
}

void freePool(MemoryPool *pool) {
    free(pool->data);
    pool->data = NULL;
    pool->used = pool->size = 0;
}

