    int max;
    int min;
    struct trackNode *next;
} trackNode;

void *manageMemory(memLib memManager, long* offset, int* keys, 
                    recordNode **headRecord, trackNode **headTrack, 
                    unsigned int size, long seed, int range) {

    // Allocate memory for arrays
    offset = memManager.alloc(sizeof(long)*size);
    keys = memManager.alloc(sizeof(int)*size);

    // Initialize the 'offset' and 'key' arrays with values generated from a provided seed for reproducibility
    srand(seed);
    for (unsigned int i = 0; i < size; ++i) {
        offset[i] = rand();
        keys[i] = rand() % range;
    }

    // Allocate memory and initialize record array with random integer values within a specified range.
    *headRecord = memManager.alloc(sizeof(recordNode)*size);
    for (unsigned int i = 0; i < size; ++i) {
        (*headRecord)[i].value = rand() % range;
        (*headRecord)[i].key = &keys[i];
    }

    // Create a circular doubly linked list of record structures.
    for (unsigned int i = 0; i < size; ++i) {
        if(i==0){
            (*headRecord)[i].prev = &(*headRecord)[size-1];
        }else{
            (*headRecord)[i].prev = &(*headRecord)[i-1];
        }

        if(i == size - 1){
            (*headRecord)[i].next = &(*headRecord)[0];
        }else{
            (*headRecord)[i].next = &(*headRecord)[i+1];
        }
    }

    // Create a singly linked list to track max and min int values.
    *headTrack = memManager.alloc(sizeof(trackNode));
    (*headTrack)->max = INT_MIN;
    (*headTrack)->min = INT_MAX;
    for (unsigned int i = 0; i < size; ++i) {
        if((*headRecord)[i].value > (*headTrack)->max){
            (*headTrack)->max = (*headRecord)[i].value;
        }

        if((*headRecord)[i].value < (*headTrack)->min){
            (*headTrack)->min = (*headRecord)[i].value;
        }
    }

    return *headRecord;
}
```
