int run_command_in_background(char* cmd) {
    pid_t childPid = fork();

    if (childPid == -1) {
        log_error("Failed to fork: %s", strerror(errno));
        return 0;
    } else if (childPid == 0) { // Child process
        char *argv[] = {"sh", "-c", cmd, NULL};

        setpgid(getpid(), getpid());
        signal(SIGCHLD, SIG_DFL);  // Restore default handler
        execvp("sh", argv);

        log_error("Failed to run command: %s", strerror(errno));
        return 0;
    } else { // Parent process
        signal(SIGCHLD, sigchld_handler);  // Handle SIGCHLD in parent
        setpgid(childPid, childPid);  // Create a new session and process group

        log_info("Running command: %s", cmd);
    }

    return 1;
}
