```c
#include <pthread.h>
#include <stdlib.h>

typedef struct {
    char* key;
    int value;
} Metadata;

typedef enum { 
    STATUS_OK,
    STATUS_ERROR
} StatusType;

typedef struct {
    double value;
    StatusType status;
    Metadata metadata;
} CacheObject;

// Simplified memory pool allocator with thread safety.
#define MAX_OBJECTS 10000
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static CacheObject* cache[MAX_OBJECTS];

void* memory_pool_alloc(size_t size) {
    void* block;

    // Lock to ensure thread safety.
    pthread_mutex_lock(&mutex);

    for (int i = 0; i < MAX_OBJECTS; ++i) {
        if (cache[i] == NULL) {
            cache[i] = malloc(sizeof(CacheObject));

            // Unlock before returning to improve performance.
            pthread_mutex_unlock(&mutex);
            return cache[i];
        }
    }

    // Unlock if no free slot found.
    pthread_mutex_unlock(&mutex);
    return NULL;
}

void memory_pool_free(void* block) {
    pthread_mutex_lock(&mutex);

    for (int i = 0; i < MAX_OBJECTS; ++i) {
        if (cache[i] == block) {
            free(block);
            cache[i] = NULL;
            break;
        }
    }

    pthread_mutex_unlock(&mutex);
}
```
