use std::sync::Arc;
use std::thread;
use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::RwLock;
use rand::Rng;
use tokio::runtime::Handle;

struct Node {
    value: usize,
    next: Option<Arc<Node>>,
    prev: Option<Arc<Node>>,
}

pub struct List {
    head: Option<Arc<Node>>,
    tail: Option<Arc<Node>>,
    len: AtomicUsize,
}

impl List {
    pub fn new() -> Self {
        List { head: None, tail: None, len: AtomicUsize::new(0) }
    }

    // add a method to push values to list, here's an example:
    pub fn push(&self, val: usize) {
        let node = Node { value: val, next: None, prev: self.tail };
        match &mut self.head {
            Some(ref mut head_node) => {
                (*head_node).prev = Some(Arc::new(node));
            }
            None => {
                self.tail = Some(Arc::new(node));
            }
        }
        self.len.fetch_add(1, Ordering::Relaxed);
    }
}
```
