// Function to add a user profile
void addUser(int id, char username[], char email[], char password[]) {
    pthread_mutex_lock(&lock);

    // Add to the linked list 
    Node* newNode = (Node*)malloc(sizeof(Node));
    UserProfile profile = {id, username, email, password};
    newNode->profile = profile;
    newNode->next = head;
    if(head != NULL)
        head->prev = newNode; 
    head = newNode; 

    pthread_mutex_unlock(&lock);
}

// Function to remove a user profile by username
void deleteUserByUsername(char username[]) {
    pthread_mutex_lock(&lock);

    // Remove from the linked list
    Node* temp = head; 
    while (temp != NULL && strcmp(temp->profile.username, username)) 
        temp = temp->next;

    if (temp == NULL) return; 

    if(temp->prev != NULL) 
        temp->prev->next = temp->next; 

    if(temp->next != NULL) 
        temp->next->prev = temp->prev; 

    free(temp);

    pthread_mutex_unlock(&lock);
}

// Function to retrieve user profile by username
UserProfile getUserByUsername(char username[]){
    pthread_mutex_lock(&lock);

    // Retrieve from the linked list 
    Node* temp = head; 
    while (temp != NULL && strcmp(temp->profile.username, username)) 
        temp = temp->next;

    if (temp == NULL){
        UserProfile empty = {0};
        return empty; 
    } 

    pthread_mutex_unlock(&lock);
    return temp->profile;
}
