#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <math.h>
#define MEM_POOL_SIZE 100000000 // ~1 billion nodes

typedef struct Node {
    long timestamp;
    float value;
    struct Node* next;
} Node;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
Node *pool, *head;

// Initial memory pool allocation.
void initializeMemoryPool() {
    head = NULL;
    pool = (Node*) malloc(sizeof(Node) * MEM_POOL_SIZE);
}

// Get node from the memory pool
Node* getNewNode() {
    pthread_mutex_lock(&lock);
    Node* n = head;
    if (n != NULL) 
        head = n->next;

    pthread_mutex_unlock(&lock);
    return n;
}

// Return node to the memory pool
void releaseNode(Node *node) {
    if (node == NULL) return;

    pthread_mutex_lock(&lock);
    node->next = head;
    head = node;
    pthread_mutex_unlock(&lock);
}

// Create an array with timestamps ranging from start to end at interval. 
Node* createArray(long start, long end, float minVal, float maxVal, int interval) {
    Node *array = NULL;

    if (end < start || interval <= 0) return NULL;

    srand((unsigned int)time(NULL));
    for (long i=start; i<=end; i+=interval) {
        Node* node = getNewNode();

        if (node == NULL){
            fprintf(stderr, "Memory allocation failed.\n"); 
            return array;
        }

        node->timestamp = i;
        node->value = ((float)rand()/(float)(RAND_MAX)) * (maxVal - minVal) + minVal;
        node->next = array;
        array = node;
    }

    return array;
}

// Clean up all allocated memory
void cleanupArray(Node* array) {
    while (array != NULL) {
        Node *tmp = array;
        array = array->next;
        releaseNode(tmp);
    }

    free(pool);
}
