    srand((unsigned int)time(NULL));

    StructObject *array = (StructObject *)malloc(sizeof(StructObject) * size);
    if (!array) {
        perror("Memory allocation failed for array");
        return NULL;
    }

    double range = maxVal - minVal;

    for (size_t i = 0; i < size; ++i) {
        double randValue = ((double)rand() / RAND_MAX) * range + minVal;

        array[i].value = randValue;

        const char* randomMsg = messages[rand() % (sizeof(messages)/sizeof(char*))]; 
        array[i].msg = strdup(randomMsg); // Allocate memory for the message string.

        if (!array[i].msg) {
            perror("Memory allocation failed for message");

            // Clean up previously allocated memory.
            for (size_t j = 0; j < i; ++j)
                free(array[j].msg); 

            free(array);

            return NULL; 
        }
    }

    return array;
}
