// Define a memory pool for efficient use of the system's resources.
typedef struct memory_pool {
    void* start;
    size_t size;
    pthread_mutex_t lock; // To ensure thread-safe operations.
} MemoryPool;

MemoryPool initMemoryPool(size_t initialSize) {
    MemoryPool pool = { .start = malloc(initialSize), .size = initialSize };
    pthread_mutex_init(&pool.lock, NULL);
    return pool;
}

// Allocate from the pool a block of memory and ensure thread-safety.
void* allocFromPool(MemoryPool *pool, size_t blockSize) {
    void* block = NULL;
    pthread_mutex_lock(&pool->lock); // Ensure exclusive access

    if (pool->size < blockSize){ 
        pool->start = realloc(pool->start, pool->size + blockSize);
        pool->size += blockSize;
    }

    block = pool->start; // Allocate from the beginning of the pool
    pool->start += blockSize; 
    pthread_mutex_unlock(&pool->lock); 

    return block;
}

// Function to create and initialize the database index.
Record* initIndex(MemoryPool *pool, size_t recordCount) {
    Record* head = NULL, *tail = NULL;
    for (size_t i = 0; i < recordCount; ++i){
        // Allocate memory for a new entry and add it to the linked list.
        Record* newRecord = allocFromPool(pool, sizeof(Record)); 

        newRecord->key = rand() % INT_MAX; // Generate a unique key - adjust based on your requirements.
        // More initialization...

        if (i == 0){
            head = tail = newRecord;
            head->prev = head->next = tail;
            tail->prev = tail->next = head;
        } else {
            newRecord->prev = tail;
            newRecord->next = head;

            head->prev = newRecord;
            tail->next = newRecord;

