#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int key;
    int value;
    struct Node* prev;
    struct Node* next;
} Node;

Node* createNode(int key, int val) {
    Node* newNode = (Node*)malloc(sizeof(Node));

    if (!newNode) {
        printf("Memory allocation failed");
        exit(0);
    }

    newNode->key = key;
    newNode->value = val;
    newNode->prev = NULL;
    newNode->next = NULL;

    return newNode;
}

void insertNodeAtEnd(Node** head, int key, int val) {
    Node* newNode = createNode(key, val);

    if (*head == NULL) {
        newNode->prev = newNode;
        newNode->next = newNode;
        *head = newNode;
    } else {
        Node* last = (*head)->prev;

        newNode->prev = last;
        newNode->next = *head;

        (*head)->prev = newNode;
        last->next = newNode;
    }
}

void generateRandomValues(Node** head, int numRecords, int minVal, int maxVal) {
    for (int i = 0; i < numRecords; ++i) {
        int key = i + 1;
        int value = minVal + rand() % ((maxVal + 1) - minVal);

        insertNodeAtEnd(head, key, value);
    }
}
