    node->record = record;
    node->timestamp = time(NULL);
    pthread_mutex_lock(&cacheLock);
    if (currentCacheSize == maxCacheSize) {
        CacheNode *oldestNode = cacheHead;
        cacheHead = oldestNode->next;
        free(oldestNode->record);
        free(oldestNode);
        currentCacheSize--;
    }
    if (cacheTail != NULL) {
        node->prev = cacheTail;
        cacheTail->next = node;
    } else {
        cacheHead = node;
    }
    cacheTail = node;
    currentCacheSize++;
    pthread_mutex_unlock(&cacheLock);
}

Record* getRecord(int key) {
    Record *record = getFromCache(key);
    if (record == NULL) {
        record = loadRecordFromFile(key); // Assuming this function exists to load from file
        insertIntoCache(record);
    }
    return record;
}
