size_t size = 0;

int hash(char* str) {
    // Simple hash function for demonstration purposes, replace with a better one in production
    int hash = 5381;
    char c;
    while ((c = *str++)) {
        hash = ((hash << 5) + hash) + c; 
    }
    return abs(hash);
}

record_t* record_create(char* buffer, double value) {
    size_t len = strlen(buffer);

    // Handle empty strings and duplicates by using hashed values
    if (len == 0 || (records != NULL && records[hash(buffer)] != NULL)) return NULL;

    record_t* newRecord = malloc(sizeof(record_t));
    if (!newRecord) return NULL;

    newRecord->key = hash(buffer);
    newRecord->value = value;
    newRecord->buffer = malloc(len + 1);
    if (!newRecord->buffer) {
        free(newRecord);
        return NULL;
    }

    strcpy(newRecord->buffer, buffer);
    srand(time(0));
    newRecord->value = ((double) rand() / (RAND_MAX)) * value;  // Random number between 0 and given value

    return newRecord;
}

void record_update(int key, double value) {
    for (size_t i = 0; i < size; ++i) {
        if (records[i]->key == key) {
            records[i]->value = value;
            break;
        }
    }
}

void record_delete(int key) {
    for (size_t i = 0; i < size; ++i) {
        if (records[i]->key == key) {
            free(records[i]->buffer);
            free(records[i]);

            // Compact the array to keep all records contiguous and without holes
            memmove(&records[i], &records[i + 1], (size - i - 1) * sizeof(record_t*));
            --size;

            break;
        }
    }
}
```
This code assumes you'd call `record_create` with a string and max value for generating the records, and then use `record_update` to update values or `record_delete` to delete records. You may need to add error handling for these functions as well.
