    FILE* fp = fopen(filename, "rb");
    if (!fp) {
        printf("Error opening file\n");
        return NULL;
    }

    fseek(fp, 0L, SEEK_END);
    long size = ftell(fp);
    rewind(fp);

    char* buffer = malloc(size + 1);
    if (!buffer) {
        printf("Memory error\n");
        return NULL;
    }

    fread(buffer, 1, size, fp);
    buffer[size] = 0;
    fclose(fp);

