['Here is a basic implementation in C:

```c
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <assert.h>

typedef struct record {
    int value;
    char* str;
    long* offset;
} Record;

void populate_record(Record* r, int val, const char* str, long off) {
    r->value = val;

    size_t len = strlen(str);
    if (!(r->str = (char*)malloc((len + 1)*sizeof(char)))) {
        assert("Failed to allocate memory for string.");
    }

    strncpy(r->str, str, len+1); // Copy the null terminator as well
    r->offset = (long*)malloc(sizeof(long));
    if(!r->offset) {
        free(r->str);
        assert("Failed to allocate memory for offset.");
    }

    *r->offset = off;
}

void* initialize_records(int num, int minVal, int maxVal, const char** strs) {
    srand(time(0));

    long* offsets = (long*)calloc(num, sizeof(long));
    if(!offsets){
        assert("Failed to allocate memory for offset array.");
    }

    int* keys = (int*)malloc(num * sizeof(int));
    if(!keys) {
        free(offsets);
        assert("Failed to allocate memory for key array.");
    }

    Record** records = (Record**)calloc(num, sizeof(Record*));
    if (!records){
        free(offsets);
        free(keys);
        assert("Failed to allocate memory for record array.");
    }

    for (int i = 0; i < num; ++i) {
        keys[i] = rand() % (maxVal - minVal + 1) + minVal;

        // Assuming the string lengths do not exceed LONG_MAX. 
        offsets[i] = strlen(strs[i]);

