['Here's a simplified example to illustrate how this might be implemented in C using pthread for thread safety, mutexes for concurrent access, and linked lists for efficient record storage:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct Record {
    int key;
    long offset;
    struct Record *next;
} Record;

Record* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
FILE *logFile;

void insertRecord(int key, long offset) {
    if (key < 0 || offset < 0) {
        fprintf(logFile, "Invalid record parameters: %d, %ld\n", key, offset);
        return;
    }

    Record *new_node = malloc(sizeof(Record));
    if (!new_node) {
        fprintf(logFile, "Memory allocation failed.\n");
        return;
    }

    new_node->key = key;
    new_node->offset = offset;
    new_node->next = NULL;

    pthread_mutex_lock(&lock);

    if (head == NULL) {
        head = new_node;
    } else {
        Record *current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }

    pthread_mutex_unlock(&lock);
}

Record* getRecord(int key) {
    if (key < 0) {
        fprintf(logFile, "Invalid key: %d\n", key);
        return NULL;
    }

    pthread_mutex_lock(&lock);

    Record *current = head;
    while (current != NULL && current->key != key) {
        current = current->next;
    }

    pthread_mutex_unlock(&lock);
    return current;
}

void deleteRecord(int key) {
    if (key < 0) {
        fprintf(logFile, "Invalid key: %d\n", key);
        return;
    }

    pthread_mutex_lock(&lock);

    Record *current = head;
    Record *prev = NULL;
    while (current != NULL && current->key != key) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        fprintf(logFile, "Record with key %d not found.\n", key);
    } else {
        if (prev != NULL) {
            prev->next = current->next;
        } else {
            head = current->next;
        }
        free(current);
    }

    pthread_mutex_unlock(&lock);
}
```
Please note that this is a simplified solution and does not include the bulk insertion or retrieval, logging mechanism configuration, out of memory management for linked list, etc. For each of these features, it would be better to implement them separately as separate functions with appropriate error handling and concurrency control mechanisms. Also, keep in mind that you'll need a cleanup function to release the resources when done.
