#include <stdlib.h>
#include <time.h>

typedef struct Record {
    int value;
    long *key_ptr;
    struct Record *prev;
    struct Record *next;
} Record;

Record* create_record(long keys[], int num_keys, int min_value, int max_value) {
    srand((unsigned int)time(NULL));

    // Allocate memory for the record structure.
    Record *record = malloc(sizeof(Record));
    if (record == NULL) {
        // Handle allocation failure.
        return NULL;
    }

    // Assign a random value to the record within specified range.
    record->value = rand() % (max_value - min_value + 1) + min_value;

    // Pick a random key from keys array and assign its pointer to the record's key_ptr.
    int index = rand() % num_keys;
    record->key_ptr = &keys[index];

    return record;
}

// Function to create linked list of records with given number of elements.
Record* create_linked_list(long keys[], int num_keys, int min_value, int max_value, int num_records) {
    Record *head = NULL;
    Record *prev = NULL;

    for (int i = 0; i < num_records; ++i) {
        Record *record = create_record(keys, num_keys, min_value, max_value);

        // Link the current record to the previous one.
        if (prev != NULL) {
            prev->next = record;
            record->prev = prev;
        } else {
            head = record;  // This is the first element, so it's also the head of the list.
        }

        // The last record points to the first one (circular linked list).
        if(i == num_records - 1) {
            record->next = head;
            head->prev = record;
        }

        prev = record;
    }

    return head;
}
```
This program creates a circular doubly linked list of records. Each record contains an integer value and a pointer to a long key from an array of keys. This is a very basic implementation, in real-world scenarios you would need to handle thread safety, memory management optimizations, logging, error handling, cleaning up the list etc. which are omitted for brevity in this example.
