record** initialize_data_structures(int num_offsets, int num_keys, int num_records, long min, long max) {

    if (num_offsets == 0 && num_keys == 0 && num_records == 0) {
        return NULL;
    }

    // Allocate memory for the offsets and keys arrays
    long* offsets = malloc(sizeof(long) * num_offsets);
    int* keys = malloc(sizeof(int) * num_keys);
    record** records = malloc(sizeof(record*) * num_records);

    if (offsets == NULL || keys == NULL || records == NULL) {
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    // Initialize offsets and keys arrays with random values
    srand(time(NULL));
    for (int i = 0; i < num_offsets; ++i) {
        offsets[i] = i;
    }
    for (int i = 0; i < num_keys; ++i) {
        keys[i] = rand();
    }

    // Initialize records array with random values and corresponding pointers to the offsets array
    long checksum = 0;
    for (int i = 0; i < num_records; ++i) {
        record* new_record = malloc(sizeof(record));
        if (new_record == NULL) {
            free(offsets);
            free(keys);
            // Free all previously allocated records
            for (int j = 0; j < i; ++j) {
                free(records[j]);
            }
            free(records);
            return NULL;
        }
        new_record->value = rand() % (max - min + 1) + min;
        new_record->offset_ptr = &offsets[rand() % num_offsets];
        records[i] = new_record;

        checksum += new_record->value;
    }

    // Verify the checksum
    long recomputed_checksum = 0;
    for (int i = 0; i < num_records; ++i) {
        recomputed_checksum += records[i]->value;
    }

    if (recomputed_checksum != checksum) {
        free(offsets);
        free(keys);
        for (int i = 0; i < num_records; ++i) {
            free(records[i]);
        }
        free(records);
        return NULL;
    }

    // Return the initialized arrays
    return records;
}
