// Custom random number generator to ensure uniform distribution
int rand_range(int min, int max) {
    return min + (rand() % (max - min + 1));
}

void high_performance_computing(long num_offsets, long num_keys, long num_records, long num_alternate_records, 
                                int min_key, int max_key, int min_value, int max_value, 
                                long window_size, double initial_avg) {

    if(num_offsets <= 0 || num_keys <= 0 || num_records <= 0 || num_alternate_records <= 0 || 
       min_key < 0 || max_key < 0 || min_value < 0 || max_value < 0 || window_size <= 0) {
        printf("Error: All parameters must be positive integers!\n");
        return;
    }

    if(window_size > num_offsets){
        printf("Error: Window size cannot exceed number of offsets!\n");
        return;
    } 

    long* offsets = (long*) malloc(num_offsets * sizeof(long));
    int* keys = (int*) malloc(num_keys * sizeof(int));

    Record* records = (Record*) malloc(num_records * sizeof(Record));
    for(int i = 0; i < num_records; ++i){
        records[i].value = rand_range(min_value, max_value); 
    }

    Record* alternate_records = (Record*) malloc(num_alternate_records * sizeof(Record));
    double average = initial_avg;

    for(int i = 0; i < num_offsets - window_size + 1; ++i) {
        double sum = 0.0;
        for(int j = 0; j < window_size; ++j) {
            sum += offsets[i+j]; 
        }
        average = (average * (window_size - 1) + offsets[i + window_size - 1]) / window_size;

        for(int j = 0; j < num_alternate_records; ++j){
            alternate_records[j].value = average; // Use calculated rolling average.
        }
    }

    free(offsets);
    free(keys);
    free(records);
    free(alternate_records);
}
```
