        fprintf(stderr, "Invalid input: non-negative integers expected.\n");
        free(result);
        result = NULL;
        result->statusCode = -1;
        return result;
    }

    int *data = malloc(count * sizeof(int));
    if (data == NULL) {
        fprintf(stderr, "Memory allocation failure.\n");
        free(result);
        result = NULL;
        result->statusCode = -1;
        return result;
    }

    for (int i = 0; i < count; ++i) {
        if (scanf("%d", &data[i]) != 1 || data[i] < 0) {
            fprintf(stderr, "Invalid input: non-negative integers expected.\n");
            free(result);
            result = NULL;
            result->statusCode = -1;
            return result;
        }
    }

    result->data = data;
    result->statusCode = 0;  // success
    return result;
}
```
This code reads an integer count from the standard input and then allocates memory for an array of that size. It validates each integer read to ensure it's non-negative, and returns a status code indicating failure if any invalid input is encountered or memory allocation fails. The allocated data structure can be freed using `free()` when no longer needed.
