['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct Node {
    int value;
    char* string_ref;
    struct Node *left, *right, *parent;  // Pointers to left child, right child and parent node
} Node;

// Create a new node with a random value in the given range
Node* createNode(int minValue, int maxValue) {
    Node* new_node = (Node*) malloc(sizeof(Node));

    if(!new_node){
        printf("Memory allocation failed. Exiting...\n");
        exit(-1);
    }

    srand((unsigned)time(NULL) * rand());
    new_node->value = (rand() % (maxValue - minValue + 1)) + minValue;  // Random value in the given range

    // Allocate memory for string reference. It can be a random length of characters between 1 and 20.
    int strLen = rand() % 20 + 1;
    new_node->string_ref = (char*) malloc(sizeof(char) * (strLen + 1)); // +1 for null character

    if(!new_node->string_ref){
        printf("Memory allocation failed. Exiting...\n");
        exit(-1);
    }

    // Generate random string of characters and assign it to string reference
    for (int i = 0; i < strLen; i++) {
        new_node->string_ref[i] = 'a' + rand() % 26; // Random lowercase character
    }

    new_node->string_ref[strLen] = '\0'; // null terminator

    new_node->left = new_node->right = new_node->parent = NULL;

    return new_node;
}

// Insert a node into BST
Node* insert(Node *node, int value) {
    if(node == NULL){
        return createNode(value, value);  // Create a new node for this value as it's a leaf.
    }

    if(value < node->value){
        Node *lchild = insert(node->left, value);
        node->left  = lchild;

        lchild->parent = node;
    } else if (value > node->value) {
        Node *rchild = insert(node->right, value);
        node->right = rchild;

        rchild->parent = node;
    }

    return node;  // return the root node of updated tree.
}

// Function to construct a balanced BST from an array
Node* sortedArrayToBST(int arr[], int start, int end) {
    if (start > end){
        return NULL;  // Base case for recursion.
    }

    int mid = (start + end)/2;
    Node *root = createNode(arr[mid], arr[mid]);  // Create a new node with the middle value of array segment as root.

    root->left  = sortedArrayToBST(arr, start, mid - 1);  // Construct left subtree recursively.
    root->right = sortedArrayToBST(arr, mid + 1, end);  // Construct right subtree recursively.

    return root;  // Return the root of the constructed balanced BST.
}
```
This code demonstrates how to create a node structure with integer values and string references, insert nodes into a binary search tree (BST), and construct a balanced BST from an array of sorted integers. It uses recursion to build the balanced BST by choosing the middle element of each segment as the root, creating left and right subtrees recursively for smaller segments.
']

