Task* create_task(int timestamp, int priority, void (*handler)(void*)) {
    Task *new_task = (Task*)malloc(sizeof(Task));
    if (new_task == NULL) return NULL;

    new_task->timestamp = timestamp;
    new_task->priority = priority;
    new_task->taskHandler = handler;

    return new_task;
}

// Function to create a node for the priority queue
struct PQNode* newPQNode(Task *d) {
    struct PQNode* temp = (struct PQNode*)malloc(sizeof(struct PQNode));
    temp->task = d;
    temp->priority = d->priority;
    temp->next = NULL;

    return temp;
}

// Function to create a new priority queue
PriorityQueue* createPQ() {
    PriorityQueue *pq = (PriorityQueue*)malloc(sizeof(PriorityQueue));
    if (pq == NULL) return NULL;

    pthread_mutex_init(&pq->lock, NULL);
    pq->head = NULL;
    return pq;
}

// Function to add a task to the priority queue according to its priority
void push(PriorityQueue *pq, Task* d) {
    struct PQNode* start = (struct PQNode*)malloc(sizeof(struct PQNode));

    pthread_mutex_lock(&pq->lock);

    // Create new node
    struct PQNode* temp = newPQNode(d);
    if (pq->head == NULL) {
        pq->head = temp;
    } else {
        if (pq->head->priority < d->priority) {
            temp->next = pq->head;
            pq->head = temp;
        } else {
            start = pq->head;
            while(start->next != NULL && start->next->priority >= d->priority) {
                start = start->next;
            }
            temp->next = start->next;
            start->next = temp;
        }
    }

    pthread_mutex_unlock(&pq->lock);
}
``` 
