```c
#include <stdlib.h>
#include <pthread.h>
#define POOL_SIZE 1024 // Optimize this according to your needs

typedef struct Node {
    long timestamp;
    int priority;
    struct Node *next;
} Node;

Node memoryPool[POOL_SIZE];
Node* freeList = NULL;
pthread_mutex_t lock;
int usedNodes = 0;

void init() {
    for (int i = 0; i < POOL_SIZE - 1; ++i)
        memoryPool[i].next = &memoryPool[i + 1];
    memoryPool[POOL_SIZE - 1].next = NULL;
    freeList = memoryPool;

    if (pthread_mutex_init(&lock, NULL) != 0){
        printf("Mutex init failed\n");
        exit(EXIT_FAILURE);
    }
}

Node* allocate() {
    pthread_mutex_lock(&lock);

    if (freeList == NULL && usedNodes < POOL_SIZE) { // Grow the pool dynamically
        memoryPool[usedNodes++].next = freeList;
        freeList = &memoryPool[usedNodes - 1];
    }

    Node* node = freeList;
    if (freeList != NULL) 
        freeList = freeList->next;

    pthread_mutex_unlock(&lock);

    return node;
}

void deallocate(Node *node) {
    pthread_mutex_lock(&lock);
    if (usedNodes > 0){ 
        memoryPool[--usedNodes] = *node;
        deallocate(node + 1); // Free the next node in case of contiguous nodes
        freeList = &memoryPool[usedNodes - 1];
    }
    pthread_mutex_unlock(&lock);
}

void insertAtEnd(Node **head, Node *newNode) {
    newNode->next = NULL;
    if (*head == NULL){
        *head = newNode;
        return;
    }

    Node *current = *head;
    while (current->next != NULL) 
        current = current->next;

    current->next = newNode;
}

