#define MAX_EVENTS 10000000
Node* events[MAX_EVENTS];
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void addEvent(long timestamp, char* description, int tag) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < MAX_EVENTS; ++i) {
        if (events[i] == NULL) {
            events[i] = malloc(sizeof(Node));
            assert(events[i] != NULL);
            events[i]->event.timestamp = timestamp;
            events[i]->event.description = strdup(description);
            events[i]->event.tag = tag;
            events[i]->next = events[i];  // circular linked list
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}

void removeEvent(int tag) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < MAX_EVENTS; ++i) {
        if (events[i] != NULL && events[i]->event.tag == tag) {
            free(events[i]->event.description);
            free(events[i]);
            events[i] = NULL;
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}
```
