// A node in our allocator
typedef struct node_t {
    void *data;
    struct node_t *next;
} node_t;

// Our custom memory pool allocator
typedef struct {
    node_t *head;
    size_t data_size;
    pthread_mutex_t lock; // for thread-safety
} allocator_t;

void* allocate(allocator_t *alloc) {
    pthread_mutex_lock(&alloc->lock);

    if (alloc->head == NULL) {
        node_t *new_node = malloc(sizeof(node_t));
        new_node->data = malloc(alloc->data_size);

        pthread_mutex_unlock(&alloc->lock);
        return new_node->data;
    } else {
        node_t *node = alloc->head;
        alloc->head = node->next;

        pthread_mutex_unlock(&alloc->lock);
        return node->data;
    }
}

void deallocate(allocator_t *alloc, void *ptr) {
    pthread_mutex_lock(&alloc->lock);

    node_t *node = (node_t*) ptr;
    node->next = alloc->head;
    alloc->head = node;

    pthread_mutex_unlock(&alloc->lock);
}
```
