void insert_string(std::forward_list<std::string>& flist, std::string str1, std::string str2) 
{
    auto prev = flist.before_begin();
    for (auto it = flist.begin(); it != flist.end(); ++it) {
        if (*it == str1) {
            flist.insert_after(it, str2);
            return;
        }
        prev = it;
    }
    // If the first string isn't found, insert at end of list
    flist.insert_after(prev, str2);
}
