void* allocator(_Atomic(Node*) *last, size_t size) {
    Node* node = malloc(sizeof(Node)); // replace with your custom memory pool allocation function
    if (!node) return NULL;

    node->record.value = 0; 

    Node* prev = atomic_exchange_explicit(last, node, memory_order_relaxed);
    while (prev != NULL) {
        prev = atomic_load(&head);
        if (_Atomic_compare_exchange_weak(&head, &prev, node)) break;
    }

    return &node->record;
}

void* allocateRecord(size_t size) {
    pthread_mutex_lock(&mutex); // for thread safety, use a lock-free alternative in production
    void* record = allocator(&head, sizeof(Node)); 
    pthread_mutex_unlock(&mutex);

    return record;
}
