    locations = allocateMemory(sizeof(char*)* locationCount);
    temperatures = allocateMemory(sizeof(double) * locationCount);

    for (int i = 0; i < locationCount; ++i){
        int hashIndex = hashFunction(locations[i]); // generate a hash index 
        if (weatherData[hashIndex].location != NULL){ // check collision
            printf("Error: Duplicate location detected.\n");
