["Here is an implementation of the described function using POSIX threads for thread safety and aligned memory allocation for cache locality and data alignment optimization. The solution does not include error handling or out-of-memory recovery to keep it concise:

```c
#include <stdlib.h>
#include <pthread.h>
#include <assert.h>

typedef struct {
    int value;
    long* offset_ptr;
    int* key_ptr;
} record;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

record* init(long size1, int size2) {
    assert(size1 > 0 && size2 > 0);

    long *offsets = aligned_alloc(64, sizeof(*offsets)*size1);
    int *keys = malloc(sizeof(*keys)*size2);
    record *records = calloc(size2, sizeof(*records));

    if (!offsets || !keys || !records) {
        free(offsets);
        free(keys);
        free(records);

        return NULL;
    }

    // Initialize offsets array
    for (long i = 0; i < size1; ++i) {
        offsets[i] = rand();
    }

    // Randomly generate unique integer value
    int* pool = malloc(sizeof(*pool)*size2);
    if (!pool) {
        free(offsets);
        free(keys);
        free(records);

        return NULL;
    }

    for (int i = 0; i < size2; ++i) {
        pool[i] = i;
    }
    for (int i = 0; i < size2; ++i) {
        int j = rand() % (size2 - i);

        pthread_mutex_lock(&lock);
        keys[i] = pool[j];
        records[i].value = keys[i];
        records[i].offset_ptr = &offsets[keys[i]];
        records[i].key_ptr = &keys[i];

        // Shift last element to j
        pool[j] = pool[size2 - i - 1];
        pthread_mutex_unlock(&lock);
    }

    free(pool);

    return records;
}
```
