    MurmurHash3_x86_32(&i, sizeof(i), 1, (void*)&id);
    sprintf(id, "%u", id); // Convert the unsigned int to a string

    new_item.index = i;
    new_item.value = minRange + ((float)rand() / RAND_MAX) * (maxRange - minRange);
