typedef struct {
    long* offset;
    int key;
    int value;
} Record;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

Record* createRecords(int numOffsets, va_list offsetSizes, int numKeys, 
                      va_list keySizes, int rangeMin, int rangeMax, 
                      size_t maxMemoryUsage, bool (*checksumFunction)(void*,size_t)) {

    pthread_mutex_lock(&lock);

    // Check memory availability before allocation
    size_t totalSize = sizeof(Record) * numKeys;
    for (int i = 0; i < numOffsets; ++i) {
        int offsetSize = va_arg(offsetSizes, int);
        totalSize += sizeof(long) * offsetSize;
    }

    if (totalSize > maxMemoryUsage) {
        pthread_mutex_unlock(&lock);
        return NULL; // Not enough memory available
    }

    Record* records = malloc(sizeof(Record) * numKeys);
    long* currentOffsetPtr = (long*) (records + numKeys);

    for (int i = 0; i < numKeys; ++i) {
        int keySize = va_arg(keySizes, int);

        records[i].offset = currentOffsetPtr;
        // Initialize offset array with random numbers here

        currentOffsetPtr += keySize;
    }

    for (int i = 0; i < numKeys; ++i) {
        // Generate unique keys and data values using the checksum function
        int newKey, newValue;
        do {
            newKey = rand() % rangeMax + rangeMin;
            newValue = rand() % rangeMax + rangeMin;
        } while (!checksumFunction(&newKey, sizeof(int)));

        records[i].key = newKey;
        records[i].value = newValue;
    }

    pthread_mutex_unlock(&lock);

