void manageMemory() {
    static long* offsets = NULL; // Static to preserve data across calls
    static int* keys = NULL; 
    static Record** records = NULL;

    pthread_mutex_lock(&lock); // Ensure thread safety

    if (offsets == NULL) { // If arrays not allocated yet, allocate them
        offsets = malloc(MAX_SIZE * sizeof(long)); 
        keys = calloc(MAX_SIZE, sizeof(int)); // Calloc to ensure zero initialization
        records = malloc(MAX_SIZE * sizeof(Record*));
