    if (offsets == NULL || keys == NULL || records == NULL) { // Handle allocation failure
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE); // Exit with an error code
    }

    for (int i = 0; i < MAX_SIZE; ++i) { 
