// Task structure to represent a task in the system
typedef struct {
    int taskID;
    int priority;
    char status[20];
    struct timeval submissionTime;
    struct timeval completionTime;
} Task;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t condition = PTHREAD_COND_INITIALIZER;
Task *taskQueue[50000];
int taskCount = 0;

// Function to add a task to the queue
void enqueue(Task *task) {
    pthread_mutex_lock(&lock);
    while (taskCount == 50000) {
        pthread_cond_wait(&condition, &lock);
    }
    taskQueue[taskCount++] = task;
    pthread_mutex_unlock(&lock);
}

// Function to remove a task from the queue
Task *dequeue() {
    pthread_mutex_lock(&lock);
    while (taskCount == 0) {
        pthread_cond_wait(&condition, &lock);
    }
    Task *task = taskQueue[--taskCount];
    pthread_mutex_unlock(&lock);
    return task;
}

// Function to handle a task
void *handleTask(void *arg) {
    // Cast the argument back to a Task and do some work...
    Task *task = (Task *) arg;

    // ... update statuses, interact with an external API etc. 
}

// Function to start processing tasks in the queue
void processTasks() {
    while (1) {
        Task *task = dequeue();

        pthread_t thread;
        pthread_create(&thread, NULL, handleTask, task);
    }
}

int main(int argc, char **argv) {
