    int DL_Layer_Indication;
    int DMRS_Configuration;
} DCI_Message;

typedef struct Node {
    DCI_Message message;
    struct Node* next;
} Node;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
Node* head = NULL;  // Linked list for messages.

void initialize() {
    pthread_mutex_lock(&lock);
    if (head == NULL)
        head = malloc(sizeof(Node));
    pthread_mutex_unlock(&lock);
}

// Add a message to the linked list.
void addMessage(DCI_Message message) {
    Node* node = malloc(sizeof(Node));
    node->message = message;
    pthread_mutex_lock(&lock);
    node->next = head;
    head = node;
    pthread_mutex_unlock(&lock);
}

// Delete a message from the linked list.
void deleteMessage(DCI_Message message) {
    pthread_mutex_lock(&lock);
    Node* prev = NULL;
    for (Node* curr = head; curr != NULL; prev = curr, curr = curr->next) {
        if (curr->message.DL_Layer_Indication == message.DL_Layer_Indication && 
            curr->message.DMRS_Configuration == message.DMRS_Configuration) {
            if (prev != NULL)
                prev->next = curr->next;
            else
                head = curr->next;
            free(curr);
        }
    }
    pthread_mutex_unlock(&lock);
}

// Lookup a message in the linked list.
