#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    char* name;
    int status; // You might want to define an enum for better readability.
} job;

job** jobs = NULL;
int job_count = 0;
int job_size = 10000;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void initialize() {
    jobs = malloc(sizeof(job*) * job_size);
}

void add_job(char* name, int status) {
    pthread_mutex_lock(&lock);

    if (job_count >= job_size) {
        job_size += 10000;
        jobs = realloc(jobs, sizeof(job*) * job_size);
    }

    job* new_job = malloc(sizeof(job));
    new_job->name = name;
    new_job->status = status;
    jobs[job_count] = new_job;
    job_count++;

    pthread_mutex_unlock(&lock);
}
