    srand((unsigned int)time(NULL));
    int i, j;

    // Allocate memory for keys array with size adjustment during iteration
    int *keys = malloc(sizeof(*keys));
    if (keys == NULL) exit(-1); 

    for (i = 0; i < 2000000; ++i) {
        int val = rand() % 2000000 + 1; // Random value from 1 to 2,000,000

        for (j = 0; j < i; ++j) {
            if (keys[j] == val) break;  // Check for duplicates
        }

        if (i == j) {
            keys = realloc(keys, sizeof(*keys) * (i + 1));   // Adjust size only when no duplicate is found
            if (keys == NULL) exit(-1); 

            keys[i] = val;
        } else {
            --i;    // Decrement i to repeat the loop without incrementing again
        }
    }

    srand((unsigned int)time(NULL));

    for (int k = 0; k < 100000; ++k) {
        offsets[k] = rand() % 2000001 - 1000000; // Random value from -1,000,000 to 1,000,000
    }

