#include <forward_list>
#include <string>
#include "json.hpp"
using json = nlohmann::json;

std::string toLowerCase(const std::string& str){
    std::string lowerStr = str;
    std::transform(lowerStr.begin(), lowerStr.end(), lowerStr.begin(), ::tolower);
    return lowerStr;
}

void manageStringCollection(std::forward_list<std::string>& flist, int index, const std::string& strArg, bool caseSensitive) {
    if(!caseSensitive){
        auto it = flist.begin();
        while (it != flist.end()) {
            if(toLowerCase(*it) == toLowerCase(strArg)) {
                it = flist.erase_after(it);
            } else{
                ++it;
            }
        }
    }else{
        auto it = flist.begin();
        while (it != flist.end()) {
            if(*it == strArg) {
                it = flist.erase_after(it);
            } else{
                ++it;
            }
        } 
    }

    int i = 0;
    auto iterator = flist.before_begin();
    for (; iterator != flist.end(); ++iterator, ++i) {
        if(i == index){
            flist.insert_after(iterator, strArg);
            return; 
        }
    }

    flist.push_front(strArg);
}

json forwardListToJson(std::forward_list<std::string>& flist) {
    json j = json::array();
    for (const auto &str : flist) {
        j.push_back(str);
    }
    return j;
}
