typedef struct ConnectionAttempt {
    char clientIP[IP_LEN];
    time_t timestamp;
    int attemptCount;
    bool status; // True for success, False for failure.
} ConnectionAttempt;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

typedef struct Node {
    ConnectionAttempt data;
    struct Node* prev;
    struct Node* next;
} Node;

Node* head = NULL;
int size = 0;

void addRecord(ConnectionAttempt record) {
    pthread_mutex_lock(&lock);

    if (size == MAX_RECORDS) {
        // Remove the oldest record before adding a new one.
        Node* tail = head->prev;
        tail->prev->next = head;
        head->prev = tail->prev;
        free(tail);
    } else if (size == 0) {
        // Initialize circular linked list with the first node.
        Node* newNode = malloc(sizeof(Node));
        memcpy(&newNode->data, &record, sizeof(ConnectionAttempt));
        newNode->next = newNode;
        newNode->prev = newNode;
        head = newNode;
    } else {
        // Add a new node to the end of the circular linked list.
        Node* tail = head->prev;
        Node* newNode = malloc(sizeof(Node));
        memcpy(&newNode->data, &record, sizeof(ConnectionAttempt));
        newNode->next = head;
        newNode->prev = tail;
        tail->next = newNode;
    }

    pthread_mutex_unlock(&lock);
}
