["Here is an example of how you could approach this problem in C using a combination of locks for concurrency control, pthread library for threading, and a hash table with separate chaining for collision resolution. The hash table uses linked lists to store entries that collide. Note that it's just an example and does not cover all aspects of your task due to its complexity and size.

```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int integer;
    float floating_point;
    char* string;
} StructuredData;

typedef struct Entry {
    StructuredData* data;
    size_t refcount;
    pthread_mutex_t lock;
    struct Entry* prev;
    struct Entry* next;
} Entry;

#define HASH_TABLE_SIZE 1024
Entry* hashTable[HASH_TABLE_SIZE];
pthread_mutex_t hashLock = PTHREAD_MUTEX_INITIALIZER;

size_t hashFunction(char* string) {
    size_t hash = 5381;
    int c;
    while ((c = *string++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    return hash % HASH_TABLE_SIZE;
}

Entry* createEntry(int integer, float floating_point, char* string) {
    Entry* entry = malloc(sizeof(Entry));
    if (entry == NULL)
        return NULL;

    StructuredData* data = malloc(sizeof(StructuredData));
    if (data == NULL) {
        free(entry);
        return NULL;
    }

    data->integer = integer;
    data->floating_point = floating_point;
    data->string = malloc(strlen(string) + 1);
    if (data->string == NULL) {
        free(entry);
        free(data);
        return NULL;
    }

    strcpy(data->string, string);
    entry->data = data;
    entry->refcount = 1;
    pthread_mutex_init(&entry->lock, NULL);
    entry->prev = entry;
    entry->next = entry;

    return entry;
}

void addEntry(int integer, float floating_point, char* string) {
    Entry* newEntry = createEntry(integer, floating_point, string);
    if (newEntry == NULL)
        return;

    size_t hashValue = hashFunction(string);

    pthread_mutex_lock(&hashLock);
    Entry** bucket = &hashTable[hashValue];
    while (*bucket != NULL) {
        if (strcmp((*bucket)->data->string, string) == 0) {
            (*bucket)->refcount++;
            free(newEntry);
            pthread_mutex_unlock(&hashLock);
            return;
        }
        bucket = &(*bucket)->next;
    }

    *bucket = newEntry;
    newEntry->prev = newEntry;
    newEntry->next = newEntry;
    pthread_mutex_unlock(&hashLock);
}

void removeEntry(char* string) {
    size_t hashValue = hashFunction(string);

    pthread_mutex_lock(&hashLock);
    Entry** bucket = &hashTable[hashValue];
    while (*bucket != NULL) {
        if (strcmp((*bucket)->data->string, string) == 0) {
            if ((--(*bucket)->refcount) == 0) {
                Entry* prev = (*bucket)->prev;
                Entry* next = (*bucket)->next;

                if (prev != *bucket) {
                    prev->next = next;
                    next->prev = prev;
                } else {
                    prev->next = prev;
                }

                pthread_mutex_destroy(&(*bucket)->lock);
                free((*bucket)->data->string);
                free((*bucket)->data);
                free(*bucket);
            }

            *bucket = NULL;
        }

        bucket = &(*bucket)->next;
    }

    pthread_mutex_unlock(&hashLock);
}
```
Please note that in a real-world scenario, you might need to use more sophisticated data structures and algorithms for hashing, resizing the hash table etc. This example does not include these aspects and does not cover all of your requirements due to its complexity and size. The actual implementation would be a lot larger and much more complex than this simplified version.
