size_t current_offset = 0;

// Memory pool allocator function
void* mymalloc(size_t size) {
    void* retval;

    pthread_mutex_lock(&mutex); // Thread safety

    if (current_offset + size > MEMORY_POOL_SIZE) {
        return NULL; // No more memory available
    }

    retval = &memory_pool[current_offset];
    current_offset += size;

    pthread_mutex_unlock(&mutex); // Release lock

    return retval;
}

// Memory pool cleanup function
void myfree(void* block) {
    if (block == NULL) return; // Null check

    pthread_mutex_lock(&mutex); // Thread safety

    size_t offset = (char*)block - memory_pool;

    // Check for valid block in pool
    if(offset >= 0 && offset < MEMORY_POOL_SIZE){ 
        current_offset = offset;
    }

    pthread_mutex_unlock(&mutex); // Release lock
}

