typedef struct node {
    unsigned int id;
    char type;
    struct node* left;
    struct node* right;
} Node;

Node* root = NULL;

// Function to allocate a new node with given data 
Node* create_node(unsigned int id, char type) {
    Node* new_node = (Node*)malloc(sizeof(Node));

    if(new_node == NULL){
        printf("Memory allocation failed!\n");
        exit(0);
    }

    new_node->id    = id;
    new_node->type  = type;
    new_node->left  = NULL;
    new_node->right = NULL;

    return new_node; // Returning newly created node 
}

// Function to insert a new node with given data in BST 
Node* insert(Node* node, unsigned int id, char type) {
    if (node == NULL) 
        return create_node(id, type); // New root node if tree is empty

    if (id < node->id) 
        node->left  = insert(node->left, id, type); // Insert in left subtree
    else if (id > node->id) 
        node->right = insert(node->right, id, type); // Insert in right subtree
    else {  
        node->type  = type; // Update existing item's data instead of inserting a duplicate
        return node;
    }

    return node; 
}

// Function to search a node with given id in BST 
Node* search(Node* root, unsigned int id) {
    if (root == NULL || root->id == id) 
       return root;

    if (root->id < id) 
       return search(root->right, id); // Search in right subtree

    return search(root->left, id); // Search in left subtree
}

// Function to perform inorder traversal of BST and free memory
void delete_tree(Node* node) {
    if (node == NULL) 
        return;

    delete_tree(node->left);
    delete_tree(node->right);

    printf("Deleting id: %u\n", node->id); // Remove this line for production, only used to check if deletion is happening properly.
    free(node); // Free memory of current node 
}

// Function to get root of BST
Node* get_root() {
   return root;
}
```
