```c
#include <stdlib.h>
#include <time.h>

typedef struct record {
    int value;
    struct record *next;
    struct record *prev;
} record_t;

record_t* create_list(int count, long offset) {
    if (count <= 0 || offset < 0) {
        return NULL; // Invalid input case
    }

    srand((unsigned int) time(NULL)); 

    // Allocating memory for the array of records and keys
    record_t* records = malloc(sizeof(record_t) * count);

    if (records == NULL) {
        return NULL; // Handle allocation failure
    }

    // Initializing each record's value to a random value within a specified range
    for (int i = 0; i < count; ++i) {
        records[i].value = rand() % offset;

        if (i > 0) {
            records[i].prev = &records[i - 1]; // Point to the previous record
        } else {
            records[i].prev = &records[count - 1]; // The first node points back to the last one.
        }

        if (i < count - 1) {
            records[i].next = &records[i + 1]; // Point to the next record
        } else {
            records[i].next = records; // The last node points back to the first one.
        }
    }

    return records; // Return a pointer to the head of this list
}
```
