['Below is a simple example of how you could implement this in C using an AVL tree and thread synchronization (locking) mechanism for multiple threads access. 

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct task{
    int id;
    int priority;
    int status;
}task;

struct Node {
   task* data;
   struct Node *left, *right;
   int height;
};

struct Node *root = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

int max(int a, int b) { return (a > b)? a : b; }
int height(struct Node* N){ return (N == NULL)? 0 : N->height; }

// A utility function to right rotate subtree rooted with y
struct Node* rightRotate(struct Node* y){
    struct Node* x = y->left;
    struct Node* T2 = x->right;
    x->right = y;
    y->left = T2;
    y->height = max(height(y->left), height(y->right)) + 1;
    x->height = max(height(x->left), height(x->right)) + 1;
    return x;
}

// A utility function to left rotate subtree rooted with x
struct Node* leftRotate(struct Node* x){
    struct Node* y = x->right;
    struct Node* T2 = y->left;
    y->left = x;
    x->right = T2;
    x->height = max(height(x->left), height(x->right)) + 1;
    y->height = max(height(y->left), height(y->right)) + 1;
    return y;
}

int getBalance(struct Node* N){
    if (N == NULL) return 0;
    return height(N->left) - height(N->right);
}

// Function to insert a task entity in AVL tree
struct Node* insert(task* data, struct Node* node){
    // Perform the normal BST rotation
    if (node == NULL) { 
        return (newNode(data));
    }

    if (data->priority < node->data->priority) node->left = insert(data, node->left);
    else if (data->priority > node->data->priority) node->right = insert(data, node->right);
    else return node; // No duplicates allowed

    // Update height of ancestor node
    node->height = 1 + max(height(node->left), height(node->right));

    // Get the balance factor and balance the tree if unbalanced
    int balance = getBalance(node);

    // Left Left Case
    if (balance > 1 && data->priority < node->left->data->priority) return rightRotate(node);
    // Right Right Case
    if (balance < -1 && data->priority > node->right->data->priority) return leftRotate(node);
    // Left Right Case
    if (balance > 1 && data->priority > node->left->data->priority){
        node->left = leftRotate(node->left);
        return rightRotate(node);
    }
    // Right Left Case
    if (balance < -1 && data->priority < node->right->data->priority) {
        node->right = rightRotate(node->right);
        return leftRotate(node);
    }
    return node; // returned unbalanced node
}
```

This is a simple implementation and does not include all functionality such as deleting, updating tasks etc. You should expand it according to your needs. Additionally you must manage memory properly and handle thread safety for access from multiple threads. 

For error handling, you could wrap each function call in `pthread_mutex_lock(&lock)` and `pthread_mutex_unlock(&lock)` to ensure that only one thread is accessing the data structure at a time. For invalid operations, such as attempting to delete a non-existent task, you might want to return an error code or throw an exception. 

