    }

    public float GenerateFloatValue() {
        Interlocked.Increment(ref counter[1]);
        double range = (double)max - (double)min;
        return (float)(random.NextDouble() * range + min);
    }

    public int GenerateIntValue() {
        Interlocked.Increment(ref counter[0]);
        return random.Next((int)Math.Ceiling(min), (int)Math.Floor(max));
    }

    public void InsertToBST(uint id, char type) {
        Node newNode = new Node { ID = id, Type = type };

        if (root == null) {
            root = newNode;
            return;
        }

        var current = root;
        while (true) {
            if (newNode.ID < current.ID) {
                if (current.LeftChild == null) {
                    current.LeftChild = newNode;
                    break;
                } else {
                    current = current.LeftChild;
                }
            } else if(newNode.ID > current.ID){
                if (current.RightChild == null) {
                    current.RightChild = newNode;
                    break;
                } else {
                    current = current.RightChild;
                }
            } else { // duplicate ID, just update type
                current.Type = newNode.Type;
                break;
            }
        }
    }

    public override string ToString() {
        return $"Current Range: [{min}, {max}]";
    }
}
``` 
