class CHM {
private:
    std::shared_mutex mutex_;
    std::unordered_map<unsigned int, Item> map_;
public:
    void insert(const unsigned int& id, const char& type) {
        std::unique_lock<std::shared_mutex> lock(mutex_);
        if (map_.size() >= 10'000'000) {
            std::cerr << "Exceeded maximum size!" << std::endl;
            return;
        }
        map_.insert({id, Item{id, type}});
    }

    void erase(const unsigned int& id) {
        std::unique_lock<std::shared_mutex> lock(mutex_);
        auto it = map_.find(id);
        if (it != map_.end()) {
            map_.erase(it);
        }
    }

    Item getItem(const unsigned int& id) const {
        std::shared_lock<std::shared_mutex> lock(mutex_);
        auto it = map_.find(id);
        if (it != map_.end()) {
            return it->second;
        } else {
            throw std::runtime_error("Item not found.");
        }
    }
};
