#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct packet {
    int id; 
    double timestamp; 
    int payload_length; 
    struct packet* next;
} Packet;

#define POOL_SIZE 1024 * 1024 // 1MB memory pool size
Packet* memoryPool = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
int remaining = 0;

void* allocate(size_t size) {
    pthread_mutex_lock(&mutex);

    if (memoryPool == NULL || remaining < size) {
        // Expand the memory pool as needed. 
        int newSize = POOL_SIZE * ((remaining + size - 1) / POOL_SIZE + 1);
        memoryPool = realloc(memoryPool, newSize);
        remaining = newSize;
    }

    void* ptr = memoryPool;
    memoryPool += size;
    remaining -= size;

    pthread_mutex_unlock(&mutex);

    return ptr;
}

Packet* createPacket() {
    Packet* packet = allocate(sizeof(Packet));
    memset(packet, 0, sizeof(*packet)); // Initialize memory to zero.

    // Randomly initialize fields.
    packet->id = rand();
    packet->timestamp = (double)rand() / RAND_MAX;
    packet->payload_length = rand();
    packet->next = NULL;

    return packet;
}

void cleanup() {
    pthread_mutex_lock(&mutex);
    free(memoryPool);
    memoryPool = NULL;
    remaining = 0;
    pthread_mutex_unlock(&mutex);
}
