    char* clientIP;
    int timestamp;
    int attemptCount;
    int status;  // 0 - failure, 1 - success
} ConnectionAttempt;

// Define a node for circular doubly linked list
typedef struct Node {
    ConnectionAttempt* data;
    struct Node* prev;
    struct Node* next;
} Node;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
Node* head = NULL;  // Head of the linked list

// Define a custom memory pool allocator
typedef struct {
    void** blocks;
    int block_size;
    int num_blocks;
} MemoryPool;

MemoryPool* createMemoryPool(int size, int block_size) {
    MemoryPool* mempool = malloc(sizeof(MemoryPool));
    mempool->block_size = block_size;
    mempool->num_blocks = size / block_size;
    mempool->blocks = malloc(mempool->num_blocks * sizeof(void*));

    for (int i = 0; i < mempool->num_blocks; ++i) {
        mempool->blocks[i] = NULL;
    }

    return mempool;
}

// Allocate memory from the pool
void* allocFromPool(MemoryPool* mempool) {
    for (int i = 0; i < mempool->num_blocks; ++i) {
        if (mempool->blocks[i] == NULL) {
            void* block = malloc(mempool->block_size);
            mempool->blocks[i] = block;
            return block;
        }
    }

    // If all blocks are in use, resize the pool
    mempool->num_blocks++;
    void* block = malloc(mempool->block_size);
    mempool->blocks[mempool->num_blocks - 1] = block;

    return block;
}

// Free memory from the pool
void freeFromPool(MemoryPool* mempool, void* ptr) {
    for (int i = 0; i < mempool->num_blocks; ++i) {
        if (mempool->blocks[i] == ptr) {
            free(ptr);
            mempool->blocks[i] = NULL;
            break;
        }
    }
}

// Function to manage connection attempts
void manageConnectionAttempts() {
    MemoryPool* mempool = createMemoryPool(5000, sizeof(Node));  // Define your own size and block_size here

    for (int i = 0; i < 5000; ++i) {
        Node* node = allocFromPool(mempool);

        ConnectionAttempt* attempt = malloc(sizeof(ConnectionAttempt));

