        // attempt->clientIP = getClientIP();
        // attempt->timestamp = getTimestamp();
        // ... etc

        pthread_mutex_lock(&lock);  // Lock to ensure thread safety

        if (head == NULL) {
            head = node;
            head->prev = head;
            head->next = head;
        } else {
            Node* lastNode = head->prev;

            lastNode->next = node;
            node->prev = lastNode;
            node->next = head;
            head->prev = node;
        }

        pthread_mutex_unlock(&lock);  // Unlock after modification
    }

    // Clean up allocated memory and pool
    for (int i = 0; i < mempool->num_blocks; ++i) {
        if (mempool->blocks[i] != NULL) {
            freeFromPool(mempool, mempool->blocks[i]);
        }
    }

    free(mempool);
}
