['Here is a sample implementation using C with the necessary checks and constraints in place. This code utilizes stdlib's `qsort` to ensure no two structures share a key or offset, but it could be improved by implementing a more efficient data structure like a hash map or tree for faster lookup times. 

In this example, we use rand() for random number generation, and malloc/calloc for memory allocation. Be sure to include the necessary headers and link against the math library with `-lm`.

```c
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <math.h>

typedef struct {
    long offset;
    int key;
    float precision;
} dataPoint;

int cmp(const void* a, const void* b) {
    return ((dataPoint*)a)->key - ((dataPoint*)b)->key;
}

dataPoint* generateDataPoints(long offsets[], int keys[], size_t n, float min, float max) {
    qsort(keys, n, sizeof(int), cmp); // Sort keys for duplicate check

    dataPoint* points = (dataPoint*)malloc(n * sizeof(dataPoint));
    if (!points) {
        printf("Error: Failed to allocate memory\n");
        return NULL;
    }

    for (size_t i = 0; i < n; i++) {
        // Check for duplicate keys
        if (i > 0 && keys[i] == keys[i-1]) {
            printf("Error: Duplicate key found\n");
            free(points);
            return NULL;
        }

        points[i].offset = offsets[i];
        points[i].key = keys[i];

        // Generate random precision value within specified range
        float randFloat = ((float)rand()/(float)(RAND_MAX)) * (max - min) + min;
        points[i].precision = randFloat;
    }

