Node** createList(int numRecords, long minOffset, long maxOffset) {
    // Random seed for random number generation
    srand((unsigned int)time(NULL));

    // Create a list of offsets and keys
    long* offset_values = (long*)calloc(numRecords, sizeof(long));
    int* keys = (int*)calloc(numRecords, sizeof(int));

    Node** nodeList = (Node**)malloc(numRecords * sizeof(Node*));

    for(int i = 0; i < numRecords; i++) {
        // Initialize offset values
        long rand_offset = minOffset + rand() % ((maxOffset + 1) - minOffset);

        while (contains(offset_values, rand_offset, numRecords)) { 
            rand_offset = minOffset + rand() % ((maxOffset + 1) - minOffset);
        }
        offset_values[i] = rand_offset;

        // Initialize keys
        int rand_key = rand();
        while (contains(keys, rand_key, numRecords)) { 
            rand_key = rand();
        }
        keys[i] = rand_key;

        Node* node = (Node*)malloc(sizeof(Node));
        Record* record = (Record*)malloc(sizeof(Record));
        record->value = 1.0 * rand() / RAND_MAX; // Generate random double between 0 and 1

        node->record = record;
        node->offset_value = &offset_values[i];

        if(i > 0) {
            Node* prevNode = nodeList[i - 1];

            // Set previous and next pointers for circular doubly linked list
            prevNode->next = node;
            node->prev = prevNode;

            // Make the last node point back to the first one
            if(i == numRecords - 1) {
                node->next = nodeList[0];
                nodeList[0]->prev = node;
            }
        } else {
            node->prev = node;
            node->next = node;
        }

        nodeList[i] = node;
    }

    free(keys); // No longer need the keys array, so we can free its memory.
    return nodeList;
}

void deleteNodeList(Node** nodeList, int numRecords) {
    for (int i = 0; i < numRecords; i++) {
        free(nodeList[i]->record); // First, free the record inside each node.
        free(nodeList[i]); // Then, free each individual node.
    }

    free(nodeList); // Finally, free the array that held all the nodes.
}

int contains(long* arr, long target, int size) {
    for (int i = 0; i < size; i++) {
        if (arr[i] == target) return 1;
    }

    return 0;
}
```
