Record* createRecords(int n, const char *password) {
    /* Initialize AES-256 cipher */
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    unsigned char key[SHA256_DIGEST_LENGTH];
    SHA256((unsigned char*)password, strlen(password), key);

    /* Initialize cipher */
    EVP_EncryptInit(ctx, EVP_aes_256_cbc(), key, NULL);

    int ivLen = EVP_CIPHER_CTX_iv_length(ctx);
    unsigned char *iv = malloc(sizeof(unsigned char) * ivLen);
    RAND_bytes(iv, ivLen);

    /* Set the IV length */
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, ivLen, NULL);

    Record *records = malloc(sizeof(Record) * n);

    for (int i = 0; i < n; i++) {
        /* Generate a random value */
        records[i].value = rand();

        /* Encrypt the record's value */
        int cipherLen, tmpLen;
        unsigned char *ciphertext = malloc(sizeof(unsigned char) * (EVP_CIPHER_CTX_block_size(ctx) + ivLen));
        EVP_EncryptUpdate(ctx, ciphertext, &cipherLen, (unsigned char*)&records[i].value, sizeof(int));

        /* Generate a key from the encrypted value */
        unsigned char *tmp = malloc(sizeof(unsigned char) * SHA256_DIGEST_LENGTH);
        SHA256(ciphertext, cipherLen + ivLen, tmp);

        /* Set the record's key to the encrypted value */
        records[i].key = malloc(SHA256_DIGEST_LENGTH);
        memcpy(records[i].key, tmp, SHA256_DIGEST_LENGTH);

        /* Update timestamp */
        time(&records[i].timestamp);
    }

    /* Cleanup cipher and keys */
    EVP_CIPHER_CTX_cleanup(ctx);
    free(iv);
    OPENSSL_free(tmp);
    free(ciphertext);

    return records;
}
