["Here is how you can implement those requirements in C. I am assuming that `struct node` and `struct mem_block` are defined according to your needs.

```c
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct record {
    int value;
    int* key;
} Record;

typedef struct node {
    long offset_value;
    int key;
    Record rec;
    struct node *next, *prev;
} Node;

struct mem_block {
    void *start;
    size_t size;
    struct mem_block *next;
};

static struct mem_block *mem_pool = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

Node* create_circular_doubly_linked_list(size_t num_records, int min_value, int max_value) {
    Node *head = NULL, *tail = NULL;
    for (size_t i = 0; i < num_records; ++i) {
        Node *newNode = malloc(sizeof(Node));
        newNode->offset_value = rand();
        newNode->key = rand() % (max_value - min_value + 1) + min_value;
        newNode->rec.value = rand() % (max_value - min_value + 1) + min_value;
        if (!head) {
            head = tail = newNode;
            head->prev = tail;
            tail->next = head;
        } else {
            tail->next = newNode;
            newNode->prev = tail;
            head->prev = newNode;
            newNode->next = head;
            tail = newNode;
        }
    }
    return head;
}

void* custom_malloc(size_t size) {
    void *ptr = NULL;
    pthread_mutex_lock(&mutex);
    if (!mem_pool || mem_pool->size < size) {
        struct mem_block *newBlock = malloc(sizeof(struct mem_block));
        newBlock->start = malloc(size);
        newBlock->next = mem_pool;
        newBlock->size = size;
        mem_pool = newBlock;
    }
    ptr = mem_pool->start;
    mem_pool = mem_pool->next;
    pthread_mutex_unlock(&mutex);
    return ptr;
}

void custom_free(void *ptr) {
    struct mem_block *newBlock = malloc(sizeof(struct mem_block));
    newBlock->start = ptr;
    newBlock->next = mem_pool;
    newBlock->size = 0; // 0 size means this block is free to be used again.
    mem_pool = newBlock;
}

void cleanup() {
    struct mem_block *curr = mem_pool, *prev = NULL;
    while (curr) {
        if (!curr->size && prev) {
            prev->next = curr->next;
            free(curr);
            curr = prev;
        } else {
            prev = curr;
            curr = curr->next;
        }
    }
}
```
