["Here's a basic example of how you could implement this in C with error handling and basic cleanup mechanism:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct record {
    char* key;
    int value;
} Record;

typedef struct collection {
    pthread_mutex_t lock;
    Record** records;
    size_t count;
    size_t capacity;
} Collection;

int addRecord(Collection* coll, const char* key, int value) {
    if (coll == NULL || key == NULL) return -1;

    pthread_mutex_lock(&coll->lock);

    Record* rec = malloc(sizeof(Record));
    if (rec == NULL) {
        pthread_mutex_unlock(&coll->lock);
        return -1; // Failed to allocate memory for record.
    }

    rec->key = strdup(key);
    if (rec->key == NULL) {
        free(rec);
        pthread_mutex_unlock(&coll->lock);
        return -1; // Failed to duplicate string key.
    }

    rec->value = value;

    // Resize if necessary.
    if (coll->count >= coll->capacity) {
        Record** newRecords = realloc(coll->records, sizeof(Record*) * (coll->capacity + 10));
        if (newRecords == NULL) {
            free(rec->key);
            free(rec);
            pthread_mutex_unlock(&coll->lock);
            return -1; // Failed to resize array.
        } else {
            coll->capacity += 10;
            coll->records = newRecords;
        }
    }

    coll->records[coll->count++] = rec;
    pthread_mutex_unlock(&coll->lock);
    return 0; // Success.
}

Record* getRecord(Collection* coll, const char* key) {
    if (coll == NULL || key == NULL) return NULL;

    pthread_mutex_lock(&coll->lock);

    for (size_t i = 0; i < coll->count; ++i) {
        if (strcmp(coll->records[i]->key, key) == 0) {
            Record* rec = coll->records[i];
            pthread_mutex_unlock(&coll->lock);
            return rec; // Found matching record.
        }
    }

    pthread_mutex_unlock(&coll->lock);
    return NULL; // No matching record found.
}
```
This code assumes that the caller will free the memory allocated for the returned records when they are no longer needed to avoid memory leaks. A more complete implementation would include mechanisms for periodically cleaning up unused records and handling all possible error cases and edge conditions. Implementing this kind of functionality, especially in a multi-threaded environment, can be quite complex and requires careful design and testing.
