void *custom_malloc(size_t size) {
    static void *memory = NULL;
    if (!memory) {
        // Allocate 20% of system memory for this pool
        long maxMemory = sysconf(_SC_PHYS_PAGES) * sysconf(_SC_PAGE_SIZE);
        size_t allocationSize = (maxMemory / 100) * 20;
        if (posix_memalign(&memory, sysconf(_SC_PAGESIZE), allocationSize)) {
            fprintf(stderr, "Failed to allocate memory\n");
            exit(EXIT_FAILURE);
        }
    }
    static size_t offset = 0;
    if (offset + size > allocationSize) {
        return NULL; // No space left in pool
    } else {
        void *block = memory + offset;
        offset += size;
        return block;
    }
}

