    }
}

// Initialize the database-like system with custom reallocation strategy. 
void initDB(Record** db, long* offsets, int* keys) {
    *db = (Record*)calloc(THRESHOLD, sizeof(Record));
    for(size_t i = 0; i < THRESHOLD; ++i){
        (*db)[i].offset = &offsets[i];
        (*db)[i].key = &keys[i];
    }
}

// Create a doubly linked list of records with pointers to the next and previous record. 
void createLinkedList(Record* db) {
    for (size_t i = 0; i < THRESHOLD - 1; ++i){
        db[i].next = &db[i+1];
        db[i+1].prev = &db[i];
    }
    db[THRESHOLD-1].next = db; // Point to the first element for circular linked list. 
    db->prev = &db[THRESHOLD-1]; // Point to the last element for circular linked list. 
}

// Cleanup function to free resources and disable encryption context. 
void cleanup(Record* db, AES_KEY* aesKey) {
    memset((unsigned char*)aesKey, 0, sizeof(*aesKey)); // clear encryption key from memory. 
    free(db);
}
