void *createRecords(size_t size, size_t alignment, callback postAllocate) {
    if (alignment < 8) {
        fprintf(stderr, "Alignment must be at least 8 bytes\n");
        return NULL;
    }

    // Lock mutex to prevent concurrent access
    pthread_mutex_lock(&mutex);

    void *memory = aligned_alloc(alignment, size);

    if (memory == NULL) {
        fprintf(stderr, "Failed to allocate memory\n");
        // Unlock mutex before returning
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    Record *records = memory;

    for (size_t i = 0; i < size / sizeof(Record); ++i) {
        records[i].offset = i + 1;
        if (postAllocate != NULL) postAllocate(&records[i]);
    }

    // Unlock mutex after memory allocation and initialization are complete
    pthread_mutex_unlock(&mutex);

    return records;
}
