void addToList(time_t timestamp, enum status indicator, char* message) {
    // Allocate memory for new log entry
    LogEntry *newNode = malloc(sizeof(LogEntry));
    if (!newNode) { 
        return; 
    }

    // Copy the data and set next as NULL
    newNode->timestamp = timestamp;
    newNode->indicator = indicator;
    newNode->message = strdup(message);
    newNode->next = NULL;
    if (!newNode->message) { 
        free(newNode); 
        return; 
    }

    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Add new log entry at the end of list
    if (tail) {
        tail->next = newNode;
        newNode->prev = tail;
        tail = newNode;
    } else { 
        head = tail = newNode; 
    }

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);
}

void deleteFromList(time_t timestamp) {
    LogEntry *tmp = head, *prev = NULL;

    while (tmp && tmp->timestamp != timestamp) {
        prev = tmp;
        tmp = tmp->next;
    }

    if (!tmp) { 
        return; 
    }

    pthread_mutex_lock(&mutex);

    // If node to be deleted is head node  
    if (head == tmp) {
        head = tmp->next;
    } else {
        prev->next = tmp->next;
    }

    // Change next only if node to be deleted is NOT the last node
    if (tmp->next != NULL){
        tmp->next->prev = prev;
    }

    free(tmp->message);
    free(tmp);

    pthread_mutex_unlock(&mutex);
}

LogEntry* findInList(time_t timestamp) {
    LogEntry *tmp = head;
    while (tmp && tmp->timestamp != timestamp){
        tmp = tmp->next;
    }

    return tmp;
}

void destroyList() {
    pthread_mutex_lock(&mutex);

    LogEntry *current = head, *next = NULL;

    while (current){
        next = current->next;

        free(current->message);
        free(current);

        current = next;
    }

    head = tail = NULL;

    pthread_mutex_unlock(&mutex);
}
```
This is a basic solution and may need further refining, especially regarding error handling. For instance, it might be useful to consider returning a status code from the `addToList` function indicating whether or not the addition was successful.
