#include <stdatomic.h>

typedef struct data_record {
    _Atomic(long) timestamp;
    int status_code;
    char* message;
} data_record_t;

typedef struct node {
    data_record_t *data;
    struct node *next;
} node_t;

typedef struct list {
    _Atomic(node_t*) head;
    pthread_mutex_t lock;
} list_t;

list_t* init_list() {
    list_t *l = malloc(sizeof(list_t));
    if (pthread_mutex_init(&l->lock, NULL) != 0) {
        free(l);
        return NULL;  // error handling is omitted for brevity
    }
    atomic_store(&l->head, NULL);
    return l;
}

data_record_t* create_data_record(long timestamp, int status_code, char *message) {
    data_record_t *rec = malloc(sizeof(data_record_t));
    if (rec == NULL) return NULL;  // error handling is omitted for brevity
    atomic_store(&rec->timestamp, timestamp);
    rec->status_code = status_code;
    rec->message = message;
    return rec;
}

void insert(list_t *l, data_record_t *data) {
    pthread_mutex_lock(&l->lock);
    node_t *new_node = malloc(sizeof(node_t));  // error handling is omitted for brevity
    new_node->data = data;
    new_node->next = atomic_load(&l->head);
    while(!atomic_compare_exchange_weak(&l->head, &new_node->next, new_node)) {}
    pthread_mutex_unlock(&l->lock);
}

void destroy(list_t *l) {
    node_t* curr = atomic_load(&l->head);
    while (curr != NULL) {
        node_t *next = curr->next;
        free(curr->data->message);  // assuming all allocations are made with malloc
        free(curr->data);
        free(curr);
        curr = next;
    }
    pthread_mutex_destroy(&l->lock);
    free(l);
}
