#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct Node {
    double value;
    char string[];
} Node;

Node* create_linked_list(double min, double step, const char *prefix, int strlen, void (*callback)(Node *)) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    const size_t NODE_SIZE = sizeof(Node) + (strlen + 1) * sizeof(char);
    const int MAX_NODES = 2 * 1024 * 1024 / NODE_SIZE; // Assume 32-byte alignment for char array.

    if (MAX_NODES <= 0 || strlen > 1024) {
        fprintf(stderr, "Memory allocation exceeded or string length too long.\n");
        return NULL;
    }

    int nodes = MAX_NODES - 1; // Leave one node for circular link.

    while (nodes * NODE_SIZE > 2 * 1024 * 1024) {
        step /= 2;
        if (step < 1e-9) {
            fprintf(stderr, "Reduced step size too small to allow allocation.\n");
            return NULL;
        }
    }

    Node *list = aligned_alloc(32, NODE_SIZE * MAX_NODES);
    if (!list) {
        perror("Memory allocation failed");
        return NULL;
    }

    // Initialize nodes.
    for (int i = 0; i < nodes; ++i) {
        list[i].value = min + i * step;

        char *str = (char*)(list[i].string);
        strcpy(str, prefix);

        if (callback != NULL) {
            callback(&list[i]);
        }
    }

    // Create circular linked list.
    for (int i = 0; i < nodes - 1; ++i) {
        list[i].next = &list[i + 1];
        list[i + 1].prev = &list[i];
    }
    list[nodes - 1].next = &list[0];
    list[0].prev = &list[nodes - 1];

    return list;
}
```
