#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct Record {
    int value;
    void *key;
    pthread_mutex_t lock;
} Record;

Record *memoryPool = NULL;
size_t poolSize = 0;
size_t recordCount = 0;
pthread_mutex_t poolLock = PTHREAD_MUTEX_INITIALIZER;

void allocateMemory(size_t size) {
    pthread_mutex_lock(&poolLock);

    if (memoryPool == NULL) {
        memoryPool = malloc(sizeof(Record) * size);

        for (size_t i = 0; i < size; i++) {
            pthread_mutex_init(&memoryPool[i].lock, NULL);

            if (i == 0) {
                memoryPool[i].key = &memoryPool[size - 1]; // Last record points to the first one.
            } else {
                memoryPool[i].key = &memoryPool[i - 1]; // Each record points to the previous one.
            }
        }

        poolSize = size;
    } else {
        Record *oldMemoryPool = memoryPool;
        size_t oldPoolSize = poolSize;

        memoryPool = realloc(memoryPool, sizeof(Record) * (size + oldPoolSize));

        for (size_t i = 0; i < size; i++) {
            pthread_mutex_init(&memoryPool[oldPoolSize + i].lock, NULL);
            memoryPool[oldPoolSize + i].key = &memoryPool[oldPoolSize - 1 + i]; // Each record points to the previous one.
        }

        poolSize += size;
    }

    pthread_mutex_unlock(&poolLock);
}

void initializeRecords(int min, int max) {
    srand(time(NULL));

