["Implementing a full-fledged in-memory cache management system with all these features is beyond the scope of this platform. However, I can provide a basic example that demonstrates how you might start implementing such a function in C. This code snippet represents a simplified version of an LRU Cache and does not include concurrent read/write operations from multiple threads or cache resizing.

```c
#include <stdlib.h>
#include <time.h>
#define MAX_CACHE_SIZE 100 // Adjust this as needed.

typedef struct Record {
    long offset;
    int key;
    void* data;
    time_t timestamp;
    int refCount;
} Record;

Record cache[MAX_CACHE_SIZE];
int start = 0, end = -1, size = 0;

void initCache() {
    for (int i = 0; i < MAX_CACHE_SIZE; ++i) {
        cache[i].data = NULL;
        cache[i].timestamp = 0;
        cache[i].refCount = 0;
    }
}

void updateRecord(int index, void* data) {
    if (cache[index].data != NULL) free(cache[index].data);
    cache[index].data = data;
    cache[index].timestamp = time(NULL);
    cache[index].refCount++;
}

void addRecord(int key, void* data) {
    if (size == MAX_CACHE_SIZE) { // LRU eviction policy.
        int lruIndex = start;
        for (int i = 0; i < MAX_CACHE_SIZE; ++i) {
            if (cache[i].timestamp < cache[lruIndex].timestamp) {
                lruIndex = i;
            }
        }
        free(cache[lruIndex].data); // Evict LRU record.
    } else size++;

    end = (end + 1) % MAX_CACHE_SIZE;
    start = (start + 1) % MAX_CACHE_SIZE;
    updateRecord(end, data);
}

void* getRecord(int key) {
    for (int i = 0; i < size; ++i) {
        int index = (start + i) % MAX_CACHE_SIZE;
        if (cache[index].key == key) {
            updateRecord(index, cache[index].data); // Update record to make it more recently used.
            return cache[index].data;
        }
    }

    // If not in the cache.
    void* data = malloc(sizeof(void*)); // Allocate memory for new data.
    addRecord(key, data); // Add record to cache.
    return data;
}
```
