['Here's an example of how this could be done in C:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>
#include <assert.h>

typedef struct {
    _Atomic long offset;
    int key;
} record_t;

static atomic_uint size = 0;
static atomic_int capacity = 0;
static record_t *records = NULL;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
FILE* logfile = NULL;

void initialize(const char* filename, int max_size) {
    records = malloc(max_size * sizeof(record_t));
    assert(records != NULL);

    capacity = max_size;

    logfile = fopen(filename, "a");
    assert(logfile != NULL);
}

int allocate() {
    pthread_mutex_lock(&mutex);

    if (atomic_load(&size) < atomic_load(&capacity)) {
        int index = atomic_fetch_add(&size, 1);

        fprintf(logfile, "Allocation successful. Current size: %d\n", atomic_load(&size));
        pthread_mutex_unlock(&mutex);

        return index;
    } else {
        fprintf(logfile, "Allocation failed. Reached maximum capacity.\n");
        pthread_mutex_unlock(&mutex);

        return -1;
    }
}

void deallocate() {
    pthread_mutex_lock(&mutex);

    if (atomic_load(&size) > 0) {
        atomic_fetch_sub(&size, 1);

        fprintf(logfile, "Deallocation successful. Current size: %d\n", atomic_load(&size));
    } else {
        fprintf(logfile, "Deallocation failed. Already empty.\n");
    }

    pthread_mutex_unlock(&mutex);
}

void finalize() {
    free(records);
    fclose(logfile);
}
```
This example uses the POSIX thread library for thread safety and atomic operations to minimize bottlenecks. The `initialize` function is responsible for initializing memory and opening the log file, while `allocate` and `deallocate` manage dynamic allocation and deallocation of records respectively.

