void *g_malloc(size_t size) {
    g_mutex_lock(&mutex);
    void *ptr = malloc(size);
    g_mutex_unlock(&mutex);
    return ptr;
}

void *g_realloc(void *mem, size_t size) {
    g_mutex_lock(&mutex);
    void *ptr = realloc(mem, size);
    g_mutex_unlock(&mutex);
    return ptr;
}

void g_free(void *mem) {
    g_mutex_lock(&mutex);
    free(mem);
    g_mutex_unlock(&mutex);
}

