vtable.malloc = &g_malloc;
vtable.realloc = &g_realloc;
vtable.free = &g_free;

// Custom thread-safe memory allocator and deallocator
void *custom_mem_alloc(size_t size) {
    return g_mem_alloc(&vtable, size);
}

void custom_mem_dealloc(void *ptr) {
    if (ptr != NULL) {
        g_mem_free(&vtable, ptr);
    }
}

