["```php
class UserService {
    private $logger;
    private $passwordPolicyValidator;
    private $messageBroker;
    private $cacheLayer;
    private $emailNotifier;

    public function __construct($distributedLogger, $policyValidator, $msgBroker, $cachingService, $notification) {
        $this->logger = $distributedLogger;
        $this->passwordPolicyValidator = $policyValidator;
        $this->messageBroker = $msgBroker;
        $this->cacheLayer = $cachingService;
        $this->emailNotifier = $notification;
    }

    public function updatePassword($userId, $newPassword) {
        try {
            $user = $this->cacheLayer->getUserData($userId);
            if (!$user) { // Cache miss, fetch from DB
                $user = User::findOrFail($userId);
                $this->cacheLayer->updateCache($user);
            }

            $validationResponse = $this->passwordPolicyValidator->validatePassword($newPassword);

            if ($validationResponse['success']) {
                $oldPasswordHash = $user->password;
                $user->password = password_hash($newPassword, PASSWORD_DEFAULT);

                DB::transaction(function () use ($user) {
                    $user->saveOrFail();
                });

                $this->logger->log('INFO', 'User password updated successfully.');
                $response = ['success' => true, 'message' => 'Password updated.'];
            } else {
                $this->logger->log('ERROR', 'Failed to update user password. Invalid password: '.$validationResponse['error']);
                $response = ['success' => false, 'message' => $validationResponse['error']];
            }

            $this->emailNotifier->notifyPasswordUpdate($user); // Async notifications
        } catch (Exception $e) {
            $this->logger->log('ERROR', 'Failed to update user password: '.$e->getMessage());
            $response = ['success' => false, 'message' => $e->getMessage()];
        } finally {
            // Notify message broker of the operation outcome
            $this->messageBroker->publish('user.passwordUpdate', $response);
            return $response;
        }
    }
}
```
