#include <stdlib.h>
#include <time.h>

typedef struct record {
    int value;
} record_t;

// A simple hashmap implementation for key uniqueness check
typedef struct hash_node{
    long key;
    int value;
    struct hash_node *next;
}hash_node;

record_t **allocate_memory(long maxOffsetLimit, 
                           long maxKeyLimit,
                           int minRecordValue,
                           int maxRecordValue,
                           long* totalSize) {
    // Assuming that we have get_external_data function which provides an external data source for record values.
    *totalSize = 0;
    long numRecords = (maxOffsetLimit < maxKeyLimit)? maxOffsetLimit: maxKeyLimit;

    // Validate the limits and fail-safe if they are too low to accommodate required elements.
    if(numRecords <= 0){
        printf("Error: Limits are too low.\n");
        return NULL;
    }

    // Allocate memory for offsets array
    long *offsets = (long*)malloc(sizeof(long) * numRecords);
    if(!offsets){
        printf("Error: Memory allocation failed for offsets.\n");
        return NULL;
    }

    // Initialize the offsets array with unique, non-negative values.
    for(int i = 0; i < numRecords; i++) {
        offsets[i] = abs((long)rand());
    }
    *totalSize += sizeof(long)*numRecords;  // Update total size allocated

    // Allocate memory for keys array, ensuring no two keys are the same.
    int *keys = (int*)malloc(sizeof(int) * numRecords);
    if(!keys){
        printf("Error: Memory allocation failed for keys.\n");
        free(offsets);  // Cleanup memory allocated earlier in case of failure
        return NULL;
    }

    // Initialize the hashmap and ensure no two keys are the same.
    hash_node* hashTable[numRecords];
    for(int i = 0; i < numRecords; ++i) {
      long key = abs((long)rand());
      hash_node *newNode = (hash_node *) malloc(sizeof(hash_node));
      newNode->key = key;
      int hashIndex = key % numRecords;
      newNode->next = hashTable[hashIndex];
      hashTable[hashIndex] = newNode;
    }

    // Allocate memory for records array and initialize with random values.
    record_t **records = (record_t**)malloc(sizeof(record_t*) * numRecords);
    if(!records){
        printf("Error: Memory allocation failed for records.\n");
        free(offsets);  // Cleanup memory allocated earlier in case of failure
        free(keys);     // Cleanup memory allocated earlier in case of failure
        return NULL;
    }

    srand(time(0));
    for(int i = 0; i < numRecords; ++i) {
      record_t *newRecord = (record_t *) malloc(sizeof(record_t));
      newRecord->value = rand() % maxRecordValue + minRecordValue;
      ++totalSize += sizeof(record_t);  // Update total size allocated
    }

    return records;
}
```
This function uses dynamic memory allocation to create `offsets`, `keys` and `records` arrays. It also uses a simple hashmap for efficient checking of key uniqueness. The randomness generation is done using the standard `rand()` function. If any memory allocation fails, it frees all previously allocated memory before returning NULL to signal failure.
