['Here is an example implementation using standard C libraries for reading from files and zlib library for handling compressed files. It assumes that the file format is each line contains `int`, `double`, and `const char*` separated by space. Also, it uses a simple mechanism to handle parsing errors and missing values: if any field is missing or cannot be parsed correctly, it's set to some default value (0 for int and double, null for string).

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "zlib.h"

typedef struct data {
    int field_int;
    double field_double;
    const char* field_str;
} Data;

// Function to handle file line by line
Data *read_line(FILE *file, gzFile gzipped_file) {
    char buffer[256];
    int read = (gzipd_file == NULL) ? fscanf(file, "%s", buffer) : gzgets(gzipped_file, buffer);

    if (read == EOF || strcmp(buffer, "\n") == 0) {
        return NULL;
    }

    Data *data = malloc(sizeof(Data));
    data->field_str = malloc(strlen(buffer + 1)); // +1 for null terminator

    if (sscanf(buffer, "%d %lf %s", &(data->field_int), &(data->field_double), data->field_str) != 3) {
        // Handle parsing error or missing values
        data->field_int = 0;
        data->field_double = 0.0;
        strcpy((char*)data->field_str, "");
    }

    return data;
}

// Function to read the entire file into an array of Data pointers
Data **read_file(const char *filename) {
    FILE *file = fopen(filename, "r");
    gzFile gzipd_file = NULL;

    // Check if it is a compressed file
    if (strstr(filename, ".gz")) {
        gzipd_file = gzopen(filename, "rb");
    } 

    Data **data_array = malloc(sizeof(Data*));
    int array_capacity = 1;

    for (int i = 0; ; i++) {
        Data *line = read_line(file, gzipd_file);

        if (line == NULL) {
            break;
        }

        // Add more space if necessary
        if (i >= array_capacity) {
            array_capacity *= 2;
            data_array = realloc(data_array, sizeof(Data*) * array_capacity);
        }

        data_array[i] = line;
    }

    // Close files if any
    if (file) fclose(file); 
    if (gzipd_file) gzclose(gzipped_file);

    return data_array;
}
```
The code above is a simplified version and may require more error checking, optimizations, and adaptations for the specific use case. For example, you might want to handle large files that cannot fit into memory by processing them in chunks instead of loading all of them into memory at once. 

Also, this implementation assumes each line contains exactly three fields separated by spaces: an int, a double, and a string without any embedded space characters within the string. If your file format is more complex, you might need to use a more sophisticated parsing strategy. 

Finally, it only supports gzip compressed files. For other formats like bz2 or xz, you would have to add extra libraries and implement similar functions as `gzgets` and `gzopen` for each new format. This code doesn't handle errors when opening the file which is a best practice to consider in real-world software development.
']

