['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <sys/stat.h>
#include <errno.h>
#include <time.h>

#define MAX_RETRIES 3 // configurable limit for retries

typedef struct metadata {
    char filename[256];
    off_t size;
    time_t timestamp;
} Metadata;

typedef struct node {
    Metadata data;
    struct node *next;
} Node;

Node* create_node(Metadata meta) {
    Node *new_node = (Node*) malloc(sizeof(Node));
    if (new_node == NULL) return NULL;

    new_node->data = meta;
    new_node->next = NULL;
    return new_node;
}

void add_metadata(Node **head, Metadata data) {
    Node *new_node = create_node(data);
    if (*head == NULL) {
        *head = new_node;
        return;
    }

    Node *curr = *head;
    while (curr->next != NULL) curr = curr->next;
    curr->next = new_node;
}

void free_list(Node **head) {
    Node *current = *head, *next;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    *head = NULL;
}

int batch_image_converter(const char* sourceDir, const char* logFilePath) {
    FILE *logfile = fopen(logFilePath, "a");
    if (logfile == NULL) return 1; // log error opening the log file

    DIR *dirp = opendir(sourceDir);
    if (dirp == NULL) {
        fprintf(logfile, "Unable to open directory: %s\n", strerror(errno));
        return 1; // unable to open the specified directory
    }

    struct dirent *entry;
    Node *head = NULL;
    int processed_files = 0;
    while ((entry = readdir(dirp)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) continue;

        time_t startTime = time(NULL);
        Metadata meta;
        strncpy(meta.filename, entry->d_name, sizeof(meta.filename));

        char sourcePath[4096]; // maximum path length allowed by the system
        sprintf(sourcePath, "%s/%s", sourceDir, entry->d_name);
        struct stat st;
        if (stat(sourcePath, &st) != 0 || !S_ISREG(st.st_mode)) { // skip directories and non-regular files
            fprintf(logfile, "Skipping %s: not a regular file\n", sourcePath);
            continue;
        }

        meta.size = st.st_size;
        meta.timestamp = st.st_mtime;

        char command[4096];
        sprintf(command, "convert %s %s.png", sourcePath, sourcePath); // using a third-party command-line tool named 'convert'
        int retry = 0;
        while (system(command) != 0 && retry < MAX_RETRIES) {
            fprintf(logfile, "Conversion failed for %s. Retry attempt: %d\n", sourcePath, retry+1);
            ++retry;
        }

        if (retry == MAX_RETRIES) { // conversion failure after maximum retries
            fprintf(logfile, "Failed to convert %s after %d attempts\n", sourcePath, MAX_RETRIES);
        } else {
            ++processed_files;
            add_metadata(&head, meta);
        }

        time_t endTime = time(NULL);
        fprintf(logfile, "Processing of %s completed. Start Time: %ld, End Time: %ld\n", sourcePath, startTime, endTime);
    }

    fprintf(logfile, "Total files processed: %d\n", processed_files);
    free_list(&head);
    fclose(logfile);
    closedir(dirp);
    return 0; // success
}
```
This code uses a linked list to store metadata of each file. Memory is allocated for each node during its creation, so no memory is allocated beforehand for all files in the directory. This minimizes memory usage and avoids potential errors due to allocation failures. Error handling strategy includes retrying conversion up to a configurable limit on failed conversions. Logging mechanism logs details of processing, any conversion errors and skipped non-regular files. Error messages are detailed and written to a separate log file for future debugging purposes. The function handles edge cases such as empty directories, non-existent source directories and incorrect file permissions by checking the return values of system calls and logging appropriate error messages. It ensures all memory is freed appropriately upon exit.
']

