    srand((unsigned int) time(NULL));

    // Allocating memory for coordinates and indices
    float* x = (float*) malloc(gridSize * sizeof(float));
    float* y = (float*) malloc(gridSize * sizeof(float));
    short* indices = (short*) calloc(gridSize, sizeof(short));

    // Checking if allocation was successful
    if (!x || !y || !indices) {
        free(x);
        free(y);
        free(indices);
        return NULL;
    }

    geometry** grid = (geometry**) malloc(gridSize * sizeof(geometry*));

    // Checking if allocation was successful
    if (!grid) {
        free(x);
        free(y);
        free(indices);
        return NULL;
    }

    for (int i = 0; i < gridSize; ++i) {
        x[i] = rand() % 100; // Random values
        y[i] = rand() % 100; // Random values

        geometry* g = (geometry*) malloc(sizeof(geometry));

        // Checking if allocation was successful
        if (!g) {
            for (int j = 0; j < i; ++j)
                free(grid[j]);
            free(x);
            free(y);
            free(indices);
            return NULL;
        }

        g->x = x[i];
        g->y = y[i];
        g->index = indices[i] = i;
        g->ptr_index = &indices[i];

        grid[i] = g;
    }

    // Assuming the function `createBST` is available 
