#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct TTY_EVENT_RECORD {
    char sessionID[20];  // Assuming session IDs are strings with maximum length of 19 chars
    time_t timestamp;
    int severityLevel;
    char eventType[30];  // Assuming event types are strings with max length of 29 chars
    unsigned long hash;
} TTY_EVENT_RECORD;

typedef struct Node {
    TTY_EVENT_RECORD data;
    struct Node* next;
    struct Node* prev;
} Node;

Node *head = NULL;
pthread_mutex_t lock;

void insert(TTY_EVENT_RECORD record) {
    // Critical section - thread safety
    pthread_mutex_lock(&lock);

    Node* new_node = (Node*) malloc(sizeof(Node));
    if(new_node == NULL) exit(-1);  // Exit if memory allocation failed

    new_node->data = record;
    new_node->next = head;

    if (head != NULL) {
        head->prev = new_node;
    }

    head = new_node;

    // Release lock 
    pthread_mutex_unlock(&lock);
}

TTY_EVENT_RECORD retrieve(unsigned long hash) {
    Node* temp = head;
    while(temp != NULL && temp->data.hash != hash) {
        temp = temp->next;
    }

    if(temp == NULL) {
        printf("Record not found\n");
        exit(-1);  // Exit if record not found
    }

    return temp->data;
}

void cleanup() {
    Node* current = head;
    Node* next;

    while (current != NULL) {
       next = current->next;
       free(current); 
       current = next;
    }

    head = NULL;
}
```
