        free(offset);
        free(key);
        free(record);
        return NULL;
    }

    // Initializing offset and key arrays with consecutive integers
    for (int i = 0; i < offsetSize; ++i) 
        offset[i] = i;

    for (int i = 0; i < keySize; ++i) 
        key[i] = i;

    srand(time(NULL)); // Initializing the random number generator
    int range_min = 0, range_max = 1 << 30; // Range of integers

    for (int i = 0; i < recordSize; ++i) {
        pthread_mutex_lock(&record[i].mutex); // Locking the mutex to ensure thread-safety

        // Generating a random integer within range
        int randNum = ((long long)rand() * RAND_MAX + rand()) % (range_max - range_min + 1) + range_min;

        if (randNum > INT_MAX || randNum < INT_MIN){ 
