```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h> // For synchronization primitives

// Define the enum for statuses
typedef enum {PENDING, PROGRESS, COMPLETE} Status;

// Define the task object structure
typedef struct Task {
    char* name;
    int priority;
    Status status;
} Task;

// Define a dynamic list structure to manage memory for tasks
typedef struct DynamicList {
    Task* tasks;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex; // Synchronization primitive
} DynamicList;

// Initialize the list with a given initial capacity
DynamicList* initialize(size_t initialCapacity) {
    DynamicList* list = malloc(sizeof(DynamicList));
    if (list == NULL) return NULL;

    list->capacity = initialCapacity;
    list->size = 0;
    list->tasks = calloc(initialCapacity, sizeof(Task));

    // Initialize synchronization primitive
    pthread_mutex_init(&list->mutex, NULL);

    return list;
}

// Generate a unique task name based on an index and a template
void setName(char** namePtr, const char* template, size_t index) {
    // Allocate memory for the new string
    *namePtr = malloc(strlen(template) + 20);
    if (*namePtr == NULL) return;

    sprintf(*namePtr, "%s%lu", template, index);
}

// Add a task to the list with an initial priority level and status
void addTask(DynamicList* list, const char* nameTemplate, int initialPriority) {
    // Lock the list for synchronized access
    pthread_mutex_lock(&list->mutex);

    if (list->size == list->capacity) {
        // Grow the task array when necessary
        list->tasks = realloc(list->tasks, 2 * list->capacity * sizeof(Task));
        if (list->tasks == NULL) return;

        list->capacity *= 2;
    }

    // Set the task properties
    setName(&list->tasks[list->size].name, nameTemplate, list->size);
    list->tasks[list->size].priority = initialPriority;
    list->tasks[list->size].status = PENDING;

    // Update the size of the task list
    list->size++;

    pthread_mutex_unlock(&list->mutex);
}
```
This is just a skeleton code, please note that it does not include error checking and logging which are essential for production level code. The code also assumes use of POSIX threads for thread synchronization. 

The function `addTask` uses a mutex to ensure thread safety. It checks if there's space in the list, if necessary it allocates more memory, sets task properties and finally unlocks the list again. 

Remember to always free all allocated resources after use to prevent memory leaks. In this case you could include code to free the name strings as well as the tasks array when done with them. Also remember to destroy the mutex using `pthread_mutex_destroy(&list->mutex)` when you're done with it.
