typedef struct MemoryPool {
    pthread_mutex_t lock;
    pthread_cond_t cond;
    int size; 
    void *startAddress;
    void *currentPointer;
} MemoryPool;

MemoryPool memoryPool;

void* allocateFromPool(size_t size) {
    pthread_mutex_lock(&memoryPool.lock);

    while (memoryPool.currentPointer + size > memoryPool.startAddress + memoryPool.size) {
        /* Wait for memory to be released */
        pthread_cond_wait(&memoryPool.cond, &memoryPool.lock);
    }

    void *block = memoryPool.currentPointer;
    memoryPool.currentPointer += size;

    pthread_mutex_unlock(&memoryPool.lock);
    return block;
}
```
