Here is an example of how you could implement a simple lock-free queue:

```cpp
#include <atomic>

template<typename T>
class LockFreeQueue {
private:
    struct Node {
        T data;
        Node* next;
        Node(T const& data_) : data(data_), next(nullptr) {}
    };

    std::atomic<Node*> head;
    std::atomic<Node*> tail;

public:
    void push(T const& data) {
        Node* new_node = new Node(data); // Avoids the issue of exception safety
        Node* old_tail = tail.load();
        while(!tail.compare_exchange_weak(old_tail, new_node));
    }
};
```

This is a simplified version and doesn't handle all corner cases (e.g., when the queue is empty). For full implementation, you should take into account ABA problem and also consider how to manage memory for nodes that are not in use anymore. 

