['Below are the classes for decryption, logging service, API call handler, and the main function. Please replace "your_logger" with your actual logger instance. 

```csharp
using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Net.Http;
using Newtonsoft.Json;
using Polly;

public class DecryptionService
{
    private readonly ILogger _logger;
    private readonly string _encKey;
    private readonly string _hmacSecret;
    private readonly HttpClient _httpClient = new HttpClient();

    public DecryptionService(ILogger logger, string encKey, string hmacSecret)
    {
        this._logger = logger;
        this._encKey = encKey;
        this._hmacSecret = hmacSecret;
    }

    public async Task<Tuple<string, bool>> DecryptAndVerifyAsync(byte[] cipherText, byte[] iv)
    {
        var decryptedBytes = await this.DecryptWithRetryAsync(cipherText, iv);

        // Assume the external API returns a JSON object with a "signature" field. 
        var metadataJson = await Policy
            .Handle<HttpRequestException>()
            .WaitAndRetryForeverAsync(_ => TimeSpan.FromSeconds(10), (ex, time) => 
                this._logger.LogError("Failed to fetch metadata: " + ex))
            .ExecuteAsync(() => _httpClient.GetStringAsync("https://api.example.com/metadata"));

        var metadata = JsonConvert.DeserializeObject<dynamic>(metadataJson);

        var isValidSignature = 
            this.VerifyHMAC(decryptedBytes, Convert.FromBase64String((string)metadata.signature));

        return new Tuple<string, bool>(Encoding.UTF8.GetString(decryptedBytes), isValidSignature);
    }

    private async Task<byte[]> DecryptWithRetryAsync(byte[] cipherText, byte[] iv) =>
        await Policy
            .Handle<CryptographicException>()
            .WaitAndRetryForeverAsync(_ => 
                TimeSpan.FromSeconds(10), (ex, time) => this._logger.LogError("Decryption failed: " + ex))
            .ExecuteAsync(() => this.Decrypt(cipherText, iv));

    private byte[] Decrypt(byte[] cipherText, byte[] iv)
    {
        using var aes = Aes.Create();
        aes.Key = Convert.FromBase64String(_encKey);
        aes.IV = iv;
        aes.Padding = PaddingMode.PKCS7;
        aes.Mode = CipherMode.CBC;

        var decryptor = aes.CreateDecryptor(aes.Key, aes.IV);
        using var memoryStream = new MemoryStream(cipherText);
        using var cryptoStream = new CryptoStream(memoryStream, decryptor, CryptoStreamMode.Read);

        using var outputStream = new MemoryStream();
        cryptoStream.CopyTo(outputStream);

        return outputStream.ToArray();
    }

    private bool VerifyHMAC(byte[] data, byte[] signature)
    {
        using var hmac = new HMACSHA256(Convert.FromBase64String(_hmacSecret));
        var computedSignature = hmac.ComputeHash(data);

        return signature.SequenceEqual(computedSignature);
    }
}

public interface ILogger
{
    void LogError(string message);
}
```
Please note, this is a basic implementation and does not handle all potential edge cases or real-world complexities you might encounter in a production environment. For instance, it does not support asynchronous logging, which can be an issue if your logger is not thread-safe. Also, the `DecryptionService` class does not contain error handling for JSON deserialization or HMAC signature comparison, and it also doesn't handle cases where ciphertext length is less than block size of AES algorithm. It should be expanded based on real needs.
