    size_t size;
    void *start;
} MemoryPool;

// Global memory pool and its mutex
MemoryPool global_pool = { PTHREAD_MUTEX_INITIALIZER, 0, NULL };

// Function to resize memory pool
void* resize_memory_pool(size_t new_size) {
    void *new_start;

    pthread_mutex_lock(&global_pool.lock);

    // Allocate new memory block
    new_start = malloc(new_size);
    if (new_start == NULL) {
        return NULL;
    }

    // Copy data from old to new
    memcpy(new_start, global_pool.start, global_pool.size);

    // Free old memory block
    free(global_pool.start);

    // Update global pool
    global_pool.start = new_start;
    global_pool.size = new_size;

    pthread_mutex_unlock(&global_pool.lock);

    return new_start;
}

