['Here is how you can create this C function `manage_records`:

```c
#include <stdio.h>
#include <stdlib.h>

typedef struct {
    long* offset;
    int key;
} record;

int manage_records(record** records, size_t n) {
    // Allocate memory for the array of `record` structures
    *records = malloc(n * sizeof(record));
    if (*records == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        return -1;  // Indicate error
    }

    for (size_t i = 0; i < n; ++i) {
        // Allocate memory for the `long` value in each record
        long* offset = malloc(sizeof(long));
        if (offset == NULL) {
            fprintf(stderr, "Memory allocation failed.\n");
            // If a single allocation fails, de-allocate all previously allocated memory 
            for (size_t j = 0; j < i; ++j) {
                free((*records)[j].offset);
            }
            free(*records);  // De-allocate the array of records
            *records = NULL;  // Prevent dangling pointers
            return -1;  // Indicate error
        }

        *offset = 0;  // Initialize offset to zero
        (*records)[i].key = i;  // Initialize key sequentially starting from 0
        (*records)[i].offset = offset;  // Assign the pointer to the dynamically allocated value
    }

    return 0;  // Indicate success
}
```

This function uses error handling to ensure that all dynamically allocated memory is freed when an allocation failure occurs, thus preventing a potential crash due to a failed memory allocation. The use of `free` ensures that any previously allocated records are de-allocated and also the array of records itself in case of any allocation failures.

