double generateRandomDouble(PRNG* prng) {
    return ((double)rand() / (double)RAND_MAX) * (prng->max - prng->min) + prng->min;
}

int generateRandomInt(PRNG* prng) {
    return rand() % (prng->max - prng->min + 1) + prng->min;
}

char* PRNGToString(PRNG* prng) {
