    if (size <= 0 || size > SIZE_MAX / sizeof(Record)) {
        fprintf(stderr, "Invalid record size.\n");
        return NULL;
    }

    Record* records = malloc(size * sizeof(Record));
    if (!records) {
        perror("malloc() failed.");
        return NULL;
    }

    srand((unsigned int)time(NULL)); // seed PRNG with current time

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    clock_t startTime = clock();

    PRNG prngDouble = {0, 10};
    PRNG prngInt = {-100, 100};

    for (size_t i = 0; i < size; ++i) {
        pthread_mutex_lock(&lock); // thread-safe operation

        records[i].offset = generateRandomLong();
        records[i].key = generateRandomInt(&prngInt);
        records[i].precision = generateRandomDouble(&prngDouble);

        pthread_mutex_unlock(&lock); // release lock
    }

    clock_t endTime = clock(); 
    double timeTaken = (double)(endTime - startTime) / CLOCKS_PER_SEC;

    printf("Random value generation took %.2f seconds.\n", timeTaken);

