    if (root == NULL) 
        root = create_node(val,key);
    else if (key < root->key) {
        root->left  = insert_node(root->left, val, key);
        root->left->parent = root;
    } else if (key > root->key) {
        root->right = insert_node(root->right, val, key);
        root->right->parent = root;
    }
    return root;
}

void inorder_traversal(Node *n, char **array, int *index) {
    if (n != NULL) {
        inorder_traversal(n->left, array, index);
        array[*index] = n->value;
        (*index)++;
        inorder_traversal(n->right, array, index);
    }
}

char** get_values(Node *root, int size) {
    char **array = (char**)malloc(size*sizeof(char*));
    if(array == NULL){ 
        printf("Memory allocation failed!\n"); 
        exit(1); 
    }
    int index = 0;
    inorder_traversal(root, array, &index);
    return array;
}
```
In a real-world application, you'd want to handle memory deallocation and data consistency issues, potentially using mutex locks for concurrency control. You'll also likely need a strategy for balancing the tree (e.g., AVL trees), possibly with a function for rebalancing after each insertion or removal operation. Further optimizations could involve lazy loading of node values from external sources and maintaining a balance factor to reduce the time complexity of insertions and deletions in the AVL tree.
