['Here's a basic solution using POSIX threads for thread safety, and logging via syslog. Please note that this is a simplified example without real-world use cases, it's just an illustrative solution of how you can approach this task. 

```c
#include <stdlib.h>
#include <string.h>
#include <syslog.h>
#include <pthread.h>

#define ARRAY_SIZE 1000

typedef struct {
    int value;
    char string[16];
    double floatValue;
} Record;

typedef struct {
    long* offsets;
    int* keys;
    pthread_mutex_t* mutexes;
    Record* records;
} MemoryState;

MemoryState state;

void logError(const char *message) {
    openlog("app", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_ERR, "%s", message);
    closelog();
}

void initializeRecords() {
    state.offsets = calloc(ARRAY_SIZE, sizeof(long));
    if (state.offsets == NULL) {
        logError("Failed to allocate offsets memory");
        exit(-1);
    }

    state.keys = calloc(ARRAY_SIZE, sizeof(int));
    if (state.keys == NULL) {
        logError("Failed to allocate keys memory");
        free(state.offsets);
        exit(-1);
    }

    state.mutexes = malloc(sizeof(pthread_mutex_t) * ARRAY_SIZE);
    if (state.mutexes == NULL) {
        logError("Failed to allocate mutex memory");
        free(state.offsets);
        free(state.keys);
        exit(-1);
    }

    state.records = calloc(ARRAY_SIZE, sizeof(Record));
    if (state.records == NULL) {
        logError("Failed to allocate records memory");
        free(state.offsets);
        free(state.keys);
        free(state.mutexes);
        exit(-1);
    }

    for (int i = 0; i < ARRAY_SIZE; ++i) {
        pthread_mutex_init(&state.mutexes[i], NULL);
    }
}

void* generateRecord(void *arg) {
    long index = (long) arg;

    int key, i = 0;
    do {
        if (++i > 10) {
            logError("Failed to generate unique key");
            exit(-1);
        }

        key = rand() % 1000; // generate random keys between 0 and 999
    } while(state.keys[key] != 0);

    state.mutexes[index].lock();
    state.records[index].value = rand() % 1000;
    for (int i = 0; i < 16; ++i) {
        state.records[index].string[i] = 'a' + rand() % ('z' - 'a'); // generate random strings between a and z
    }
    state.records[index].floatValue = (double)(rand() % 2000) / 10 - 10; // generate random doubles between -10 and 10

    state.keys[key] = 1;
    state.offsets[index] = index;
    state.mutexes[index].unlock();
}

int main() {
    initializeRecords();

    pthread_t threads[ARRAY_SIZE];

    for (long i = 0; i < ARRAY_SIZE; ++i) {
        if (pthread_create(&threads[i], NULL, generateRecord, (void*) i)) {
            logError("Failed to create thread");
            exit(-1);
        }
    }

    for (int i = 0; i < ARRAY_SIZE; ++i) {
        if(pthread_join(threads[i], NULL)) {
            logError("Failed to join thread");
            exit(-1);
        }
    }

    free(state.offsets);
    free(state.keys);
    for (int i = 0; i < ARRAY_SIZE; ++i) {
        pthread_mutex_destroy(&state.mutexes[i]);
    }
    free(state.records);
}
``` 

This solution doesn't handle error cases in generating the records, and it assumes that the maximum key value is less than `ARRAY_SIZE` (which might be too large). It also uses a simple mutex for every record to ensure thread safety, which might not scale well with large numbers of threads.
